// Offline Cache Manager for Chapters
class OfflineCacheManager {
    constructor() {
        this.cacheName = 'devnovels-chapters-offline';
        this.downloadQueue = [];
        this.isDownloading = false;
        this.currentProgress = 0;
        this.totalToDownload = 0;
        this.downloadId = null;
    }

    async cacheChapter(novelSlug, chapterNum) {
        try {
            const url = `/chapter/${novelSlug}/${chapterNum}`;
            const response = await fetch(url);
            if (response.ok) {
                const cache = await caches.open(this.cacheName);
                await cache.put(url, response);
                return true;
            }
            return false;
        } catch (error) {
            console.error(`Failed to cache chapter ${chapterNum}:`, error);
            return false;
        }
    }

    async cacheChapters(novelSlug, chapters, onProgress) {
        this.isDownloading = true;
        this.currentProgress = 0;
        this.totalToDownload = chapters.length;

        const results = { success: 0, failed: 0, total: chapters.length };

        for (let i = 0; i < chapters.length; i++) {
            const success = await this.cacheChapter(novelSlug, chapters[i]);
            if (success) results.success++; else results.failed++;
            this.currentProgress = i + 1;
            if (onProgress) {
                onProgress({
                    current: this.currentProgress,
                    total: this.totalToDownload,
                    percent: Math.round((this.currentProgress / this.totalToDownload) * 100),
                    success: results.success,
                    failed: results.failed
                });
            }
            await new Promise(resolve => setTimeout(resolve, 100));
        }

        this.isDownloading = false;
        return results;
    }

    async getCachedChapters(novelSlug) {
        try {
            const cache = await caches.open(this.cacheName);
            const keys = await cache.keys();
            return keys
                .map(request => {
                    const url = new URL(request.url);
                    const match = url.pathname.match(/\/chapter\/([^\/]+)\/(\d+)/);
                    if (match && match[1] === novelSlug) return parseInt(match[2]);
                    return null;
                })
                .filter(num => num !== null)
                .sort((a, b) => a - b);
        } catch (error) {
            console.error('Failed to get cached chapters:', error);
            return [];
        }
    }

    async clearCache(novelSlug) {
        try {
            const cache = await caches.open(this.cacheName);
            const keys = await cache.keys();
            let deleted = 0;
            for (const request of keys) {
                const url = new URL(request.url);
                if (url.pathname.includes(`/chapter/${novelSlug}/`)) {
                    await cache.delete(request);
                    deleted++;
                }
            }
            return deleted;
        } catch (error) {
            console.error('Failed to clear cache:', error);
            return 0;
        }
    }

    async getCacheSize() {
        try {
            if ('storage' in navigator && 'estimate' in navigator.storage) {
                const estimate = await navigator.storage.estimate();
                return {
                    used: estimate.usage,
                    quota: estimate.quota,
                    usedMB: (estimate.usage / (1024 * 1024)).toFixed(2),
                    quotaMB: (estimate.quota / (1024 * 1024)).toFixed(2),
                    percentUsed: ((estimate.usage / estimate.quota) * 100).toFixed(1)
                };
            }
        } catch (error) {
            console.error('Failed to get cache size:', error);
        }
        return null;
    }

    async openDB() {
        return new Promise((resolve, reject) => {
            const request = indexedDB.open('OfflineDownloads', 1);
            request.onerror = () => reject(request.error);
            request.onsuccess = () => resolve(request.result);
            request.onupgradeneeded = (event) => {
                const db = event.target.result;
                if (!db.objectStoreNames.contains('downloads')) {
                    db.createObjectStore('downloads', { keyPath: 'id' });
                }
            };
        });
    }

    async startBackgroundDownload(novelSlug, chapters, downloadId) {
        try {
            console.log('[OfflineCache] Starting background download:', downloadId, chapters.length, 'chapters');

            const db = await this.openDB();
            const tx = db.transaction('downloads', 'readwrite');
            const store = tx.objectStore('downloads');
            await new Promise((resolve, reject) => {
                const req = store.put({
                    id: downloadId,
                    novelSlug,
                    chapters,
                    status: 'pending',
                    progress: 0,
                    success: 0,
                    failed: 0,
                    total: chapters.length,
                    createdAt: Date.now()
                });
                req.onsuccess = () => resolve();
                req.onerror = () => reject(req.error);
            });
            db.close();

            const controller = navigator.serviceWorker && navigator.serviceWorker.controller;
            if (controller) {
                // SW is active — let it handle the download in the background
                controller.postMessage({
                    type: 'START_DOWNLOAD',
                    downloadId,
                    novelSlug,
                    chapters
                });
            } else {
                // SW not controlling this page yet — run download directly in page
                console.log('[OfflineCache] No SW controller, running download in-page');
                this._runInPageDownload(novelSlug, chapters, downloadId);
            }

            return downloadId;
        } catch (error) {
            console.error('[OfflineCache] Error starting background download:', error);
            throw error;
        }
    }

    async _runInPageDownload(novelSlug, chapters, downloadId) {
        const cache = await caches.open(this.cacheName);
        let success = 0, failed = 0;

        const notify = async (progress) => {
            // Update IndexedDB so downloads modal can read it
            try {
                const db = await this.openDB();
                const tx = db.transaction('downloads', 'readwrite');
                const store = tx.objectStore('downloads');
                const existing = await new Promise((res, rej) => {
                    const r = store.get(downloadId);
                    r.onsuccess = () => res(r.result);
                    r.onerror = () => rej(r.error);
                });
                if (existing) {
                    await new Promise((res, rej) => {
                        const r = store.put({ ...existing, ...progress });
                        r.onsuccess = () => res();
                        r.onerror = () => rej(r.error);
                    });
                }
                db.close();
            } catch (e) { /* ignore */ }

            // Also fire event for the download modal on same page
            window.dispatchEvent(new CustomEvent('download-progress', {
                detail: { type: 'DOWNLOAD_PROGRESS', downloadId, ...progress }
            }));
        };

        for (let i = 0; i < chapters.length; i++) {
            // Check cancellation via IndexedDB
            try {
                const db = await this.openDB();
                const tx = db.transaction('downloads', 'readonly');
                const store = tx.objectStore('downloads');
                const rec = await new Promise((res, rej) => {
                    const r = store.get(downloadId);
                    r.onsuccess = () => res(r.result);
                    r.onerror = () => rej(r.error);
                });
                db.close();
                if (!rec || rec.status === 'cancelled') {
                    await notify({ progress: i, success, failed, total: chapters.length, status: 'cancelled' });
                    return;
                }
            } catch (e) { /* ignore */ }

            const chapterNum = chapters[i];
            try {
                const url = `/chapter/${novelSlug}/${chapterNum}`;
                const response = await fetch(url);
                if (response.ok) {
                    await cache.put(url, response);
                    success++;
                } else {
                    failed++;
                }
            } catch {
                failed++;
            }

            const progress = { progress: i + 1, success, failed, total: chapters.length, status: 'downloading' };
            if (i % 3 === 0 || i === chapters.length - 1) await notify(progress);
            await new Promise(r => setTimeout(r, 50));
        }

        await notify({ progress: chapters.length, success, failed, total: chapters.length, status: 'completed' });
    }

    async getDownloadStatus(downloadId) {
        try {
            const db = await this.openDB();
            const tx = db.transaction('downloads', 'readonly');
            const store = tx.objectStore('downloads');
            const download = await new Promise((resolve, reject) => {
                const req = store.get(downloadId);
                req.onsuccess = () => resolve(req.result);
                req.onerror = () => reject(req.error);
            });
            db.close();
            return download;
        } catch (error) {
            console.error('[OfflineCache] Error getting download status:', error);
            return null;
        }
    }

    async cancelDownload(downloadId) {
        // Signal SW if active
        if ('serviceWorker' in navigator && navigator.serviceWorker.controller) {
            navigator.serviceWorker.controller.postMessage({
                type: 'CANCEL_DOWNLOAD',
                downloadId
            });
        }
        // Mark as cancelled in IndexedDB (stops in-page download loop too)
        try {
            const db = await this.openDB();
            const tx = db.transaction('downloads', 'readwrite');
            const store = tx.objectStore('downloads');
            const existing = await new Promise((res, rej) => {
                const r = store.get(downloadId);
                r.onsuccess = () => res(r.result);
                r.onerror = () => rej(r.error);
            });
            if (existing) {
                await new Promise((res, rej) => {
                    const r = store.put({ ...existing, status: 'cancelled' });
                    r.onsuccess = () => res();
                    r.onerror = () => rej(r.error);
                });
            }
            db.close();
        } catch (error) {
            console.error('[OfflineCache] Error canceling download:', error);
        }
    }

    async getAllDownloads() {
        try {
            const db = await this.openDB();
            const tx = db.transaction('downloads', 'readonly');
            const store = tx.objectStore('downloads');
            const all = await new Promise((resolve, reject) => {
                const req = store.getAll();
                req.onsuccess = () => resolve(req.result || []);
                req.onerror = () => reject(req.error);
            });
            db.close();
            return all;
        } catch (error) {
            console.error('[OfflineCache] Error getting downloads:', error);
            return [];
        }
    }
}

// Global instance
window.offlineCacheManager = new OfflineCacheManager();

// Request persistent storage so browser doesn't evict offline chapters
if ('storage' in navigator && 'persist' in navigator.storage) {
    navigator.storage.persist().then(granted => {
        console.log('[OfflineCache] Persistent storage:', granted ? 'granted' : 'denied (eviction possible)');
    });
}

// Forward SW messages as custom events
if ('serviceWorker' in navigator) {
    navigator.serviceWorker.addEventListener('message', (event) => {
        if (event.data && event.data.type === 'DOWNLOAD_PROGRESS') {
            window.dispatchEvent(new CustomEvent('download-progress', { detail: event.data }));
        }
    });
}

// Show download modal
function showDownloadModal(novelSlug, novelName, totalChapters) {
    const existing = document.getElementById('downloadModal');
    if (existing) existing.remove();

    const modal = document.createElement('div');
    modal.id = 'downloadModal';
    modal.style.cssText = 'position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,0.9);z-index:10000;display:flex;align-items:center;justify-content:center;padding:20px;';

    const box = document.createElement('div');
    box.style.cssText = 'background:#111;border:1px solid var(--accent-border);border-radius:12px;padding:24px;max-width:480px;width:100%;';
    box.innerHTML = `
        <h2 style="color:var(--accent-primary);margin:0 0 6px;font-size:20px;">📥 Download for Offline</h2>
        <p style="color:rgba(255,255,255,0.6);margin:0 0 20px;font-size:13px;">${novelName}</p>
        <select style="width:100%;padding:10px;background:#000;border:1px solid var(--accent-border);color:#fff;font-size:14px;font-family:inherit;border-radius:6px;margin-bottom:16px;">
            <option value="all">All Chapters (1-${totalChapters})</option>
            <option value="range">Chapter Range</option>
        </select>
        <div class="range-inputs" style="display:none;gap:10px;margin-bottom:16px;">
            <input type="number" class="from-input" min="1" max="${totalChapters}" value="1" placeholder="From" style="flex:1;padding:10px;background:#000;border:1px solid var(--accent-border);color:#fff;font-size:14px;border-radius:6px;">
            <input type="number" class="to-input" min="1" max="${totalChapters}" value="${Math.min(50, totalChapters)}" placeholder="To" style="flex:1;padding:10px;background:#000;border:1px solid var(--accent-border);color:#fff;font-size:14px;border-radius:6px;">
        </div>
        <div class="progress-section" style="display:none;margin-bottom:16px;">
            <div style="display:flex;justify-content:space-between;margin-bottom:6px;">
                <span style="color:rgba(255,255,255,0.6);font-size:13px;">Progress</span>
                <span class="pct-text" style="color:var(--accent-primary);font-size:13px;font-weight:600;">0%</span>
            </div>
            <div style="height:6px;background:rgba(255,255,255,0.1);border-radius:3px;overflow:hidden;">
                <div class="pct-bar" style="height:100%;width:0%;background:var(--accent-primary);transition:width 0.5s ease;"></div>
            </div>
            <div class="pct-details" style="color:rgba(255,255,255,0.5);font-size:12px;margin-top:6px;text-align:center;"></div>
        </div>
        <div style="display:flex;gap:10px;">
            <button class="btn-start" style="flex:1;padding:12px;background:var(--accent-primary);color:#000;border:none;border-radius:6px;font-size:14px;font-weight:600;cursor:pointer;font-family:inherit;">Start Download</button>
            <button class="btn-cancel" style="display:none;padding:12px 16px;background:rgba(239,68,68,0.15);color:#ef4444;border:1px solid rgba(239,68,68,0.4);border-radius:6px;font-size:14px;font-weight:600;cursor:pointer;font-family:inherit;">Cancel</button>
            <button class="btn-close" style="padding:12px 16px;background:rgba(255,255,255,0.08);color:#fff;border:1px solid rgba(255,255,255,0.15);border-radius:6px;font-size:14px;font-weight:600;cursor:pointer;font-family:inherit;">Close</button>
        </div>
    `;

    modal.appendChild(box);
    document.body.appendChild(modal);

    // Local DOM refs - no getElementById
    const select = box.querySelector('select');
    const rangeInputs = box.querySelector('.range-inputs');
    const fromInput = box.querySelector('.from-input');
    const toInput = box.querySelector('.to-input');
    const progressSection = box.querySelector('.progress-section');
    const pctText = box.querySelector('.pct-text');
    const pctBar = box.querySelector('.pct-bar');
    const pctDetails = box.querySelector('.pct-details');
    const btnStart = box.querySelector('.btn-start');
    const btnCancel = box.querySelector('.btn-cancel');
    const btnClose = box.querySelector('.btn-close');

    select.addEventListener('change', () => {
        rangeInputs.style.display = select.value === 'range' ? 'flex' : 'none';
    });

    let currentDownloadId = null;

    btnStart.addEventListener('click', async () => {
        let chapters = [];
        if (select.value === 'all') {
            chapters = Array.from({ length: totalChapters }, (_, i) => i + 1);
        } else {
            const from = parseInt(fromInput.value);
            const to = parseInt(toInput.value);
            if (isNaN(from) || isNaN(to) || from > to) { alert('Invalid range'); return; }
            chapters = Array.from({ length: to - from + 1 }, (_, i) => from + i);
        }

        btnStart.style.display = 'none';
        btnCancel.style.display = 'block';
        progressSection.style.display = 'block';

        try {
            currentDownloadId = 'dl_' + Date.now();
            await window.offlineCacheManager.startBackgroundDownload(novelSlug, chapters, currentDownloadId);

            const onProgress = (e) => {
                if (e.detail.downloadId !== currentDownloadId) return;
                const { progress, success, failed, total, status } = e.detail;
                const pct = total ? Math.round((progress / total) * 100) : 0;
                pctBar.style.width = pct + '%';
                pctText.textContent = pct + '%';
                pctDetails.textContent = `${success || 0} done · ${failed || 0} failed · ${total} total`;

                if (status === 'completed' || status === 'cancelled') {
                    window.removeEventListener('download-progress', onProgress);
                    pctDetails.innerHTML = status === 'completed'
                        ? `<span style="color:#10b981">✓ Done! ${success} chapters cached</span>`
                        : `<span style="color:#ef4444">✗ Cancelled</span>`;
                    btnCancel.style.display = 'none';
                    setTimeout(() => modal.remove(), 2000);
                }
            };

            window.addEventListener('download-progress', onProgress);

        } catch (err) {
            pctDetails.innerHTML = `<span style="color:#ef4444">✗ Error: ${err.message}</span>`;
            btnStart.style.display = 'block';
            btnCancel.style.display = 'none';
        }
    });

    btnCancel.addEventListener('click', async () => {
        if (currentDownloadId) {
            await window.offlineCacheManager.cancelDownload(currentDownloadId);
            pctDetails.innerHTML = '<span style="color:#ef4444">✗ Cancelled</span>';
            btnCancel.style.display = 'none';
            setTimeout(() => modal.remove(), 1500);
        }
    });

    btnClose.addEventListener('click', () => modal.remove());
    modal.addEventListener('click', (e) => { if (e.target === modal) modal.remove(); });
}

window.showDownloadModal = showDownloadModal;

/**
 * Offline Sync Queue
 * Queues failed API writes to IndexedDB, flushes when back online.
 * Persists across refreshes. Auto-flushes on page load + online event.
 */
(function() {
    'use strict';

    const DB_NAME = 'DevNovelsSync';
    const STORE = 'queue';

    function openDB() {
        return new Promise((resolve, reject) => {
            const req = indexedDB.open(DB_NAME, 1);
            req.onerror = () => reject(req.error);
            req.onsuccess = () => resolve(req.result);
            req.onupgradeneeded = (e) => {
                const db = e.target.result;
                if (!db.objectStoreNames.contains(STORE)) {
                    db.createObjectStore(STORE, { keyPath: 'id', autoIncrement: true });
                }
            };
        });
    }

    async function enqueue(url, method, body) {
        try {
            const db = await openDB();
            const tx = db.transaction(STORE, 'readwrite');
            tx.objectStore(STORE).add({ url, method, body, timestamp: Date.now() });
            db.close();
            console.log('[OfflineSync] Queued:', method, url);
        } catch (e) {
            console.warn('[OfflineSync] Failed to enqueue:', e);
        }
    }

    async function flush() {
        if (!navigator.onLine) return;
        try {
            const db = await openDB();
            const tx = db.transaction(STORE, 'readonly');
            const items = await new Promise((res, rej) => {
                const r = tx.objectStore(STORE).getAll();
                r.onsuccess = () => res(r.result);
                r.onerror = () => rej(r.error);
            });
            db.close();

            if (items.length === 0) return;
            console.log('[OfflineSync] Flushing', items.length, 'queued requests...');

            for (const item of items) {
                try {
                    const resp = await fetch(item.url, {
                        method: item.method,
                        headers: { 'Content-Type': 'application/json' },
                        body: item.body ? JSON.stringify(item.body) : undefined
                    });
                    if (resp.ok) {
                        const db2 = await openDB();
                        const tx2 = db2.transaction(STORE, 'readwrite');
                        tx2.objectStore(STORE).delete(item.id);
                        db2.close();
                        console.log('[OfflineSync] Synced:', item.method, item.url);
                    }
                } catch (e) {
                    // Still offline or server error — leave in queue
                }
            }
        } catch (e) {
            console.warn('[OfflineSync] Flush error:', e);
        }
    }

    /**
     * Smart fetch: tries network, queues on failure if it's a write.
     * Returns { ok, data, offline } — callers handle UI accordingly.
     */
    async function syncFetch(url, options = {}) {
        const method = (options.method || 'GET').toUpperCase();
        const isWrite = method !== 'GET';

        try {
            const resp = await fetch(url, options);
            const data = await resp.json().catch(() => ({}));
            return { ok: resp.ok, status: resp.status, data, offline: false };
        } catch (e) {
            if (isWrite && options.body) {
                const body = typeof options.body === 'string'
                    ? JSON.parse(options.body)
                    : options.body;
                await enqueue(url, method, body);
                return { ok: false, offline: true, queued: true, data: {} };
            }
            return { ok: false, offline: true, queued: false, data: {} };
        }
    }

    // Flush on load and when coming back online
    window.addEventListener('online', () => {
        console.log('[OfflineSync] Back online — flushing queue...');
        flush();
    });

    // Flush on page load (catches anything queued in previous sessions)
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', flush);
    } else {
        flush();
    }

    window.offlineSync = { syncFetch, enqueue, flush };
})();

(function() {
    'use strict';
    
    let pixieAgentUnlocked = false;
    let chatOpen = false;
    
    class PixieAgent {
        constructor() {
            this.createUI();
            this.bindEvents();
            this.checkStatus();
            this.initEasterEgg();
        }
        
        initEasterEgg() {
            // Listen for shadow mode discovery
            this.shadowModeDiscovered = localStorage.getItem('shadowModeDiscovered') === 'true';
            
            // Initialize interruption tracking
            this.initInterruptionTracking();
        }
        
        initInterruptionTracking() {
            const today = new Date().toDateString();
            const tracking = JSON.parse(localStorage.getItem('shadowInterruptions') || '{}');
            
            // Reset if new day
            if (tracking.date !== today) {
                tracking.date = today;
                tracking.count = 0;
                tracking.lastInterruption = 0;
            }
            
            this.interruptionTracking = tracking;
            localStorage.setItem('shadowInterruptions', JSON.stringify(tracking));
        }
        
        canInterrupt() {
            const now = Date.now();
            const fourHours = 4 * 60 * 60 * 1000;
            
            // Check daily limit
            if (this.interruptionTracking.count >= 3) {
                console.log('[Shadow Mode] Daily interruption limit reached (3/3)');
                return false;
            }
            
            // Check cooldown
            if (now - this.interruptionTracking.lastInterruption < fourHours) {
                const remaining = Math.ceil((fourHours - (now - this.interruptionTracking.lastInterruption)) / 1000 / 60);
                console.log(`[Shadow Mode] Cooldown active. ${remaining} minutes remaining`);
                return false;
            }
            
            return true;
        }
        
        recordInterruption() {
            this.interruptionTracking.count++;
            this.interruptionTracking.lastInterruption = Date.now();
            localStorage.setItem('shadowInterruptions', JSON.stringify(this.interruptionTracking));
            console.log(`[Shadow Mode] Interruption ${this.interruptionTracking.count}/3 recorded`);
        }
        
        createUI() {
            // Create pixie button (bottom-right corner) - actual pixie sprite
            const button = document.createElement('button');
            button.id = 'pixieAgentButton';
            button.className = 'pixie-agent-button';
            button.setAttribute('aria-label', 'Open Pixie Agent');
            button.innerHTML = `
                <span class="pixie-agent-aura"></span>
                <span class="pixie-agent-body">
                    <span class="pixie-agent-wing pixie-agent-wing-left"></span>
                    <span class="pixie-agent-core"></span>
                    <span class="pixie-agent-wing pixie-agent-wing-right"></span>
                </span>
            `;
            button.style.display = 'none';
            document.body.appendChild(button);
            
            // Check if shadow mode is active
            const isShadowMode = localStorage.getItem('accentColor') === 'shadow' || 
                                 document.body.getAttribute('data-accent') === 'shadow' ||
                                 document.documentElement.getAttribute('data-accent') === 'shadow';
            const pixieName = isShadowMode ? 'Shadow Pixie' : 'Pixie Agent';
            const pixieStatus = isShadowMode ? 'Lurking in shadows' : 'Online';
            const welcomeMessage = isShadowMode 
                ? 'Greetings from the void, seeker of shadows. You have embraced the darkness and earned my allegiance. I am your Shadow Pixie, here to guide you through the mysteries of this realm. Ask, and the shadows shall answer...'
                : 'Greetings, brave challenger! You\'ve defeated me in battle and earned my blessing. I\'m now your Pixie Agent, here to assist you with novel recommendations, reading tips, and answer any questions you have!';
            
            // Create chat popup
            const chatPopup = document.createElement('div');
            chatPopup.id = 'pixieChatPopup';
            chatPopup.className = 'pixie-chat-popup';
            chatPopup.innerHTML = `
                <div class="pixie-chat-header">
                    <div class="pixie-chat-title">
                        <div class="pixie-chat-avatar">
                            <span class="pixie-chat-avatar-aura"></span>
                            <span class="pixie-chat-avatar-body">
                                <span class="pixie-chat-avatar-wing pixie-chat-avatar-wing-left"></span>
                                <span class="pixie-chat-avatar-core"></span>
                                <span class="pixie-chat-avatar-wing pixie-chat-avatar-wing-right"></span>
                            </span>
                        </div>
                        <div>
                            <div class="pixie-name">${pixieName}</div>
                            <div class="pixie-status">${pixieStatus}</div>
                        </div>
                    </div>
                    <div class="pixie-chat-actions">
