        watchAccentChanges() {
            // Watch for localStorage changes
            window.addEventListener('storage', (e) => {
                if (e.key === 'accentColor') {
                    this.updatePixieName();
                }
            });
            
            // Watch for attribute changes on body/html
            const observer = new MutationObserver(() => {
                this.updatePixieName();
            });
            
            observer.observe(document.body, {
                attributes: true,
                attributeFilter: ['data-accent']
            });
            
            observer.observe(document.documentElement, {
                attributes: true,
                attributeFilter: ['data-accent']
            });
        }
        
        updatePixieName() {
            const isShadowMode = localStorage.getItem('accentColor') === 'shadow' || 
                                 document.body.getAttribute('data-accent') === 'shadow' ||
                                 document.documentElement.getAttribute('data-accent') === 'shadow';
            
            const pixieName = isShadowMode ? 'Shadow Pixie' : 'Pixie Agent';
            const pixieStatus = isShadowMode ? 'Lurking in shadows' : 'Online';
            
            // Update name and status in header
            const nameElement = this.popup.querySelector('.pixie-name');
            const statusElement = this.popup.querySelector('.pixie-status');
            
            if (nameElement) nameElement.textContent = pixieName;
            if (statusElement) statusElement.textContent = pixieStatus;
        }
        
        bindEvents() {
            this.button.addEventListener('click', () => this.toggleChat());
            
            // Add shake animation to chat avatar when clicked
            const chatAvatar = this.popup.querySelector('.pixie-chat-avatar');
            if (chatAvatar) {
                chatAvatar.addEventListener('click', () => {
                    chatAvatar.classList.add('shake');
                    setTimeout(() => chatAvatar.classList.remove('shake'), 500);
                });
                chatAvatar.style.cursor = 'pointer';
            }
            
            this.chatForm.addEventListener('submit', async (e) => {
                e.preventDefault();
                await this.sendMessage();
            });
