        async checkStatus() {
            try {
                console.log('[Pixie Agent] Checking status...');
                const response = await fetch('/api/pixie/status');
                const data = await response.json();
                
                console.log('[Pixie Agent] Status response:', data);
                
                if (data.authenticated && data.status) {
                    const currentAccent = localStorage.getItem('accentColor');
                    
                    // Check for shadow departure — runs independently, doesn't block pixie
                    if (data.status.shadow_departed && currentAccent === 'shadow') {
                        console.log('[Pixie Agent] 🌑 Shadow departure detected on load!');
                        if (window.shadowRitual && !window.shadowRitual.isDepartureInProgress) {
                            window.shadowRitual.isDepartureInProgress = true;
                            window.shadowRitual.stopShadowMonitoring();
                            window.shadowRitual.triggerShadowDeparture();
                        }
                    }
                    
                    // Check for shadow grant — runs independently, doesn't block pixie
                    if (data.status.shadow_granted && currentAccent !== 'shadow') {
                        console.log('[Pixie Agent] 🌑 Shadow grant detected on load!');
                        if (window.shadowRitual && !window.shadowRitual.isGrantInProgress) {
                            window.shadowRitual.isGrantInProgress = true;
                            window.shadowRitual.stopShadowMonitoring();
                            window.shadowRitual.triggerShadowGrant();
                        }
                    }
                }
                
                // Always continue with normal pixie agent setup
                if (data.authenticated && data.status && data.status.pixie_agent_unlocked) {
                    console.log('[Pixie Agent] Agent unlocked! Showing button...');
                    pixieAgentUnlocked = true;
                    this.button.style.display = 'flex';
                    await this.loadHistory();
                    await this.sendChapterContext();
                    this.startShadowMonitoring();
                } else {
                    console.log('[Pixie Agent] Agent not unlocked yet. Status:', data.status);
                }
            } catch (error) {
                console.error('[Pixie Agent] Failed to check status:', error);
            }
        }
        
        startShadowMonitoring() {
            // Only monitor if user is currently in shadow mode
            const currentAccent = localStorage.getItem('accentColor');
            if (currentAccent !== 'shadow') return;
            
            if (this.shadowMonitorInterval) return; // Already monitoring
            
            this.shadowMonitorInterval = setInterval(() => {
                const accent = localStorage.getItem('accentColor');
                if (accent !== 'shadow') {
                    this.stopShadowMonitoring();
                    return;
                }
                this.checkShadowDeparture();
            }, 15000);
            console.log('[Pixie Agent] Started shadow departure monitoring');
        }
        
        stopShadowMonitoring() {
            if (this.shadowMonitorInterval) {
                clearInterval(this.shadowMonitorInterval);
                this.shadowMonitorInterval = null;
                console.log('[Pixie Agent] Stopped shadow departure monitoring');
            }
        }
        
        async checkShadowDeparture() {
            try {
                const response = await fetch('/api/pixie/status');
                const data = await response.json();
                
                if (!data.authenticated || !data.status) return;
                
                const currentAccent = localStorage.getItem('accentColor');
                
                // Check for departure (in shadow mode, admin disabled it)
                if (data.status.shadow_departed && currentAccent === 'shadow') {
                    console.log('[Pixie Agent] 🌑 Real-time shadow departure detected!');
                    this.stopShadowMonitoring();
                    if (window.shadowRitual && !window.shadowRitual.isDepartureInProgress) {
                        window.shadowRitual.isDepartureInProgress = true;
                        window.shadowRitual.stopShadowMonitoring();
                        window.shadowRitual.triggerShadowDeparture();
                    }
                }
                
                // Check for grant (not in shadow mode, admin enabled it)
                if (data.status.shadow_granted && currentAccent !== 'shadow') {
                    console.log('[Pixie Agent] 🌑 Real-time shadow grant detected!');
                    this.stopShadowMonitoring();
                    if (window.shadowRitual && !window.shadowRitual.isGrantInProgress) {
                        window.shadowRitual.isGrantInProgress = true;
                        window.shadowRitual.stopShadowMonitoring();
                        window.shadowRitual.triggerShadowGrant();
                    }
                }
            } catch (error) {
                console.error('[Pixie Agent] Failed to check shadow status:', error);
            }
        }
        
        async sendChapterContext() {
            // Check if we're on a chapter page
            const path = window.location.pathname;
            const match = path.match(/\/chapter\/([^\/]+)\/(\d+)/);
            
            if (!match) {
                console.log('[Pixie Agent] Not on chapter page, skipping context send');
                return;
            }
            
            const novelSlug = match[1];
            const chapterNum = match[2];
            
            console.log('[Pixie Agent] Sending chapter context:', novelSlug, chapterNum);
            
            try {
                const response = await fetch('/api/pixie/chapter-context', {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json'
                    },
                    body: JSON.stringify({
                        novel_slug: novelSlug,
                        chapter_num: parseInt(chapterNum)
                    })
                });
                
                const data = await response.json();
                
                if (data.success) {
                    console.log('[Pixie Agent] Chapter context stored successfully');
                } else {
                    console.error('[Pixie Agent] Failed to store chapter context:', data.error);
                }
            } catch (error) {
                console.error('[Pixie Agent] Error sending chapter context:', error);
            }
        }
        
        async loadHistory() {
