        async sendMessage() {
            const message = this.chatInput.value.trim();
            if (!message) return;
            
            // CHEAT CODE: Force trigger cryptic quote for testing
            if (message.toLowerCase() === '!shadowtest') {
                this.chatInput.value = '';
                
                // Check if shadow mode already discovered or enabled
                const shadowDiscovered = localStorage.getItem('shadowModeDiscovered') === 'true';
                const currentAccent = localStorage.getItem('accentColor');
                
                if (shadowDiscovered || currentAccent === 'shadow') {
                    // Already has shadow mode, show normal message
                    this.addMessage('Shadow mode is already active or discovered. The ritual has been completed.', 'assistant');
                    return;
                }
                
                // Show cryptic interruption for testing
                this.showCrypticInterruption();
                return;
            }
            
            // Add user message
            this.addMessage(message, 'user');
            this.chatInput.value = '';
            
            // Check if shadow mode already discovered
            if (this.shadowModeDiscovered) {
                // Normal response - no interruptions
                await this.getNormalResponse(message);
                return;
            }
            
            // Check if can interrupt (15% chance + tracking limits)
            const shouldInterrupt = Math.random() < 0.15 && this.canInterrupt();
            
            // Always give normal response first
            await this.getNormalResponse(message);
            
            if (shouldInterrupt) {
                // Record interruption and append cryptic hint after the real response
                this.recordInterruption();
                setTimeout(() => this.showCrypticInterruption(), 800);
            }
        }
        
        async getNormalResponse(message) {
            // Show typing indicator
            const typingIndicator = this.showTyping();
            
            // Get current page context
            const context = this.getCurrentPageContext();
            
            try {
                const response = await fetch('/api/pixie/chat', {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json'
                    },
                    body: JSON.stringify({ 
                        message,
                        context
                    })
                });
                
                const data = await response.json();
                
                // Remove typing indicator
                typingIndicator.remove();
                
                if (data.success) {
                    // Check for Rune intercept
                    if (data.reply && data.reply.trim() === '[RUNE_INTERCEPT]') {
                        this.addRuneMessage();
                    } else {
                        this.addMessage(data.reply, 'assistant');
                    }
                    
                    // Debug: log which context was used
                    if (data.debug_context_used) {
                        console.log('[Pixie Agent] Context used:', data.debug_context_used);
                    }
                } else {
                    this.addMessage(`Error: ${data.error}`, 'assistant');
                }
            } catch (error) {
                typingIndicator.remove();
                this.addMessage(`Network error: ${error.message}`, 'assistant');
            }
        }
        
        showCrypticInterruption() {
            // Glitch the chat popup
