        getCurrentPageContext() {
            // Try to detect current novel and chapter from URL
            const path = window.location.pathname;
            const match = path.match(/\/chapter\/([^\/]+)\/(\d+)/);
            
            if (match) {
                const novelSlug = match[1];
                const chapterNum = match[2];
                const novelName = novelSlug.replace(/-/g, ' ').replace(/\b\w/g, l => l.toUpperCase());
                
                // Try to get chapter title from page
                const titleElement = document.querySelector('title');
                let chapterTitle = `Chapter ${chapterNum}`;
                if (titleElement) {
                    const titleMatch = titleElement.textContent.match(/^([^-]+)/);
                    if (titleMatch) {
                        chapterTitle = titleMatch[1].trim();
                    }
                }
                
                return {
                    type: 'chapter',
                    novelSlug,
                    novelName,
                    chapterNum,
                    chapterTitle
                };
            }
            
            // Check if on novel page
            const novelMatch = path.match(/\/novel\/([^\/]+)/);
            if (novelMatch) {
                const novelSlug = novelMatch[1];
                const novelName = novelSlug.replace(/-/g, ' ').replace(/\b\w/g, l => l.toUpperCase());
                return {
                    type: 'novel',
                    novelSlug,
                    novelName
                };
            }
            
            return null;
        }
        
