                positions[i3] = Math.random() * 2000 - 1000;
                positions[i3 + 1] = Math.random() * 2000 - 1000;
                positions[i3 + 2] = Math.random() * 2000 - 1000;
                
                // Color - purple/pink gradient
                const mixRatio = Math.random();
                color.setHSL(0.75 + mixRatio * 0.1, 0.8, 0.5 + mixRatio * 0.3);
                colors[i3] = color.r;
                colors[i3 + 1] = color.g;
                colors[i3 + 2] = color.b;
            }
            
            geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
            geometry.setAttribute('color', new THREE.BufferAttribute(colors, 3));
            
            // Create material
            const material = new THREE.PointsMaterial({
                size: 3,
                vertexColors: true,
                transparent: true,
                opacity: 0.8,
                blending: THREE.AdditiveBlending
            });
            
            particles = new THREE.Points(geometry, material);
            scene.add(particles);
            
            // Create renderer
            renderer = new THREE.WebGLRenderer({ alpha: true, antialias: true });
            renderer.setSize(window.innerWidth, window.innerHeight);
            renderer.setPixelRatio(window.devicePixelRatio);
            renderer.setClearColor(0x0a0015, 0);
            
            const canvas = renderer.domElement;
            canvas.style.position = 'fixed';
            canvas.style.top = '0';
            canvas.style.left = '0';
            canvas.style.zIndex = '-1';
            canvas.style.pointerEvents = 'none';
            canvas.id = 'pixie-three-canvas';
            
            document.body.insertBefore(canvas, document.body.firstChild);
            
            // Event listeners
            document.addEventListener('mousemove', onMouseMove);
            window.addEventListener('resize', onWindowResize);
            
            // Watch for theme changes
            const observer = new MutationObserver(() => {
                if (!document.body.classList.contains('pixie-theme')) {
                    cleanup();
                }
            });
            observer.observe(document.body, { attributes: true, attributeFilter: ['class'] });
        }
        
        function onMouseMove(event) {
            mouseX = event.clientX - windowHalfX;
            mouseY = event.clientY - windowHalfY;
        }
        
        function onWindowResize() {
            windowHalfX = window.innerWidth / 2;
            windowHalfY = window.innerHeight / 2;
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        }
        
        function animate() {
            requestAnimationFrame(animate);
            render();
        }
        
        function render() {
            const time = Date.now() * 0.00005;
            
            // Rotate particles
            particles.rotation.x = time * 0.5;
            particles.rotation.y = time * 0.3;
            
            // Wave effect
            const positions = particles.geometry.attributes.position.array;
            
            for (let i = 0; i < particleCount; i++) {
                const i3 = i * 3;
                const x = positions[i3];
                const z = positions[i3 + 2];
                
                // Create wave
                positions[i3 + 1] = Math.sin((x + time * 100) * 0.01) * 50 +
                                    Math.sin((z + time * 100) * 0.01) * 50;
            }
            
            particles.geometry.attributes.position.needsUpdate = true;
            
            // Camera follows mouse
            camera.position.x += (mouseX - camera.position.x) * 0.05;
            camera.position.y += (-mouseY - camera.position.y) * 0.05;
            camera.lookAt(scene.position);
            
            renderer.render(scene, camera);
        }
        
        function cleanup() {
            document.removeEventListener('mousemove', onMouseMove);
            window.removeEventListener('resize', onWindowResize);
            
            if (renderer) {
                const canvas = document.getElementById('pixie-three-canvas');
                if (canvas && canvas.parentNode) {
                    canvas.parentNode.removeChild(canvas);
                }
                renderer.dispose();
            }
            
            if (particles) {
                particles.geometry.dispose();
                particles.material.dispose();
            }
        }
    }
})();

