        async animateDialogue(text, note, actions) {
            const token = ++this.dialogueToken;
            this.dialogueActions.classList.add('is-hidden');
            this.dialogueActions.innerHTML = '';
            this.dialogueText.classList.remove('is-typing');
            this.dialogueNote.classList.remove('is-typing');

            if (this.prefersReducedMotion) {
                this.dialogueText.textContent = text;
                this.dialogueNote.textContent = note;
            } else {
                this.dialogueText.textContent = '';
                this.dialogueNote.textContent = '';
                await this.typeInto(this.dialogueText, text, token, 14);
                if (token !== this.dialogueToken) {
                    return;
                }
                await this.typeInto(this.dialogueNote, note, token, 8);
                if (token !== this.dialogueToken) {
                    return;
                }
            }

            if (token !== this.dialogueToken) {
                return;
            }

            this.renderDialogueActions(actions);
            this.dialogueActions.classList.remove('is-hidden');
