        stopBattle() {
            if (this.battle) {
                this.battle.active = false;
            }
            this.battle = null;
            this.clearArena();
            this.sealButton.disabled = true;
        }

        loop(now) {
            if (!this.battle || !this.battle.active) {
                return;
            }

            const dt = Math.min(now - this.battle.lastFrame, 34);
            this.battle.lastFrame = now;

            if (!this.battle.pendingVolley && now >= this.battle.nextPatternAt) {
                this.planVolley(now);
            }
            if (this.battle.pendingVolley && now >= this.battle.pendingVolley.fireAt) {
                this.fireVolley(now);
            }
            if (now >= this.battle.nextSigilAt) {
                this.spawnSigil();
                this.battle.nextSigilAt = now + 1800 + Math.random() * 800;  // Decreased from 2400+1100 - more frequent sigils
            }

            this.battle.charge = Math.min(100, this.battle.charge + dt * 0.009);  // Increased from 0.006 - faster charge
            this.updateProjectiles(now, dt);
            this.updateSigils(dt);
            this.updateHud();

            if (this.battle.playerHP <= 0) {
                console.log('[Battle] Player defeated! HP:', this.battle.playerHP);
                setTimeout(() => {
                    this.resolveBattle(false);
                }, 100);
                return;
            }

            requestAnimationFrame(this.boundLoop);
        }

        planVolley(now) {
            const pressure = Math.min(1, this.battle.attackCount / 15);  // Increased from 10 - slower difficulty ramp
            let lanes;
            if (Math.random() < 0.20 + pressure * 0.35) {  // Decreased from 0.28+0.46 - fewer multi-lane attacks
                const safe = Math.floor(Math.random() * 3);
                lanes = [0, 1, 2].filter((lane) => lane !== safe);
            } else {
                lanes = [Math.floor(Math.random() * 3)];
            }

            this.battle.pendingVolley = {lanes, fireAt: now + 500};  // Increased from 360 - more warning time
            const bossLane = lanes[Math.floor(Math.random() * lanes.length)];
            this.battle.bossLane = bossLane;
            this.positionActor(this.boss, bossLane);
            this.boss.classList.add('is-casting');
            lanes.forEach((lane) => this.lanes[lane].classList.add('is-hot'));
        }

        fireVolley(now) {
            const lanes = this.battle.pendingVolley.lanes;
            const speedBase = 160 + this.battle.attackCount * 4;  // Decreased from 198+6 - slower projectiles
            lanes.forEach((lane) => {
                const bolt = document.createElement('div');
                bolt.className = 'pixie-bolt';
                bolt.style.left = this.getLaneCenter(lane).toFixed(1) + 'px';
                bolt.style.transform = 'translate3d(0, 92px, 0)';
                this.arena.appendChild(bolt);
                this.battle.projectiles.push({lane, y: 92, speed: speedBase + Math.random() * 20, element: bolt});  // Decreased variance from 28
            });
            this.lanes.forEach((lane) => lane.classList.remove('is-hot'));
            this.boss.classList.remove('is-casting');
            this.battle.pendingVolley = null;
            this.battle.attackCount += 1;
            this.battle.nextPatternAt = now + Math.max(700, 1400 - this.battle.attackCount * 20);  // Increased from 520/1040/26 - more time between attacks
        }

        spawnSigil() {
            const lane = Math.floor(Math.random() * 3);
            const sigil = document.createElement('div');
            sigil.className = 'pixie-sigil-drop';
            sigil.style.left = this.getLaneCenter(lane).toFixed(1) + 'px';
            sigil.style.transform = 'translate3d(0, 110px, 0) rotate(45deg)';
            this.arena.appendChild(sigil);
            this.battle.sigils.push({lane, y: 110, speed: 110 + Math.random() * 15, element: sigil});  // Decreased from 132+18 - slower sigils, easier to catch
        }

        updateProjectiles(now, dt) {
            const catchLine = this.arena.clientHeight - 54;
            const survivors = [];
            this.battle.projectiles.forEach((projectile) => {
                projectile.y += projectile.speed * (dt / 1000);
                projectile.element.style.transform = `translate3d(0, ${projectile.y.toFixed(1)}px, 0)`;
                if (projectile.y >= catchLine && projectile.lane === this.battle.playerLane) {
                    projectile.element.remove();
                    if (now >= this.battle.invulnerableUntil) {
                        this.hitPlayer(now);
                    }
                    return;
                }
                if (projectile.y > this.arena.clientHeight + 30) {
                    projectile.element.remove();
                    return;
                }
                survivors.push(projectile);
            });
            this.battle.projectiles = survivors;
        }

        updateSigils(dt) {
            const catchLine = this.arena.clientHeight - 58;
            const survivors = [];
            this.battle.sigils.forEach((sigil) => {
                sigil.y += sigil.speed * (dt / 1000);
                sigil.element.style.transform = `translate3d(0, ${sigil.y.toFixed(1)}px, 0) rotate(45deg)`;
                if (sigil.y >= catchLine && sigil.lane === this.battle.playerLane) {
                    sigil.element.remove();
                    this.battle.charge = Math.min(100, this.battle.charge + 40);  // Increased from 34 - more charge per sigil
                    this.battleCopy.textContent = 'Sun sigil gathered. Cast the seal the moment it fills.';
                    return;
                }
                if (sigil.y > this.arena.clientHeight + 24) {
                    sigil.element.remove();
                    return;
                }
                survivors.push(sigil);
            });
            this.battle.sigils = survivors;
        }

        hitPlayer(now) {
            this.battle.playerHP -= 1;
            console.log('[Battle] Player hit! HP now:', this.battle.playerHP);
            this.battle.invulnerableUntil = now + 1000;  // Increased from 820 - longer invulnerability
            this.player.classList.remove('is-hit');
            void this.player.offsetWidth;
            this.player.classList.add('is-hit');
            this.battleCopy.textContent = this.battle.playerHP > 0 ? 'The moon-bolt struck. Move earlier.' : 'The ward broke.';
            if (navigator.vibrate) {
                navigator.vibrate([18, 24, 18]);
            }
        }

        castSeal() {
            if (!this.battle || !this.battle.active || this.battle.charge < 100) {
                console.log('[Battle] Cannot cast seal - battle:', !!this.battle, 'active:', this.battle?.active, 'charge:', this.battle?.charge);
                return;
            }

            console.log('[Battle] Casting seal! Boss HP before:', this.battle.bossHP, 'Player HP:', this.battle.playerHP, 'Charge:', this.battle.charge);
            this.battle.charge = 0;
            this.battle.bossHP -= 1;
            console.log('[Battle] Boss HP after:', this.battle.bossHP);
            this.clearwave.classList.remove('is-active');
            void this.clearwave.offsetWidth;
            this.clearwave.classList.add('is-active');
            this.clearArena();
            const now = performance.now();
            this.battle.pendingVolley = null;
            this.battle.nextPatternAt = now + 680;
            this.battle.nextSigilAt = now + 1800;
            this.battleCopy.textContent = this.battle.bossHP > 0 ? 'Seal landed. Gather more light.' : 'The Fairy Goddess yields.';
            this.updateHud();

            if (this.battle.bossHP <= 0) {
                console.log('[Battle] Boss defeated! Resolving victory...');
                setTimeout(() => {
                    this.resolveBattle(true);
                }, 100);
            }
        }

        async resolveBattle(victory) {
            if (!this.battle || !this.battle.active) {
                return;
            }

            this.battle.active = false;
            this.sealButton.disabled = true;

            let responseData = null;
            try {
                const response = await fetch('/api/pixie/complete', {
                    method: 'POST',
                    headers: {'Content-Type': 'application/json'},
                    body: JSON.stringify({victory})
                });
                responseData = await response.json();
            } catch (error) {
                responseData = {success: false, error: 'Unable to save pixie result.'};
            }

            if (!responseData || !responseData.success) {
                this.showDialogue('The encounter could not be saved.', 'Stay online and try the secret again so the account state can be recorded.', [{label: 'Close', action: 'close', primary: true}]);
                return;
            }

            this.status = responseData.status;
            window.dispatchEvent(new CustomEvent('pixie:wallet-updated', {detail: this.status}));

            if (victory) {
                this.showDialogue(
                    'The Fairy Goddess accepts your challenge.',
                    'Pixie Agent unlocked! You can now use AI features for word definitions, chapter summaries, and more.',
                    [{label: 'Close', action: 'close', primary: true}]
                );
                return;
            }

            this.showDialogue(
                'The pixie leaves this account.',
                'You had one turn and the ward broke. The Fairy Goddess is gone from this account now.',
                [{label: 'Close', action: 'gone', primary: true}]
            );

            setTimeout(() => {
                this.close({removePixie: true});
            }, 1400);
        }

        clearArena() {
            Array.from(this.arena.querySelectorAll('.pixie-bolt, .pixie-sigil-drop')).forEach((node) => node.remove());
            this.lanes.forEach((lane) => lane.classList.remove('is-hot'));
            this.boss.classList.remove('is-casting');
            if (this.battle) {
                this.battle.projectiles = [];
                this.battle.sigils = [];
            }
        }

        updateHud() {
            if (!this.battle) {
                return;
            }

            const bossPercent = (this.battle.bossHP / 4) * 100;
            const playerPercent = (this.battle.playerHP / 5) * 100;  // Changed from 4 to 5
            const chargePercent = this.battle.charge;
            this.bossFill.style.width = bossPercent.toFixed(1) + '%';
            this.playerFill.style.width = playerPercent.toFixed(1) + '%';
            this.chargeFill.style.width = chargePercent.toFixed(1) + '%';
            this.bossValue.textContent = this.battle.bossHP + ' / 4';
            this.playerValue.textContent = this.battle.playerHP + ' / 5';  // Changed from 4 to 5
            this.chargeValue.textContent = Math.round(chargePercent) + '%';
            this.sealButton.disabled = chargePercent < 100;
        }

        setPlayerLane(lane) {
            if (!this.battle || !this.battle.active) {
                return;
            }
            this.battle.playerLane = lane;
            this.positionActor(this.player, lane);
        }

        positionActor(actor, lane) {
            actor.style.left = this.getLaneCenter(lane).toFixed(1) + 'px';
        }

        getLaneCenter(lane) {
            return this.arena.clientWidth * ((lane * 2) + 1) / 6;
        }

        async fetchStatus() {
            const response = await fetch('/api/pixie/status');
            const data = await response.json();
            this.status = data.status;
            return data;
        }

        async primeStatus() {
            try {
                const data = await this.fetchStatus();
                if (data.authenticated && data.status && data.status.pixie_departed) {
                    window.dispatchEvent(new CustomEvent('pixie:challenge-close', {detail: {removePixie: true}}));
                }
            } catch (error) {
                console.error('Pixie status check failed:', error);
            }
        }
    }

    function initPixieBattle() {
        if (!document.body || document.body.dataset.pixie !== 'enabled') {
            return;
        }
        if (document.querySelector('[data-role="arena"]')) {
            return;
        }
        const battle = new PixieBattle();
        battle.primeStatus();
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initPixieBattle);
    } else {
        initPixieBattle();
    }
})();

