const STATIC_CACHE_NAME = 'devnovels-static-v139';
const PAGE_CACHE_NAME = 'devnovels-pages-v44';
const DATA_CACHE_NAME = 'devnovels-data-v44';
const OFFLINE_CHAPTERS_CACHE = 'devnovels-chapters-offline';
const OFFLINE_URL = '/offline';

const APP_SHELL = [
  OFFLINE_URL,
  '/manifest.json',
  '/static/icon-192.png',
  '/static/icon-512.png',
  '/static/offline-sync.js?v=20260323a',
];

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(STATIC_CACHE_NAME).then((cache) =>
      Promise.allSettled(
        APP_SHELL.map(url =>
          cache.add(url).catch(err => console.warn('[SW] Failed to precache:', url, err))
        )
      )
    )
  );
  self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  const validCaches = new Set([
    STATIC_CACHE_NAME,
    PAGE_CACHE_NAME,
    DATA_CACHE_NAME,
    OFFLINE_CHAPTERS_CACHE,
  ]);
  event.waitUntil(
    Promise.all([
      caches.keys().then(names =>
        Promise.all(names.map(name => validCaches.has(name) ? null : caches.delete(name)))
      ),
      self.clients.claim()
    ])
  );
});

self.addEventListener('fetch', (event) => {
  if (event.request.method !== 'GET') return;

  const url = new URL(event.request.url);
  if (url.origin !== self.location.origin) return;

  // Static assets — cache first, lazy fill
  if (url.pathname.startsWith('/static/') || url.pathname === '/manifest.json') {
    event.respondWith(cacheFirst(event.request, STATIC_CACHE_NAME));
    return;
  }

  // API requests — network first, cache fallback (so offline still gets last known data)
  if (url.pathname.startsWith('/api/')) {
    event.respondWith(networkFirst(event.request, DATA_CACHE_NAME));
    return;
  }

  // Chapter pages — check offline cache first, then network
  if (url.pathname.startsWith('/chapter/')) {
    event.respondWith(chapterStrategy(event.request));
    return;
  }

  // All other HTML pages (home, novel, search, history, settings, login)
  // Network first, fall back to cached version
  event.respondWith(pageStrategy(event.request));
});

// ── Cache first (static assets) ──────────────────────────────────────────────
async function cacheFirst(request, cacheName) {
  const cached = await caches.match(request);
  if (cached) return cached;
  try {
    const response = await fetch(request);
    if (response && response.ok) {
      const cache = await caches.open(cacheName);
      cache.put(request, response.clone());
    }
    return response;
  } catch (e) {
    return new Response('Offline', { status: 503 });
  }
}

// ── Network first with cache fallback (API + pages) ──────────────────────────
async function networkFirst(request, cacheName) {
  try {
    const response = await fetch(request);
    if (response && response.ok) {
      const cache = await caches.open(cacheName);
      cache.put(request, response.clone());
    }
    return response;
  } catch (e) {
    const cached = await caches.match(request);
    if (cached) return cached;
    return new Response(JSON.stringify({ error: 'offline', offline: true }), {
      status: 503,
      headers: { 'Content-Type': 'application/json' }
    });
  }
}

// ── Chapter strategy: offline cache → page cache → network → offline msg ─────
async function chapterStrategy(request) {
  // 1. Check downloaded chapters cache first
  const offlineCache = await caches.open(OFFLINE_CHAPTERS_CACHE);
  const offlineCached = await offlineCache.match(request);
  if (offlineCached) {
    console.log('[SW] Serving chapter from offline cache:', request.url);
    return offlineCached;
  }

  // 2. Try network
  try {
    const response = await fetch(request);
    if (response && response.ok) {
      // Cache in both places
      const pageCache = await caches.open(PAGE_CACHE_NAME);
      pageCache.put(request, response.clone());
      offlineCache.put(request, response.clone());
    }
    return response;
  } catch (e) {
    // 3. Try page cache
    const pageCached = await caches.match(request);
    if (pageCached) return pageCached;

    // 4. Offline message
    return new Response(
      `<!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1">
      <title>Offline</title>
      <style>
        body{font-family:system-ui,sans-serif;background:#111;color:#fff;display:flex;align-items:center;justify-content:center;min-height:100vh;margin:0;text-align:center;padding:20px}
        .box{background:rgba(255,255,255,0.05);border:1px solid rgba(255,255,255,0.1);border-radius:16px;padding:40px;max-width:400px}
        h2{margin:0 0 12px}p{opacity:.6;margin:0 0 24px;line-height:1.6}
        button{background:#06b6d4;color:#000;border:none;padding:12px 24px;border-radius:8px;font-size:14px;font-weight:600;cursor:pointer;margin:4px}
      </style>
      </head><body><div class="box">
        <h2>📴 Chapter Not Available Offline</h2>
        <p>This chapter wasn't downloaded. Use the Download button on the novel page while online.</p>
        <button onclick="history.back()">Go Back</button>
        <button onclick="location.reload()">Retry</button>
      </div></body></html>`,
      { headers: { 'Content-Type': 'text/html' }, status: 200 }
    );
  }
}

// ── Page strategy: network first, fall back to cached HTML ───────────────────
async function pageStrategy(request) {
  try {
    const response = await fetch(request);
    if (response && response.ok) {
      const cache = await caches.open(PAGE_CACHE_NAME);
      cache.put(request, response.clone());
    }
    return response;
  } catch (e) {
    // Try exact match
    const cached = await caches.match(request);
    if (cached) {
      console.log('[SW] Serving page from cache:', request.url);
      return cached;
    }

    // Try offline page
    const offlinePage = await caches.match(OFFLINE_URL);
    if (offlinePage) return offlinePage;

    return new Response(
      `<!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1">
      <title>Offline - DevNovels</title>
      <style>
        body{font-family:system-ui,sans-serif;background:#111;color:#fff;display:flex;align-items:center;justify-content:center;min-height:100vh;margin:0;text-align:center;padding:20px}
        .box{background:rgba(255,255,255,0.05);border:1px solid rgba(255,255,255,0.1);border-radius:16px;padding:40px;max-width:400px}
        h2{margin:0 0 12px}p{opacity:.6;margin:0 0 24px;line-height:1.6}
        button{background:#06b6d4;color:#000;border:none;padding:12px 24px;border-radius:8px;font-size:14px;font-weight:600;cursor:pointer;margin:4px}
      </style>
      </head><body><div class="box">
        <h2>📴 You're Offline</h2>
        <p>Visit this page while online first so it can be cached for offline use.</p>
        <button onclick="location.reload()">Retry</button>
      </div></body></html>`,
      { headers: { 'Content-Type': 'text/html' }, status: 200 }
    );
  }
}

