// ── Background download handler ───────────────────────────────────────────────
let activeDownloads = new Map();

self.addEventListener('message', (event) => {
  if (event.data.type === 'START_DOWNLOAD') {
    event.waitUntil(handleBackgroundDownload(event.data));
  } else if (event.data.type === 'CANCEL_DOWNLOAD') {
    const dl = activeDownloads.get(event.data.downloadId);
    if (dl) dl.cancelled = true;
  }
});

async function handleBackgroundDownload({ downloadId, novelSlug, chapters }) {
  console.log('[SW] Starting background download:', downloadId, chapters.length, 'chapters');

  const cache = await caches.open(OFFLINE_CHAPTERS_CACHE);
  let success = 0, failed = 0;
  activeDownloads.set(downloadId, { cancelled: false });

  const db = await openDownloadDB();

  const notifyClients = async (progress) => {
    const allClients = await self.clients.matchAll();
    allClients.forEach(client => client.postMessage({ type: 'DOWNLOAD_PROGRESS', downloadId, ...progress }));
  };

  for (let i = 0; i < chapters.length; i++) {
    const state = activeDownloads.get(downloadId);
    if (state && state.cancelled) break;

    const chapterNum = chapters[i];
    const url = `${self.location.origin}/chapter/${novelSlug}/${chapterNum}`;
    try {
      const response = await fetch(url);
      if (response.ok) { await cache.put(url, response); success++; }
      else failed++;
    } catch (e) { failed++; }

    const progress = { progress: i + 1, success, failed, total: chapters.length, status: 'downloading' };
    await updateDownloadProgress(db, downloadId, progress);
    if (i % 5 === 0 || i === chapters.length - 1) await notifyClients(progress);
    if (i % 10 === 0) await new Promise(r => setTimeout(r, 10));
  }

  const state = activeDownloads.get(downloadId);
  const cancelled = state && state.cancelled;
  const final = { progress: chapters.length, success, failed, total: chapters.length, status: cancelled ? 'cancelled' : 'completed' };
  await updateDownloadProgress(db, downloadId, final);
  await notifyClients(final);
  activeDownloads.delete(downloadId);

  if (!cancelled && self.registration.showNotification) {
    self.registration.showNotification('Download Complete', {
      body: `${success} chapters cached${failed > 0 ? `, ${failed} failed` : ''}`,
      icon: '/static/icon-192.png',
      tag: downloadId
    });
  }
}

function openDownloadDB() {
  return new Promise((resolve, reject) => {
    const req = indexedDB.open('OfflineDownloads', 1);
    req.onerror = () => reject(req.error);
    req.onsuccess = () => resolve(req.result);
    req.onupgradeneeded = (e) => {
      const db = e.target.result;
      if (!db.objectStoreNames.contains('downloads')) {
        db.createObjectStore('downloads', { keyPath: 'id' });
      }
    };
  });
}

async function updateDownloadProgress(db, downloadId, updates) {
  try {
    const tx = db.transaction('downloads', 'readwrite');
    const store = tx.objectStore('downloads');
    const existing = await new Promise((res, rej) => {
      const r = store.get(downloadId);
      r.onsuccess = () => res(r.result);
      r.onerror = () => rej(r.error);
    });
    if (existing) {
      await new Promise((res, rej) => {
        const r = store.put({ ...existing, ...updates });
        r.onsuccess = () => res();
        r.onerror = () => rej(r.error);
      });
    }
  } catch (e) {
    console.error('[SW] Error updating download progress:', e);
  }
}

