export default async function handler(req, res) {
    if (req.method !== 'POST') return res.status(405).json({ error: 'Method not allowed' });

    try {
        const {
            user_id,
            user_ids,
            title,
            body,
            link,
            data
        } = req.body;

        // 1. Determine target users
        const targetUserIds = [...new Set([
            ...(Array.isArray(user_ids) ? user_ids : []),
            user_id
        ].filter(Boolean))];

        if (targetUserIds.length === 0) {
            return res.status(400).json({ success: false, error: 'No user targets provided' });
        }

        // 2. Fetch subscriptions for these users from Supabase
        const { data: profiles, error: fetchError } = await supabase
            .from('profiles')
            .select('id, preferences')
            .in('id', targetUserIds);

        if (fetchError) {
            console.error('[Push] Supabase fetch error:', fetchError);
            throw fetchError;
        }

        if (!profiles || profiles.length === 0) {
            console.warn('[Push] No profiles found for IDs:', targetUserIds);
            return res.status(200).json({ 
                success: true, 
                sentCount: 0, 
                message: 'User profile not found in database',
                debug: { targetUserIds, profilesCount: profiles?.length || 0 }
            });
        }

        // 3. Flatten all subscriptions from all targeted users
        const allSubscriptions = [];
        profiles.forEach(profile => {
            const subs = profile.preferences?.push_subscriptions;
            if (Array.isArray(subs)) {
                subs.forEach(sub => {
                    allSubscriptions.push({
                        ...sub,
                        userId: profile.id
                    });
                });
            } else {
                console.log(`[Push] User ${profile.id} has no push_subscriptions array in preferences`);
            }
        });

        if (allSubscriptions.length === 0) {
            console.log('[Push] No active subscriptions found for users:', targetUserIds);
            return res.status(200).json({ 
                success: true, 
                sentCount: 0, 
                message: 'No registered devices found',
                debug: { 
                    profilesFound: profiles.length,
                    preferencesKeys: profiles.map(p => Object.keys(p.preferences || {}))
                }
            });
        }

        // 4. Send notifications
        const payload = JSON.stringify({
            title: title || 'Zenith Notification',
            body: body || 'You have a new update.',
            url: link || '/',
            data: data || {}
        });

        const results = await Promise.allSettled(
            allSubscriptions.map(async (sub) => {
                try {
                    // Extract only what web-push needs to avoid errors
                    const pushSubscription = {
                        endpoint: sub.endpoint,
                        keys: {
                            p256dh: sub.keys?.p256dh,
                            auth: sub.keys?.auth
                        }
                    };

                    if (!pushSubscription.endpoint || !pushSubscription.keys.p256dh || !pushSubscription.keys.auth) {
                        console.warn('[Push] Skipping invalid subscription for user:', sub.userId);
                        throw new Error('Invalid subscription format');
                    }

                    await webpush.sendNotification(pushSubscription, payload);
                    return { success: true, endpoint: sub.endpoint };
                } catch (err) {
                    if (err.statusCode === 404 || err.statusCode === 410) {
                        console.log('[Push] Subscription expired or gone:', sub.endpoint);
                    } else {
                        console.error('[Push] Error sending to endpoint:', sub.endpoint, err.message);
                    }
                    throw err;
                }
            })
        );

        const sentCount = results.filter(r => r.status === 'fulfilled').length;
        const failedCount = results.filter(r => r.status === 'rejected').length;

        console.log(`[Push] Finished. Sent: ${sentCount}, Failed: ${failedCount}`);

        return res.status(200).json({
            success: true,
            sentCount,
            failedCount,
            totalAttempted: allSubscriptions.length
        });

    } catch (error) {
        console.error('[Push API] Error:', error);
        return res.status(500).json({ success: false, error: error.message });
    }
}

import { createClient } from '@supabase/supabase-js';

const supabaseUrl = process.env.VITE_SUPABASE_URL;
const supabaseKey = process.env.SUPABASE_SERVICE_ROLE_KEY || process.env.VITE_SUPABASE_ANON_KEY;
const supabase = createClient(supabaseUrl, supabaseKey);

export default async function handler(req, res) {
  const { user_id } = req.query;

  if (!user_id) {
    return res.status(400).send('Missing user_id parameter');
  }

  try {
    // 1. Fetch active routines for the user
    const { data: routines, error } = await supabase
      .from('routines')
      .select('*')
      .eq('user_id', user_id)
      .eq('is_active', true);

    if (error) {
      console.error('[CalendarSync] Supabase error:', error);
      throw error;
    }

    if (!routines || routines.length === 0) {
      // Return an empty calendar rather than an error
      return res.status(200)
        .setHeader('Content-Type', 'text/calendar')
        .send('BEGIN:VCALENDAR\r\nVERSION:2.0\r\nPRODID:-//Zenith//Productivity System//EN\r\nEND:VCALENDAR');
    }

    // 2. Generate ICS Content
    let ics = [
      'BEGIN:VCALENDAR', 
      'VERSION:2.0', 
      'PRODID:-//Zenith//Productivity System//EN', 
      'CALSCALE:GREGORIAN', 
      'METHOD:PUBLISH',
      'X-WR-CALNAME:Zenith Productivity',
      'X-WR-TIMEZONE:UTC' // Using UTC as a base; DTSTART will be floating for simplicity
    ];

    const daysMap = { 1: 'MO', 2: 'TU', 3: 'WE', 4: 'TH', 5: 'FR', 6: 'SA', 7: 'SU' };

    routines.forEach(r => {
      const [hours, mins] = r.start_time.split(':');
      const timeStr = `${hours}${mins}00`;

      // We use a fixed base date (Monday, Jan 1, 2024 was a Monday)
      // BYDAY handles the actual recurrence
      const rrule = `FREQ=WEEKLY;BYDAY=${r.days_of_week.map(d => daysMap[d]).join(',')}`;

      ics.push(
        'BEGIN:VEVENT',
        `UID:${r.id}@zenith.app`,
        `SUMMARY:${r.title}`,
        `DESCRIPTION:${r.description || 'Zenith Routine'}`,
        `DTSTART:20240101T${timeStr}`, // Floating time (matches wall-clock time)
        `RRULE:${rrule}`,
        `DURATION:PT${r.duration_minutes || 60}M`,
        'END:VEVENT'
      );
    });

    ics.push('END:VCALENDAR');

    // 3. Serve the file
    res.setHeader('Content-Type', 'text/calendar; charset=utf-8');
    res.setHeader('Content-Disposition', 'attachment; filename="zenith_calendar.ics"');
    res.setHeader('Cache-Control', 'public, s-maxage=3600, stale-while-revalidate=600'); // Cache for 1 hour

    return res.status(200).send(ics.join('\r\n'));

  } catch (err) {
    console.error('[CalendarSync] Server error:', err);
    return res.status(500).send('Internal Server Error');
  }
}

