    if (event.action === 'open') {
        event.waitUntil(
            clients.openWindow('/')
        );
    }
});

// Local check function (limited by SW environment, needs access to indexedDB or similar)
// For now, the best reliability is the GlobalAlarmListener while the browser is open.
async function checkRoutinesAndNotify() {
    // This would ideally fetch from a local cache or Supabase
    // But Service Workers have limited network access in some contexts
    console.log('[Zenith SW] Periodic check triggered');
}

// Zenith Service Worker - Simple Push Notifications
const CACHE_NAME = 'zenith-v1';
const OFFLINE_URL = '/offline.html';

// Install event
self.addEventListener('install', (event) => {
  console.log('[SW] Installing service worker...');
  event.waitUntil(
    caches.open(CACHE_NAME).then((cache) => {
      console.log('[SW] Caching offline page');
      return cache.addAll([
        OFFLINE_URL,
        '/manifest.json',
        '/zenith.png'
      ]).catch(err => console.warn('[SW] Failed to cache:', err));
    })
  );
  self.skipWaiting();
});

// Activate event
self.addEventListener('activate', (event) => {
  console.log('[SW] Activating service worker...');
  event.waitUntil(
    Promise.all([
      // Clean up old caches
      caches.keys().then(names =>
        Promise.all(
          names.map(name => name !== CACHE_NAME ? caches.delete(name) : null)
        )
      ),
      self.clients.claim()
    ])
  );
});

// Fetch event - basic offline support
self.addEventListener('fetch', (event) => {
  if (event.request.method !== 'GET') return;
  
  // Network first, fall back to cache
  event.respondWith(
    fetch(event.request)
      .then(response => {
        // Cache successful responses
        if (response && response.ok) {
          const responseClone = response.clone();
          caches.open(CACHE_NAME).then(cache => {
            cache.put(event.request, responseClone);
          });
        }
        return response;
      })
      .catch(() => {
        // Try cache
        return caches.match(event.request).then(cached => {
          if (cached) return cached;
          
          // Return offline page for navigation requests
          if (event.request.mode === 'navigate') {
            return caches.match(OFFLINE_URL);
          }
          
          return new Response('Offline', { status: 503 });
        });
      })
  );
});

// ── Push Notification Handlers ────────────────────────────────────────────────
self.addEventListener('push', (event) => {
  console.log('[SW] Push notification received');
  
  let data = {
    title: 'Zenith',
    body: 'You have a new notification',
    icon: '/zenith.png',
    badge: '/zenith.png',
    url: '/'
  };
  
  try {
    if (event.data) {
      const payload = event.data.json();
      data = { ...data, ...payload };
    }
  } catch (e) {
    console.error('[SW] Error parsing push data:', e);
  }
  
  event.waitUntil(
    self.registration.showNotification(data.title, {
      body: data.body,
      icon: data.icon,
      badge: data.badge,
      data: { url: data.url },
      tag: data.tag || 'zenith-notification',
      requireInteraction: false,
      vibrate: [200, 100, 200]
    })
  );
});

// Handle notification clicks
self.addEventListener('notificationclick', (event) => {
  console.log('[SW] Notification clicked');
  event.notification.close();
  
  const url = event.notification.data?.url || '/';
  
  event.waitUntil(
    clients.matchAll({ type: 'window', includeUncontrolled: true })
      .then(clientList => {
        // Check if there's already a window open
        for (const client of clientList) {
          if (client.url.includes(self.location.origin) && 'focus' in client) {
            client.navigate(url);
            return client.focus();
          }
        }
        // Open new window if none exists
        return clients.openWindow(url);
      })
  );
});

// Handle notification close
self.addEventListener('notificationclose', (event) => {
  console.log('[SW] Notification closed');
});

console.log('[SW] Service worker loaded');

