import { createContext, useContext, useState, useEffect, useMemo, useCallback, useRef } from 'react';
import { supabase } from '../lib/supabase';
import * as db from '../services/database';

const AuthContext = createContext(null);

// eslint-disable-next-line react-refresh/only-export-components
export const useAuth = () => {
    const context = useContext(AuthContext);
    if (!context) {
        throw new Error('useAuth must be used within an AuthProvider');
    }
    return context;
};

export const AuthProvider = ({ children }) => {
    const [user, setUser] = useState(null);
    const [profile, setProfile] = useState(null);
    const [loading, setLoading] = useState(true);
    const lastFetchRef = useRef(0);
    const fetchProfileRef = useRef(null);

    // fetchProfile as useCallback — stored in ref so closures never go stale
    const fetchProfile = useCallback(async (userId, force = false) => {
        if (!userId) return;

        const now = Date.now();
        if (!force && lastFetchRef.current > 0 && (now - lastFetchRef.current < 30000)) {
            return;
        }

        lastFetchRef.current = now;
        try {
            const { data: userProfile, error } = await supabase
                .from('profiles')
                .select('*')
                .eq('id', userId)
                .single();

            if (error) {
                console.warn('[AuthContext] Profile fetch error:', error);
                return;
            }

            if (userProfile) {
                let classroom_name = null;
                if (userProfile.classroom_id) {
                    const { data: classroom } = await supabase
                        .from('classrooms')
                        .select('name')
                        .eq('id', userProfile.classroom_id)
                        .single();
                    if (classroom) classroom_name = classroom.name;
                }

                setProfile({ ...userProfile, classroom_name });

                // Load AI settings in background
                import('../services/aiService')
                    .then(({ loadFromDatabase }) => loadFromDatabase())
                    .catch(() => {});
            }
        } catch (err) {
            console.error('[AuthContext] Profile fetch error:', err);
        }
    }, []);

    // Always keep ref pointing to latest
    fetchProfileRef.current = fetchProfile;

    useEffect(() => {
        let mounted = true;

        // 1. Initial session check (cold start only)
        const initializeAuth = async () => {
            try {
                const { data: { session } } = await supabase.auth.getSession();
                if (session?.user && mounted) {
                    setUser(session.user);
                    // Optimistic profile so UI is never blank
                    setProfile({
                        id: session.user.id,
                        email: session.user.email,
                        name: session.user.user_metadata?.name || session.user.email?.split('@')[0],
                        role: session.user.user_metadata?.role || 'member',
                        classroom_id: session.user.user_metadata?.classroom_id
                    });
                    fetchProfileRef.current(session.user.id, true);
                }
            } catch (error) {
                console.error('[AuthContext] Init error:', error);
            } finally {
                if (mounted) setLoading(false);
            }
        };

        initializeAuth();

        // 2. Auth state listener — single source of truth
        const { data: { subscription } } = supabase.auth.onAuthStateChange(
            (event, session) => {
                if (!mounted) return;

                if (event === 'SIGNED_OUT') {
                    setUser(null);
                    setProfile(null);
                    setLoading(false);
                    return;
                }

                if (session?.user) {
                    setUser(session.user);
                    if (event === 'SIGNED_IN' || event === 'INITIAL_SESSION') {
                        fetchProfileRef.current(session.user.id, true);
                    }
                }

                setLoading(false);
            }
        );

        // 3. Visibility change — DO NOT call supabase.auth here!
        //    Just tell components to re-fetch their own data.
        const handleVisibilityChange = () => {
            if (document.visibilityState === 'visible') {
                setTimeout(() => {
                    window.dispatchEvent(new CustomEvent('zenith-refresh'));
                }, 300);
            }
        };

        document.addEventListener('visibilitychange', handleVisibilityChange);

        // Emergency timeout
        const emergencyTimeout = setTimeout(() => {
            if (mounted) setLoading(false);
        }, 5000);

        return () => {
            mounted = false;
            subscription?.unsubscribe();
            document.removeEventListener('visibilitychange', handleVisibilityChange);
            clearTimeout(emergencyTimeout);
        };
    }, []);

    const login = useCallback(async (email, password) => {
        try {
            const { data, error } = await Promise.race([
                supabase.auth.signInWithPassword({ email: email.toLowerCase().trim(), password }),
                new Promise((_, reject) => setTimeout(() => reject(new Error('Sign in timed out.')), 60000))
            ]);

            if (error) return { success: false, error: error.message };
            if (data.user) {
                setUser(data.user);
                fetchProfileRef.current(data.user.id, true);
                return { success: true, user: data.user };
            }
            return { success: false, error: 'No user data returned' };
        } catch (err) {
            return { success: false, error: err.message || 'Login failed.' };
        }
    }, []);

    const register = useCallback(async (name, email, password, classroomId) => {
        try {
            const { data, error } = await Promise.race([
                supabase.auth.signUp({
                    email: email.toLowerCase().trim(),
                    password,
                    options: { data: { name, role: 'member', classroom_id: classroomId } }
                }),
                new Promise((_, reject) => setTimeout(() => reject(new Error('Registration timed out.')), 60000))
            ]);

            if (error) return { success: false, error: error.message };
            setUser(data.user);
            fetchProfileRef.current(data.user.id, true);
            return { success: true, user: data.user };
        } catch (err) {
            return { success: false, error: err.message || 'Registration failed.' };
        }
    }, []);

    // logout with timeout — can NEVER hang
    const logout = useCallback(async () => {
        try {
            // Firebase logic removed - migrating to native push

            await Promise.race([
                supabase.auth.signOut(),
                new Promise(resolve => setTimeout(resolve, 3000))
            ]);
        } catch (err) {
            console.error('[AuthContext] Sign out error:', err);
        }
        setUser(null);
        setProfile(null);
    }, [user?.id]);

    const refreshUser = useCallback(async () => {
        if (user?.id) await fetchProfileRef.current(user.id, true);
    }, [user?.id]);

    const forceRefresh = useCallback(async () => {
        try {
            const { data: { session } } = await supabase.auth.getSession();
            if (session?.user) {
                setUser(session.user);
                await fetchProfileRef.current(session.user.id, true);
            }
        } catch (err) {
            console.error('[AuthContext] Force refresh error:', err);
        }
    }, []);

    const updateProfile = useCallback(async (updates) => {
        if (!user?.id) return;
        const updated = await db.updateProfile(user.id, updates);
        if (updated) setProfile(prev => ({ ...prev, ...updated }));
        return updated;
    }, [user?.id]);

    const addXP = useCallback(async (amount) => {
        if (!profile) return;
        await updateProfile({ xp: (profile.xp || 0) + amount });
    }, [profile, updateProfile]);

    const addBadge = useCallback(async (badgeId) => {
        if (!profile) return;
        const currentBadges = profile.badges || [];
        if (!currentBadges.includes(badgeId)) {
            await updateProfile({ badges: [...currentBadges, badgeId] });
        }
    }, [profile, updateProfile]);

    const value = useMemo(() => ({
        user: profile,
        authUser: user,
        loading,
        isAdmin: profile?.role === 'admin',
        login, register, logout, refreshUser, forceRefresh,
        updateProfile, addXP, addBadge,
        currentClassroomName: profile?.classroom_name
    }), [profile, user, loading, login, register, logout, refreshUser, forceRefresh, updateProfile, addXP, addBadge]);

    return (
        <AuthContext.Provider value={value}>
            {children}
        </AuthContext.Provider>
    );
};

import { createContext, useContext, useState, useEffect } from 'react';
import * as storage from '../services/storage';
import { supabase } from '../lib/supabase';

const ThemeContext = createContext(null);

// eslint-disable-next-line react-refresh/only-export-components
export const useTheme = () => {
    const context = useContext(ThemeContext);
    if (!context) {
        throw new Error('useTheme must be used within a ThemeProvider');
    }
    return context;
};

export const ThemeProvider = ({ children }) => {
    const [theme, setThemeState] = useState(() => {
        const savedTheme = storage.getTheme();
        return savedTheme;
    });

    const [colorScheme, setColorSchemeState] = useState(() => {
        const savedScheme = localStorage.getItem('skillquest_color_scheme') || 'gold';
        return savedScheme;
    });



    // We can't use useAuth here directly if AuthContext depends on ThemeContext (circular)
    // But usually ThemeProvider wraps AuthProvider or vice versa.
    // In App.jsx: ThemeProvider -> AuthProvider. So ThemeContext cannot use AuthContext.
    // We need to listen to auth changes separately or handle it via a layout effect or pass user in.
    // Actually, looking at App.jsx, ThemeProvider is outside AuthProvider.
    // So we can't fully sync inside here without refactoring or using supabase directly.
    // Let's use supabase direct listener for preferences if needed, or better:
    // We can expose setPreferences functions that AuthContext calls when user loads.

    // HOWEVER, to make it simple and robust:
    // Let's rely on the components to update attributes, but allow external syncing.
    // Actually, simpler: Let's Move AuthProvider OUTSIDE ThemeProvider in App.jsx? 
    // No, usually Theme is lower level. 

    // Correct approach ensuring persistence:
    // 1. ThemeContext manages local state and DOM.
    // 2. A new component `ThemeSyncer` inside AuthProvider can handle the sync.
    // OR: We just use Supabase client here directly to listen to auth changes? 

    // Let's try to grab the user session directly from supabase in useEffect to sync initial state
    // but avoid tight coupling if possible.

    const setTheme = (newTheme) => {
        setThemeState(newTheme);
        storage.setTheme(newTheme);
        document.documentElement.setAttribute('data-theme', newTheme);

        // Save to DB if user is logged in
        syncPreferenceToDb({ theme: newTheme });
    };

    const setColorScheme = (newScheme) => {
        setColorSchemeState(newScheme);
        localStorage.setItem('skillquest_color_scheme', newScheme);
        document.documentElement.setAttribute('data-color-scheme', newScheme);

        // Save to DB if user is logged in
        syncPreferenceToDb({ colorScheme: newScheme });
    };



    // Helper to sync to DB
    const syncPreferenceToDb = async (prefUpdate) => {
        try {
            const { data: { session } } = await supabase.auth.getSession();
            if (session?.user) {
                const { data: profile } = await supabase
                    .from('profiles')
                    .select('preferences')
                    .eq('id', session.user.id)
                    .single();

                const currentPrefs = profile?.preferences || {};
                const newPrefs = { ...currentPrefs, ...prefUpdate };

                await supabase
                    .from('profiles')
                    .update({ preferences: newPrefs })
                    .eq('id', session.user.id);
            }
        } catch (err) {
            console.error('Failed to sync theme preference:', err);
        }
    };

    // Apply theme attributes on mount — preferences come from localStorage (already persisted)
    // No auth listener here to avoid competing with AuthContext for Supabase locks
    useEffect(() => {
        document.documentElement.setAttribute('data-theme', theme);
        document.documentElement.setAttribute('data-color-scheme', colorScheme);


        // One-time preference load from DB (fire-and-forget, no auth listener)
        const loadPrefsFromDb = async () => {
            try {
                const { data: { session } } = await supabase.auth.getSession();
                if (session?.user) {
                    const { data: profileData } = await supabase
                        .from('profiles')
                        .select('preferences')
                        .eq('id', session.user.id)
                        .single();

                    if (profileData?.preferences) {
                        if (profileData.preferences.theme) {
                            setThemeState(profileData.preferences.theme);
                            storage.setTheme(profileData.preferences.theme);
                            document.documentElement.setAttribute('data-theme', profileData.preferences.theme);
                        }
                        if (profileData.preferences.colorScheme) {
                            setColorSchemeState(profileData.preferences.colorScheme);
                            localStorage.setItem('skillquest_color_scheme', profileData.preferences.colorScheme);
                            document.documentElement.setAttribute('data-color-scheme', profileData.preferences.colorScheme);
                        }

                    }
                }
            } catch (err) {
                // Non-critical — localStorage values are fine as fallback
            }
        };

        loadPrefsFromDb();
    }, []);

    const toggleTheme = () => {
        const newTheme = theme === 'dark' ? 'light' : 'dark';
        setTheme(newTheme);
    };

    const value = {
        theme,
        isDark: theme === 'dark',
        toggleTheme,
        colorScheme,
        setColorScheme
    };

    return (
        <ThemeContext.Provider value={value}>
            {children}
        </ThemeContext.Provider>
    );
};

export default ThemeContext;

import { initializeApp } from "firebase/app";
import { getMessaging, getToken, onMessage } from "firebase/messaging";
import { supabase } from "./supabase";

// Your web app's Firebase configuration
// You will need to add these to your .env file
const firebaseConfig = {
  apiKey: import.meta.env.VITE_FIREBASE_API_KEY,
  authDomain: import.meta.env.VITE_FIREBASE_AUTH_DOMAIN,
  projectId: import.meta.env.VITE_FIREBASE_PROJECT_ID,
  storageBucket: import.meta.env.VITE_FIREBASE_STORAGE_BUCKET,
  messagingSenderId: import.meta.env.VITE_FIREBASE_MESSAGING_SENDER_ID,
  appId: import.meta.env.VITE_FIREBASE_APP_ID
};

export let app;
export let messaging;

try {
  // Initialize Firebase
  app = initializeApp(firebaseConfig);
  messaging = getMessaging(app);
} catch (error) {
  console.warn("Firebase not initialized. Make sure you have the environment variables set up.");
}

export const requestNotificationPermission = async (userId) => {
  if (!messaging) {
    console.error('[Firebase] Messaging not initialized. Check environment variables.');
    alert('Firebase is not configured. Please contact the administrator.');
    return false;
  }

  try {
    // Check if notifications are supported
    if (!('Notification' in window)) {
      console.error('[Firebase] Notifications not supported in this browser');
      alert('Notifications are not supported in your browser. Please use Chrome, Firefox, or Safari.');
      return false;
    }

    // Check if service workers are supported
    if (!('serviceWorker' in navigator)) {
      console.error('[Firebase] Service Workers not supported');
      alert('Service Workers are not supported in your browser. Please update your browser.');
      return false;
    }

    // Check current permission state
    const currentPermission = Notification.permission;
    console.log('[Firebase] Current notification permission:', currentPermission);

    if (currentPermission === 'denied') {
      console.warn('[Firebase] Notification permission denied by user');
      alert('Notifications are blocked. Please enable them in your browser settings:\n\n1. Click the lock icon in the address bar\n2. Find "Notifications"\n3. Change to "Allow"');
      return false;
    }

    // Request permission if not already granted
    console.log('[Firebase] Requesting notification permission...');
    const permission = await Notification.requestPermission();
    console.log('[Firebase] Permission result:', permission);

    if (permission !== 'granted') {
      console.warn('[Firebase] Notification permission not granted:', permission);
      alert('Notification permission was not granted. Please try again and click "Allow" when prompted.');
      return false;
    }

    // Register or re-use existing service worker
    console.log('[Firebase] Registering service worker...');
    const swUrl = `/firebase-messaging-sw.js?v=2.0.0&apiKey=${firebaseConfig.apiKey}&authDomain=${firebaseConfig.authDomain}&projectId=${firebaseConfig.projectId}&storageBucket=${firebaseConfig.storageBucket}&messagingSenderId=${firebaseConfig.messagingSenderId}&appId=${firebaseConfig.appId}`;

    let registration;
    const existingRegistrations = await navigator.serviceWorker.getRegistrations();
    const existingSW = existingRegistrations.find(r => r.active?.scriptURL.includes('firebase-messaging-sw.js'));

    if (existingSW) {
      console.log('[Firebase] Reusing existing service worker');
      registration = existingSW;
      // Update the SW in the background (don't wait)
      existingSW.update().catch(() => {});
    } else {
      registration = await navigator.serviceWorker.register(swUrl, {
        scope: '/'
      });
      console.log('[Firebase] New service worker registered');
    }

    // Wait for the service worker to be ready
    await navigator.serviceWorker.ready;
    console.log('[Firebase] Service worker ready');

    // Check if VAPID key is configured
    if (!import.meta.env.VITE_FIREBASE_VAPID_KEY) {
      console.error('[Firebase] VAPID key not configured');
      alert('Firebase VAPID key is missing. Please contact the administrator.');
      return false;
    }

    // Get the VAPID key from Firebase console -> Cloud Messaging -> Web configuration
    console.log('[Firebase] Getting FCM token...');
    const currentToken = await getToken(messaging, { 
      vapidKey: import.meta.env.VITE_FIREBASE_VAPID_KEY,
      serviceWorkerRegistration: registration
    });

    if (currentToken) {
      console.log('[Firebase] FCM token obtained:', currentToken.substring(0, 20) + '...');
      // Save token to Supabase profiles (merge into preferences or a dedicated column)
      await saveTokenToDatabase(userId, currentToken);

      console.log('[Firebase] ✅ Notifications enabled successfully');
      return true;
    } else {
      console.warn('[Firebase] No FCM token received');
      alert('Could not get notification token. Please try again.');
      return false;
    }
  } catch (error) {
    console.error('[Firebase] Error requesting permission:', error);
    console.error('[Firebase] Error details:', {
      name: error.name,
      message: error.message,
      code: error.code,
      stack: error.stack
    });

    // Provide user-friendly error messages
    let errorMessage = 'Could not enable notifications. ';

    if (error.code === 'messaging/permission-blocked') {
      errorMessage += 'Notifications are blocked. Please enable them in your browser settings.';
    } else if (error.code === 'messaging/token-subscribe-failed') {
      errorMessage += 'Failed to subscribe to notifications. Please check your internet connection.';
    } else if (error.code === 'messaging/unsupported-browser') {
      errorMessage += 'Your browser does not support notifications.';
    } else if (error.message.includes('VAPID')) {
      errorMessage += 'Configuration error. Please contact the administrator.';
    } else {
      errorMessage += `Error: ${error.message}`;
    }

    alert(errorMessage);
    return false;
  }
};

const saveTokenToDatabase = async (userId, token) => {
  try {
    // We fetch current preferences, then update the fcm_token
    const { data: profile } = await supabase
      .from('profiles')
      .select('preferences')
      .eq('id', userId)
      .single();

    // De-duplicate and save
    const currentTokens = profile?.preferences?.fcm_tokens || [];
    if (!currentTokens.includes(token)) {
      const updatedTokens = [...currentTokens, token];
      await supabase.from('profiles').update({
        preferences: { ...profile?.preferences, fcm_tokens: updatedTokens, fcm_token: token }
      }).eq('id', userId);
    }
  } catch (error) {
    console.error("Failed to save FCM token:", error);
  }
};

export const clearTokenFromDatabase = async (userId) => {
  try {
    const { data: profile } = await supabase
      .from('profiles')
      .select('preferences')
      .eq('id', userId)
      .single();

    if (profile?.preferences?.fcm_token) {
      const prefs = profile.preferences;
      delete prefs.fcm_token;

      await supabase
        .from('profiles')
        .update({ preferences: prefs })
        .eq('id', userId);
    }
  } catch (error) {
    console.error("Failed to clear FCM token:", error);
  }
};

export const onMessageListener = () =>
  new Promise((resolve) => {
    if (!messaging) return;
    onMessage(messaging, (payload) => {
      resolve(payload);
    });
  });

// Native Push Notification API Wrapper (No external SDK needed)

// VAPID public key - generate with: npx web-push generate-vapid-keys
// You'll need to add this to your .env as VITE_VAPID_PUBLIC_KEY
const VAPID_PUBLIC_KEY = import.meta.env.VITE_VAPID_PUBLIC_KEY;

/**
 * Check if push notifications are supported
 */
export const isPushSupported = () => {
  return 'serviceWorker' in navigator && 
         'PushManager' in window && 
         'Notification' in window;
};

/**
 * Check if service worker is registered
 */
export const isServiceWorkerRegistered = async () => {
  if (!('serviceWorker' in navigator)) return false;
  const registration = await navigator.serviceWorker.getRegistration();
  return !!registration;
};

/**
 * Register service worker
 */
export const registerServiceWorker = async () => {
  if (!('serviceWorker' in navigator)) {
    throw new Error('Service workers not supported');
  }
  
  try {
    console.log('[Push] Registering service worker...');
    const registration = await navigator.serviceWorker.register('/sw.js', {
      scope: '/'
    });
    console.log('[Push] Service worker registered:', registration.scope);
    return registration;
  } catch (error) {
    console.error('[Push] Service worker registration failed:', error);
    throw error;
  }
};

/**
 * Request notification permission and get push subscription
 */
export const requestPushPermission = async () => {
  if (!isPushSupported()) {
    throw new Error('Push notifications not supported');
  }
  
  try {
    console.log('[Push] Requesting notification permission...');
    
    // Request permission
    const permission = await Notification.requestPermission();
    console.log('[Push] Permission:', permission);
    
    if (permission !== 'granted') {
      throw new Error('Notification permission denied');
    }
    
    // Get or register service worker
    let registration = await navigator.serviceWorker.getRegistration();
    if (!registration) {
      registration = await registerServiceWorker();
      // Wait for service worker to be ready
      await navigator.serviceWorker.ready;
    }
    
    // Check if already subscribed
    let subscription = await registration.pushManager.getSubscription();
    
    if (!subscription) {
      console.log('[Push] Creating new push subscription...');
      
      if (!VAPID_PUBLIC_KEY) {
        throw new Error('VAPID public key not configured');
      }
      
      // Subscribe to push notifications
      subscription = await registration.pushManager.subscribe({
        userVisibleOnly: true,
        applicationServerKey: urlBase64ToUint8Array(VAPID_PUBLIC_KEY)
      });
      
      console.log('[Push] Push subscription created');
    } else {
      console.log('[Push] Using existing push subscription');
    }
    
    return subscription;
  } catch (error) {
    console.error('[Push] Error requesting push permission:', error);
    throw error;
  }
};

/**
 * Get current push subscription
 */
export const getPushSubscription = async () => {
  if (!isPushSupported()) return null;
  
  try {
    const registration = await navigator.serviceWorker.getRegistration();
    if (!registration) return null;
    
    return await registration.pushManager.getSubscription();
  } catch (error) {
    console.error('[Push] Error getting subscription:', error);
    return null;
  }
};

/**
 * Unsubscribe from push notifications
 */
export const unsubscribePush = async () => {
  try {
    const subscription = await getPushSubscription();
    if (subscription) {
      await subscription.unsubscribe();
      console.log('[Push] Unsubscribed from push notifications');
      return true;
    }
    return false;
  } catch (error) {
    console.error('[Push] Error unsubscribing:', error);
    throw error;
  }
};

/**
 * Check current notification permission
 */
export const getNotificationPermission = () => {
  if (!('Notification' in window)) return 'unsupported';
  return Notification.permission;
};

/**
 * Helper function to convert VAPID key
 */
function urlBase64ToUint8Array(base64String) {
  const padding = '='.repeat((4 - base64String.length % 4) % 4);
  const base64 = (base64String + padding)
    .replace(/\-/g, '+')
    .replace(/_/g, '/');
  
  const rawData = window.atob(base64);
  const outputArray = new Uint8Array(rawData.length);
  
  for (let i = 0; i < rawData.length; ++i) {
    outputArray[i] = rawData.charCodeAt(i);
  }
  return outputArray;
}

/**
 * Debug helper - log push notification status
 */
export const debugPushStatus = async () => {
  console.log('=== Push Notification Debug ===');
  console.log('Push supported:', isPushSupported());
  console.log('Notification permission:', getNotificationPermission());
  console.log('Service worker registered:', await isServiceWorkerRegistered());
  
  const subscription = await getPushSubscription();
  console.log('Push subscription:', subscription ? 'Active' : 'None');
  if (subscription) {
    console.log('Endpoint:', subscription.endpoint);
  }
  console.log('VAPID key configured:', !!VAPID_PUBLIC_KEY);
  console.log('==============================');
};

import { useState, useEffect } from 'react';
import { Card, Button, Badge, Modal } from '../components/common';
import { useAuth } from '../context/AuthContext';
import * as db from '../services/database';
import {
    Bell,
    CheckCircle,
    Award,
    AlertCircle,
    Info,
    Check,
    Trash2,
    Calendar,
    ArrowRight
} from 'lucide-react';
import { useNavigate } from 'react-router-dom';

const Notifications = () => {
    const { user } = useAuth();
    const navigate = useNavigate();
    const [notifications, setNotifications] = useState([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        if (user) {
            loadNotifications();
        }
    }, [user]);

    const loadNotifications = async () => {
        setLoading(true);

        // Safety timeout to prevent infinite loading
        const safetyTimeout = setTimeout(() => {
            if (loading) {
                console.warn('Notifications load taking too long, forcing loading to false');
                setLoading(false);
            }
        }, 8000);

        try {
            const data = await db.getNotifications(user.id);
            setNotifications(data);
        } catch (error) {
            console.error('Error loading notifications:', error);
        } finally {
            setLoading(false);
        }
    };

    const handleMarkAsRead = async (id) => {
        try {
            await db.markNotificationRead(id);
            // Update local state locally to reflect optimization
            setNotifications(prev =>
                prev.map(n => n.id === id ? { ...n, is_read: true } : n)
            );
        } catch (error) {
            console.error('Error marking as read:', error);
        }
    };

    const handleMarkAllRead = async () => {
        try {
            await db.markAllNotificationsRead(user.id);
            setNotifications(prev => prev.map(n => ({ ...n, is_read: true })));
        } catch (error) {
            console.error('Error marking all as read:', error);
        }
    };

    const getIcon = (type) => {
        switch (type) {
            case 'success': return <CheckCircle size={24} style={{ color: 'var(--success-500)' }} />;
            case 'award': return <Award size={24} style={{ color: 'var(--primary-500)' }} />;
            case 'warning': return <AlertCircle size={24} style={{ color: 'var(--warning-500)' }} />;
            case 'error': return <AlertCircle size={24} style={{ color: 'var(--error-500)' }} />;
            default: return <Info size={24} style={{ color: 'var(--primary-500)' }} />;
        }
    };

    const formatTime = (isoString) => {
        const date = new Date(isoString);
        return date.toLocaleDateString() + ' ' + date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
    };

    if (loading) {
        return (
            <div className="animate-fade-in">
                <div className="flex justify-between items-center mb-lg">
                    <h2>Notifications</h2>
                </div>
                <div className="flex justify-center p-xl">
                    <div className="loading-spinner" />
                </div>
            </div>
        );
    }

    return (
        <div className="animate-fade-in">
            <div className="flex flex-mobile-col justify-between items-center mb-lg">
                <div>
                    <h2>Notifications</h2>
                    <p style={{ color: 'var(--text-muted)' }}>Stay updated with your latest activities</p>
                </div>
                {notifications.some(n => !n.is_read) && (
                    <Button
                        variant="secondary"
                        icon={Check}
                        onClick={handleMarkAllRead}
                    >
                        Mark all as read
                    </Button>
                )}
            </div>

            {notifications.length === 0 ? (
                <Card className="text-center p-2xl">
                    <div style={{
                        width: '64px',
                        height: '64px',
                        background: 'var(--surface)',
                        borderRadius: '50%',
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        margin: '0 auto var(--space-md)',
                        color: 'var(--text-muted)'
                    }}>
                        <Bell size={32} />
                    </div>
                    <h3>No notifications yet</h3>
                    <p>When you get tasks or earn badges, they'll show up here.</p>
                </Card>
            ) : (
                <div className="flex flex-col gap-md">
                    {notifications.map((notif) => (
                        <Card
                            key={notif.id}
                            style={{
                                display: 'flex',
                                gap: 'var(--space-md)',
                                opacity: notif.is_read ? 0.7 : 1,
                                borderLeft: !notif.is_read ? '4px solid var(--primary-500)' : undefined,
                                transition: 'all var(--transition-base)'
                            }}
                            className={notif.is_read ? '' : 'glow-accent'}
                        >
                            <div style={{ flexShrink: 0, marginTop: '4px' }}>
                                {getIcon(notif.type)}
                            </div>

                            <div style={{ flex: 1 }}>
                                <div className="flex justify-between items-start">
                                    <h4 style={{ margin: '0 0 4px 0' }}>{notif.title}</h4>
                                    <span style={{ fontSize: 'var(--text-xs)', color: 'var(--text-muted)' }}>
                                        {formatTime(notif.created_at)}
                                    </span>
                                </div>
                                <p style={{ margin: '0 0 var(--space-sm) 0' }}>{notif.message}</p>

                                {notif.link && (
                                    <Button
                                        variant="ghost"
                                        size="sm"
                                        icon={ArrowRight}
                                        onClick={() => navigate(notif.link)}
                                        style={{ paddingLeft: 0, color: 'var(--primary-500)' }}
                                    >
                                        View Details
                                    </Button>
                                )}
                            </div>

                            {!notif.is_read && (
                                <div style={{ alignSelf: 'center' }}>
                                    <Button
                                        variant="ghost"
                                        size="icon"
                                        onClick={() => handleMarkAsRead(notif.id)}
                                        title="Mark as read"
                                    >
                                        <Check size={18} />
                                    </Button>
                                </div>
                            )}
                        </Card>
                    ))}
                </div>
            )}
        </div>
    );
};

