                                </h4>
                                {(() => {
                                    const s = getStudentStats(selectedStudent.id);
                                    return (
                                        <div className="flex flex-col gap-lg">
                                            <div>
                                                <div className="flex justify-between text-xs font-bold mb-xs uppercase tracking-widest text-muted">Completion Rate</div>
