                            <Button variant="secondary" onClick={() => setSelectedStudent(null)}>Close Profile</Button>
                        </div>
                    </div>
                )}
            </Modal>
        </div>
    );
};

export default ClassroomDetail;

import { useState, useEffect } from 'react';
import { Card, Button, Input, LoadingSpinner, Modal, Badge } from '../../components/common';
import { School, Save, Users, BookOpen, Key, Plus, Check, MoreVertical, LayoutGrid, Settings } from 'lucide-react';
import * as db from '../../services/database';
import { useAuth } from '../../context/AuthContext';
import { useNavigate, Link } from 'react-router-dom';

const ClassroomSettings = () => {
    const { user, forceRefresh } = useAuth();
    const navigate = useNavigate();

    const [classrooms, setClassrooms] = useState([]);
    const [activeClassroom, setActiveClassroom] = useState(null);
    const [loading, setLoading] = useState(true);
    const [stats, setStats] = useState({});

    // Modal states
    const [showCreateModal, setShowCreateModal] = useState(false);
    const [showEditModal, setShowEditModal] = useState(false);

    // Form states
    const [newName, setNewName] = useState('');
    const [newDesc, setNewDesc] = useState('');

    // Edit states
    const [editId, setEditId] = useState(null);
    const [editName, setEditName] = useState('');
    const [editDesc, setEditDesc] = useState('');

    const [isSubmitting, setIsSubmitting] = useState(false);

    useEffect(() => {
        loadData();
    }, []);

    const loadData = async () => {
        try {
            setLoading(true);
            const [list, active] = await Promise.all([
                db.getClassrooms(),
                db.getClassroom()
            ]);

            setClassrooms(list);
            setActiveClassroom(active);

            if (active) {
                // Load stats for active classroom
                const [members, tasks, codes] = await Promise.all([
                    db.getMembers(),
                    db.getTasks(),
                    db.getInviteCodes ? db.getInviteCodes() : Promise.resolve([])
                ]);
                setStats({
                    members: members.length,
                    tasks: tasks.length,
                    codes: codes.length || 0
                });
            }
        } catch (error) {
            console.error('Error loading data:', error);
        } finally {
            setLoading(false);
        }
    };

    const handleCreate = async (e) => {
        e.preventDefault();
        try {
            setIsSubmitting(true);
            const newClass = await db.createClassroom(newName, newDesc);
            await handleSwitch(newClass.id); // Auto switch to new
            setShowCreateModal(false);
            setNewName('');
            setNewDesc('');
        } catch (error) {
            console.error(error);
            alert('Failed to create classroom');
        } finally {
            setIsSubmitting(false);
        }
    };

    const handleEditClick = (classroom) => {
        setEditId(classroom.id);
        setEditName(classroom.name);
        setEditDesc(classroom.description || '');
        setShowEditModal(true);
    };

    const handleUpdate = async (e) => {
        e.preventDefault();
        try {
            setIsSubmitting(true);
            await db.updateClassroom(editId, {
                name: editName,
                description: editDesc
            });
            setShowEditModal(false);
            loadData();
        } catch (error) {
            console.error(error);
            alert('Failed to update classroom');
        } finally {
            setIsSubmitting(false);
        }
    };

    const handleSwitch = async (id) => {
        try {
            setLoading(true);
            await db.switchClassroom(id);
            // Force refresh auth context instead of full page reload
            await forceRefresh();
            // Reload data after context refresh
            await loadData();
        } catch (error) {
            console.error('Switch error', error);
            alert('Failed to switch classroom');
        } finally {
            setLoading(false);
        }
    };

    if (loading) {
        return (
            <div className="flex justify-center items-center h-full">
                <LoadingSpinner size="lg" />
            </div>
        );
    }

    return (
        <div className="animate-fade-in max-w-6xl mx-auto">
            <div className="flex flex-mobile-col justify-between items-center mb-xl">
                <div>
                    <h2>My Classrooms</h2>
                    <p style={{ color: 'var(--text-muted)' }}>Manage and switch between your classrooms</p>
                </div>
                <Button icon={Plus} onClick={() => setShowCreateModal(true)}>
                    Create Classroom
                </Button>
            </div>

            {/* Active Classroom Overview */}
            {activeClassroom && (
                <div className="mb-2xl">
                    <h3 className="mb-md text-sm uppercase tracking-wider text-muted font-bold">Current Classroom</h3>

                    <Card className="p-xl border-primary-500 border-2 relative overflow-hidden">
                        <div className="absolute top-0 right-0 p-2 bg-primary-500 text-white rounded-bl-lg">
                            <span className="text-xs font-bold px-2">ACTIVE</span>
                        </div>

                        <div className="flex flex-mobile-col justify-between items-start mb-lg">
                            <div>
                                <h1 className="text-3xl font-bold mb-xs text-gradient">{activeClassroom.name}</h1>
                                <p className="text-muted max-w-2xl">{activeClassroom.description || "No description provided."}</p>
                            </div>
                            <Button variant="secondary" icon={Settings} onClick={() => handleEditClick(activeClassroom)}>Edit Details</Button>
                        </div>

                        <div className="grid grid-cols-3 grid-3-mobile-1 gap-md">
                            <div className="flex items-center gap-md p-md bg-surface rounded-lg border border-border">
                                <div className="w-10 h-10 rounded-full bg-blue-500/10 flex items-center justify-center text-blue-500">
                                    <Users size={20} />
                                </div>
                                <div>
                                    <h4 className="m-0 text-xl">{stats.members}</h4>
                                    <span className="text-xs text-muted font-bold uppercase">Members</span>
                                </div>
                            </div>
                            <div className="flex items-center gap-md p-md bg-surface rounded-lg border border-border">
                                <div className="w-10 h-10 rounded-full bg-green-500/10 flex items-center justify-center text-green-500">
                                    <BookOpen size={20} />
                                </div>
                                <div>
                                    <h4 className="m-0 text-xl">{stats.tasks}</h4>
                                    <span className="text-xs text-muted font-bold uppercase">Tasks</span>
                                </div>
                            </div>
                            <div className="flex items-center gap-md p-md bg-surface rounded-lg border border-border">
                                <div className="w-10 h-10 rounded-full bg-purple-500/10 flex items-center justify-center text-purple-500">
                                    <Key size={20} />
                                </div>
                                <div>
                                    <h4 className="m-0 text-xl">{stats.codes}</h4>
                                    <span className="text-xs text-muted font-bold uppercase">Codes</span>
                                </div>
                            </div>
                        </div>
                    </Card>
                </div>
            )}

            {/* All Classrooms Grid */}
            <div>
                <h3 className="mb-md text-sm uppercase tracking-wider text-muted font-bold">Available Classrooms ({classrooms.length})</h3>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-lg">
                    {classrooms.map(room => {
                        const isActive = activeClassroom?.id === room.id;
                        return (
                            <Card
                                key={room.id}
                                className={`p-lg cursor-pointer transition-all hover:-translate-y-1 hover:shadow-lg ${isActive ? 'ring-2 ring-primary-500' : ''}`}
                                onClick={() => !isActive && handleSwitch(room.id)}
                            >
                                <div className="flex justify-between items-start mb-md">
                                    <School size={32} className={isActive ? 'text-primary-500' : 'text-muted'} />
                                    {isActive && <Badge variant="primary">Active</Badge>}
                                </div>
                                <h3 className="mb-xs text-lg">{room.name}</h3>
                                <p className="text-sm text-muted line-clamp-2 mb-lg h-10">
                                    {room.description || "No description"}
                                </p>
                                <div className="mt-auto flex gap-sm">
                                    {isActive ? (
                                        <Button variant="outline" className="flex-1" disabled>Currently Active</Button>
                                    ) : (
                                        <Button variant="secondary" className="flex-1" onClick={(e) => { e.stopPropagation(); handleSwitch(room.id); }}>Switch</Button>
                                    )}
                                    <div className="flex gap-xs flex-1">
                                        <Link to={`/admin/classroom/${room.id}`} className="flex-1" onClick={(e) => e.stopPropagation()}>
                                            <Button variant="ghost" className="w-full">Manage</Button>
                                        </Link>
                                        <Button variant="ghost" size="icon" onClick={(e) => { e.stopPropagation(); handleEditClick(room); }} title="Edit">
                                            <Settings size={18} />
                                        </Button>
                                    </div>
                                </div>
                            </Card>
                        );
                    })}

                    {/* Add New Card */}
                    <button
                        onClick={() => setShowCreateModal(true)}
                        className="flex flex-col items-center justify-center p-lg rounded-xl border-2 border-dashed border-border hover:border-primary-500 hover:bg-primary-50/10 transition-all group h-full min-h-[220px]"
                    >
                        <div className="w-12 h-12 rounded-full bg-surface border border-border flex items-center justify-center mb-md group-hover:scale-110 transition-transform">
                            <Plus size={24} className="text-muted group-hover:text-primary-500" />
                        </div>
                        <h4 className="text-muted group-hover:text-primary-500">Create New Classroom</h4>
                    </button>
                </div>
            </div>

            {/* Create Modal */}
            <Modal
                isOpen={showCreateModal}
                onClose={() => setShowCreateModal(false)}
                title="Create New Classroom"
            >
                <form onSubmit={handleCreate}>
                    <div className="flex flex-col gap-lg">
                        <Input
                            label="Classroom Name"
                            placeholder="e.g. Advanced React Course"
                            value={newName}
                            onChange={(e) => setNewName(e.target.value)}
                            required
                        />
                        <Input
                            type="textarea"
                            label="Description"
                            placeholder="What will students learn?"
                            value={newDesc}
                            onChange={(e) => setNewDesc(e.target.value)}
                        />
                        <div className="flex justify-end gap-sm mt-md">
                            <Button variant="ghost" type="button" onClick={() => setShowCreateModal(false)}>Cancel</Button>
                            <Button type="submit" loading={isSubmitting}>Create Classroom</Button>
                        </div>
                    </div>
                </form>
            </Modal>
            {/* Edit Modal */}
            <Modal
                isOpen={showEditModal}
                onClose={() => setShowEditModal(false)}
                title="Edit Classroom"
            >
                <form onSubmit={handleUpdate}>
                    <div className="flex flex-col gap-lg">
                        <Input
                            label="Classroom Name"
                            placeholder="e.g. Advanced React Course"
                            value={editName}
                            onChange={(e) => setEditName(e.target.value)}
                            required
                        />
                        <Input
                            type="textarea"
                            label="Description"
                            placeholder="What will students learn?"
                            value={editDesc}
                            onChange={(e) => setEditDesc(e.target.value)}
                        />
                        <div className="flex justify-end gap-sm mt-md">
                            <Button variant="ghost" type="button" onClick={() => setShowEditModal(false)}>Cancel</Button>
                            <Button type="submit" loading={isSubmitting}>Save Changes</Button>
                        </div>
                    </div>
                </form>
            </Modal>
        </div>
    );
};

export default ClassroomSettings;

import { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import { Card, Badge, Avatar, Button, ProgressBar } from '../../components/common';
import { supabase } from '../../lib/supabase';
import {
    ListTodo,
    ClipboardCheck,
    Users,
    Trophy,
    TrendingUp,
    Clock,
    CheckCircle,
    AlertCircle,
    ArrowRight,
    Plus
} from 'lucide-react';
import * as db from '../../services/database';
import { formatRelativeTime, getStatusColor, calculateLevelProgress, calculateLevel } from '../../utils/constants';
import { useMiniReload } from '../../hooks/useMiniReload';

const AdminDashboard = () => {
    const { user } = useAuth();
    const [stats, setStats] = useState({
        totalTasks: 0,
        pendingReviews: 0,
        completionRate: 0,
        teamMembers: 0
    });
    const [recentSubmissions, setRecentSubmissions] = useState([]);
    const [teamProgress, setTeamProgress] = useState([]);
    const [loading, setLoading] = useState(true);

    const loadDashboardData = async (isRefresh = false) => {
        try {
            if (!isRefresh) setLoading(true);

            // Fetch data from Supabase with timeout
            const fetchPromise = Promise.all([
                db.getTasks(),
                db.getSubmissions(),
                db.getMembers(),
                db.getQuizAttempts()
            ]);

            const [tasks, submissions, members, quizAttempts] = await Promise.race([
                fetchPromise,
                new Promise((_, reject) => setTimeout(() => reject(new Error('TIMEOUT')), 10000))
            ]);

            // Calculate stats
            const pendingSubmissions = (submissions || []).filter(s => s.status === 'pending').length;
            const pendingQuizzes = (quizAttempts || []).filter(q => q.status === 'pending').length;
            const pendingReviews = pendingSubmissions + pendingQuizzes;

            const approvedSubmissions = (submissions || []).filter(s => s.status === 'approved').length;
            const completionRate = (submissions || []).length > 0
                ? Math.round((approvedSubmissions / submissions.length) * 100)
                : 0;

            // Filter out admins for stats and progress
            const filteredMembers = members.filter(m => m.role !== 'admin');

            setStats({
                totalTasks: tasks.filter(t => t.status === 'active').length,
                pendingReviews,
                completionRate,
                teamMembers: filteredMembers.length
            });

            // Recent submissions with joined data
            setRecentSubmissions(submissions.slice(0, 5));

            // Team progress (sorted by XP)
            const progress = filteredMembers
                .sort((a, b) => (b.xp || 0) - (a.xp || 0))
                .slice(0, 5)
                .map(m => {
                    const memberSubmissions = submissions.filter(s => s.user_id === m.id);
                    const completed = memberSubmissions.filter(s => s.status === 'approved').length;
                    return {
                        ...m,
                        tasksCompleted: completed,
                        totalTasks: memberSubmissions.length
                    };
                });
            setTeamProgress(progress);
        } catch (error) {
            console.error('Error loading dashboard:', error);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        loadDashboardData();

        // REALTIME: Auto-update when data changes
        const channel = supabase
            .channel('admin-dashboard-realtime')
            .on('postgres_changes', { event: '*', schema: 'public', table: 'tasks' }, () => {
                loadDashboardData(true);
            })
            .on('postgres_changes', { event: '*', schema: 'public', table: 'submissions' }, () => {
                loadDashboardData(true);
            })
            .on('postgres_changes', { event: '*', schema: 'public', table: 'quiz_attempts' }, () => {
                loadDashboardData(true);
            })
            .on('postgres_changes', { event: '*', schema: 'public', table: 'profiles' }, () => {
                loadDashboardData(true);
            })
            .subscribe();

        return () => {
            supabase.removeChannel(channel);
        };
    }, []);

    // Visibility-based refresh (no manual button needed)
    useMiniReload(() => loadDashboardData(true));

    const statCards = [
        {
            label: 'Active Tasks',
            value: stats.totalTasks,
            icon: ListTodo,
            color: 'var(--primary-500)',
            bg: 'rgba(99, 102, 241, 0.1)'
        },
        {
            label: 'Pending Reviews',
            value: stats.pendingReviews,
            icon: ClipboardCheck,
            color: 'var(--warning-500)',
            bg: 'rgba(245, 158, 11, 0.1)'
        },
        {
            label: 'Completion Rate',
            value: `${stats.completionRate}%`,
            icon: TrendingUp,
            color: 'var(--success-500)',
            bg: 'rgba(16, 185, 129, 0.1)'
        },
        {
            label: 'Team Members',
            value: stats.teamMembers,
            icon: Users,
            color: 'var(--accent-500)',
            bg: 'rgba(6, 182, 212, 0.1)'
        }
    ];

    if (loading) {
        return (
            <div className="flex items-center justify-center" style={{ minHeight: '400px' }}>
                <div className="loading-spinner" />
            </div>
        );
    }

    return (
        <div className="animate-fade-in">
            {/* Welcome Section */}
            <div style={{ marginBottom: 'var(--space-xl)' }}>
                <h2 style={{ fontSize: 'var(--text-2xl)', marginBottom: 'var(--space-xs)' }}>
                    Welcome back, {user?.name?.split(' ')[0]}! 👋
                </h2>
                <p style={{ color: 'var(--text-muted)' }}>
                    Here's what's happening with your team today.
                </p>
            </div>

            {/* Stats Grid */}
            <div className="stat-card-grid" style={{ marginBottom: 'var(--space-xl)' }}>
                {statCards.map((stat) => (
                    <Card
                        key={stat.label}
                        style={{
                            display: 'flex',
                            alignItems: 'flex-start',
                            gap: 'var(--space-md)'
                        }}
                    >
                        <div style={{
                            width: '48px',
                            height: '48px',
                            borderRadius: 'var(--radius-lg)',
                            background: stat.bg,
                            display: 'flex',
                            alignItems: 'center',
                            justifyContent: 'center',
                            color: stat.color
                        }}>
                            <stat.icon size={24} />
                        </div>
                        <div>
                            <h3 style={{
                                fontSize: 'var(--text-3xl)',
                                fontWeight: 700,
                                marginBottom: '2px',
                                color: 'var(--text)'
                            }}>
                                {stat.value}
                            </h3>
                            <p style={{
                                fontSize: 'var(--text-sm)',
                                color: 'var(--text-muted)',
                                margin: 0
                            }}>
                                {stat.label}
                            </p>
                        </div>
                    </Card>
                ))}
            </div>

            {/* Main Content Grid */}
            <div className="dashboard-grid">
                {/* Recent Submissions */}
                <Card>
                    <div className="flex justify-between items-center mb-lg">
                        <h3 style={{ margin: 0, fontSize: 'var(--text-lg)' }}>
                            Recent Submissions
                        </h3>
                        <Link to="/admin/evaluations">
                            <Button variant="ghost" size="sm" icon={ArrowRight} iconPosition="right">
                                View All
                            </Button>
                        </Link>
                    </div>

                    {recentSubmissions.length === 0 ? (
                        <div className="empty-state" style={{ padding: 'var(--space-xl)' }}>
                            <div className="empty-state-icon">
                                <ClipboardCheck size={32} />
                            </div>
                            <h4>No submissions yet</h4>
                            <p>Submissions will appear here once team members start completing tasks.</p>
                        </div>
                    ) : (
                        <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-sm)' }}>
                            {recentSubmissions.map((sub) => (
                                <Link
                                    key={sub.id}
                                    to={`/admin/evaluations/${sub.id}`}
                                    style={{ textDecoration: 'none' }}
                                >
                                    <div style={{
                                        display: 'flex',
                                        alignItems: 'center',
                                        gap: 'var(--space-md)',
                                        padding: 'var(--space-md)',
                                        background: 'var(--surface)',
                                        borderRadius: 'var(--radius-lg)',
                                        border: '1px solid var(--border)',
                                        transition: 'all var(--transition-fast)',
                                        cursor: 'pointer'
                                    }}
                                        onMouseEnter={e => {
                                            e.currentTarget.style.borderColor = 'var(--primary-500)';
                                            e.currentTarget.style.transform = 'translateX(4px)';
                                        }}
                                        onMouseLeave={e => {
                                            e.currentTarget.style.borderColor = 'var(--border)';
                                            e.currentTarget.style.transform = 'translateX(0)';
                                        }}
                                    >
                                        <Avatar name={sub.profiles?.name} image={sub.profiles?.avatar_url} size="sm" />
                                        <div style={{ flex: 1, minWidth: 0 }}>
                                            <p style={{
                                                margin: 0,
                                                fontWeight: 500,
                                                fontSize: 'var(--text-sm)',
                                                color: 'var(--text)'
                                            }}>
                                                {sub.profiles?.name}
                                            </p>
                                            <p style={{
                                                margin: 0,
                                                fontSize: 'var(--text-xs)',
                                                color: 'var(--text-muted)',
                                                whiteSpace: 'nowrap',
                                                overflow: 'hidden',
                                                textOverflow: 'ellipsis'
                                            }}>
                                                {sub.tasks?.title}
                                            </p>
                                        </div>
                                        <div style={{ textAlign: 'right' }}>
                                            <Badge variant={getStatusColor(sub.status)}>
                                                {sub.status}
                                            </Badge>
                                            <p style={{
                                                margin: '4px 0 0',
                                                fontSize: 'var(--text-xs)',
                                                color: 'var(--text-muted)'
                                            }}>
                                                {formatRelativeTime(sub.submitted_at)}
                                            </p>
                                        </div>
                                    </div>
                                </Link>
                            ))}
                        </div>
                    )}
                </Card>

                {/* Team Progress */}
                <Card>
                    <div className="flex justify-between items-center mb-lg">
                        <h3 style={{ margin: 0, fontSize: 'var(--text-lg)' }}>
                            Team Performance
                        </h3>
                        <Link to="/leaderboard">
                            <Button variant="ghost" size="sm" icon={Trophy}>
                                Leaderboard
                            </Button>
                        </Link>
                    </div>

                    {teamProgress.length === 0 ? (
                        <div className="empty-state" style={{ padding: 'var(--space-xl)' }}>
                            <div className="empty-state-icon">
                                <Users size={32} />
                            </div>
                            <h4>No team members yet</h4>
                            <p>Team members will appear here once they join the platform.</p>
                        </div>
                    ) : (
                        <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-md)' }}>
                            {teamProgress.map((member, index) => (
                                <div
                                    key={member.id}
                                    style={{
                                        display: 'flex',
                                        alignItems: 'center',
                                        gap: 'var(--space-md)'
                                    }}
                                >
                                    <span style={{
                                        width: '24px',
                                        fontSize: 'var(--text-sm)',
                                        color: 'var(--text-muted)',
                                        textAlign: 'center'
                                    }}>
                                        #{index + 1}
                                    </span>
                                    <Avatar name={member.name} image={member.avatar_url} size="sm" />
                                    <div style={{ flex: 1 }}>
                                        <div className="flex justify-between items-center mb-xs">
                                            <span style={{ fontWeight: 500, fontSize: 'var(--text-sm)' }}>
                                                {member.name}
                                            </span>
                                            <span style={{
                                                fontSize: 'var(--text-xs)',
                                                color: 'var(--primary-400)'
                                            }}>
                                                {member.xp || 0} XP
                                            </span>
                                        </div>
                                        <ProgressBar
                                            value={calculateLevelProgress(member.xp || 0)}
                                            size="sm"
                                        />
                                    </div>
                                </div>
                            ))}
                        </div>
                    )}
                </Card>
            </div >

            <div style={{ marginTop: 'var(--space-xl)' }}>
                <h3 style={{ marginBottom: 'var(--space-md)' }}>Quick Actions</h3>
                <div className="flex flex-mobile-col gap-md">
                    <Link to="/admin/tasks/new">
                        <Button icon={Plus}>Create New Task</Button>
                    </Link>
                    <Link to="/admin/quizzes/new">
                        <Button variant="secondary" icon={Plus}>Create Quiz</Button>
                    </Link>
                    <Link to="/admin/evaluations">
                        <Button variant="secondary" icon={ClipboardCheck}>
                            Review Submissions ({stats.pendingReviews})
                        </Button>
                    </Link>
                </div>
            </div >

        </div >
    );
};

export default AdminDashboard;

// Vercel Deployment Trigger: 2026-05-03-2001
import { useState, useEffect, useCallback } from 'react';
import { Link, useParams, useNavigate } from 'react-router-dom';
import { Card, Button, Badge, Avatar, Modal, Input, ProgressBar } from '../../components/common';
import {
    Search,
    Filter,
    CheckCircle,
    XCircle,
    Clock,
    ExternalLink,
    MessageSquare,
    Award,
    ArrowLeft,
    RefreshCw,
    AlertTriangle,
    Check,
    X,
    Brain,
    ChevronRight
} from 'lucide-react';
import { supabase } from '../../lib/supabase';
import * as db from '../../services/database';
import { evaluateQuizAttempt, evaluateTaskSubmission } from '../../services/aiService';
import { formatDate, formatRelativeTime, getStatusColor, EVALUATION_CRITERIA } from '../../utils/constants';

const EvaluationCenter = () => {
    const { type, submissionId } = useParams();
    const navigate = useNavigate();
    const [mode, setMode] = useState(type || 'tasks'); // 'tasks' or 'quizzes'
    const [submissions, setSubmissions] = useState([]);
    const [quizAttempts, setQuizAttempts] = useState([]);
    const [filterStatus, setFilterStatus] = useState('pending');
    const [searchQuery, setSearchQuery] = useState('');
    const [loading, setLoading] = useState(true);
    const [evalAbortController, setEvalAbortController] = useState(null);

    const loadData = useCallback(async () => {
        try {
            console.log('[EvaluationCenter] loadData: Starting fetch...');
            setLoading(true);

            // Safety timeout to prevent infinite loading
            const safetyTimeout = setTimeout(() => {
                if (loading) {
                    console.warn('[EvaluationCenter] loadData taking too long, forcing loading to false');
                    setLoading(false);
                }
            }, 10000);
            const [subs, atts] = await Promise.all([
                db.getSubmissions().catch(e => { console.error('Submissions Fetch Error:', e); return []; }),
                db.getQuizAttempts().catch(e => { console.error('Quiz Attempts Fetch Error:', e); return []; })
            ]);
            
            console.log('[EvaluationCenter] loadData: Data received', {
                subsCount: subs?.length,
                attsCount: atts?.length
            });
            
            setSubmissions(subs || []);
            setQuizAttempts(atts || []);
            console.log('[EvaluationCenter] loadData: State updated');
        } catch (error) {
            console.error('[EvaluationCenter] CRITICAL: Evaluation Data Load Failed:', error);
        } finally {
            console.log('[EvaluationCenter] loadData: Setting loading to false');
            setLoading(false);
        }
    }, []);

    useEffect(() => {
        console.log('[EvaluationCenter] useEffect: Mounting and starting loadData');
        loadData();
        
        // GOD COMMAND: REALTIME UPDATES
        console.log('[EvaluationCenter] useEffect: Setting up Realtime channel');
        const channel = supabase
            .channel(`evaluation-updates-${Math.random().toString(36).substring(7)}`) // Unique channel name per mount
            .on('postgres_changes', { event: '*', schema: 'public', table: 'quiz_attempts' }, (payload) => {
                console.log('[EvaluationCenter] Realtime: Quiz attempt update detected', payload.eventType);
                loadData();
            })
            .on('postgres_changes', { event: '*', schema: 'public', table: 'submissions' }, (payload) => {
                console.log('[EvaluationCenter] Realtime: Task submission update detected', payload.eventType);
                loadData();
            })
            .subscribe((status) => {
                console.log('[EvaluationCenter] Realtime Subscription Status:', status);
            });

        return () => {
            console.log('[EvaluationCenter] useEffect Cleanup: Removing Realtime channel');
            supabase.removeChannel(channel);
        };
    }, [loadData]);

    const filteredSubmissions = submissions
        .filter(sub => {
            const matchesStatus = filterStatus === 'all' || sub.status === filterStatus;
            const matchesSearch = searchQuery === '' ||
                sub.profiles?.name?.toLowerCase().includes(searchQuery.toLowerCase()) ||
                sub.tasks?.title?.toLowerCase().includes(searchQuery.toLowerCase());
            return matchesStatus && matchesSearch;
        })
        .sort((a, b) => new Date(b.submitted_at) - new Date(a.submitted_at));

    const filteredQuizzes = quizAttempts
        .filter(att => {
            const userName = att.profiles?.name || '';
            const quizTitle = att.quizzes?.title || '';
            const matchesSearch = searchQuery === '' ||
                userName.toLowerCase().includes(searchQuery.toLowerCase()) ||
                quizTitle.toLowerCase().includes(searchQuery.toLowerCase());
            
            return matchesSearch;
        })
        .sort((a, b) => new Date(b.created_at || b.completed_at) - new Date(a.created_at || a.completed_at));

    console.log('Evaluation Data:', { mode, submissions: submissions.length, quizAttempts: quizAttempts.length });

    if (mode === 'tasks' && submissionId) {
        return <EvaluationDetail submissionId={submissionId} onBack={() => navigate('/admin/evaluations')} onUpdate={loadData} />;
    }

    if (mode === 'quizzes' && submissionId) {
        return <QuizReviewDetail attemptId={submissionId} onBack={() => navigate('/admin/evaluations')} onUpdate={loadData} />;
    }

    // Handle legacy URLs or automatic routing based on type param
    if (type === 'tasks' && submissionId) {
        return <EvaluationDetail submissionId={submissionId} onBack={() => navigate('/admin/evaluations')} onUpdate={loadData} />;
    }
    if (type === 'quizzes' && submissionId) {
        return <QuizReviewDetail attemptId={submissionId} onBack={() => navigate('/admin/evaluations')} onUpdate={loadData} />;
    }

    if (loading && submissions.length === 0 && quizAttempts.length === 0) {
        return (
            <div className="flex items-center justify-center" style={{ minHeight: '400px' }}>
                <div className="loading-spinner" />
            </div>
        );
    }

    return (
        <div className="animate-fade-in">
            {/* Header */}
            <div className="flex flex-mobile-col justify-between items-center mb-lg">
                <div>
                    <h2 style={{ margin: 0 }}>Evaluation Center</h2>
                    <p style={{ color: 'var(--text-muted)', margin: 0 }}>
                        Review and evaluate team progress
                    </p>
                </div>
                <div className="flex gap-sm">
                    {mode === 'quizzes' && quizAttempts.some(a => a.metadata?.has_key_error) && (
                        <Button 
                            variant="danger" 
                            size="sm" 
                            icon={AlertTriangle} 
                            className="animate-pulse"
                            onClick={async () => {
                                const flagged = quizAttempts.filter(a => a.metadata?.has_key_error);
                                if (window.confirm(`Are you sure you want to Intercept & Re-evaluate all ${flagged.length} flagged attempts?`)) {
                                    setLoading(true);
                                    try {
                                        const { evaluateQuizAttempt, getSelectedModel } = await import('../../services/aiService');
                                        const model = getSelectedModel();
                                        
                                        for (const att of flagged) {
                                            const quiz = await db.getQuizById(att.quiz_id);
                                            const report = await evaluateQuizAttempt(quiz, att.answers, model);
                                            
                                            // Simple auto-update for bulk
                                            const hasKeyError = report.suggestions.some(s => s.isKeyError === true);
                                            await db.updateQuizAttempt(att.id, {
                                                metadata: { 
                                                    ...att.metadata, 
                                                    ai_evaluated: true, 
                                                    ai_report: report, 
                                                    has_key_error: hasKeyError 
                                                }
                                            });
                                        }
                                        alert('Bulk re-evaluation complete!');
                                        loadData();
                                    } catch (e) {
                                        console.error('Bulk Error:', e);
                                        alert('Some attempts failed to re-evaluate.');
                                    } finally {
                                        setLoading(false);
                                    }
                                }
                            }}
                        >
                            Intercept All Flagged
                        </Button>
                    )}
                    <Button variant="secondary" size="sm" icon={RefreshCw} onClick={loadData} loading={loading}>
                        Refresh Data
                    </Button>
                    <div className="tabs" style={{ background: 'var(--card)', padding: '4px' }}>
                        <button
                            className={`tab ${mode === 'tasks' ? 'active' : ''}`}
                            onClick={() => {
                                setMode('tasks');
                                setFilterStatus('pending');
                            }}
                        >
                            Tasks
                        </button>
                        <button
                            className={`tab ${mode === 'quizzes' ? 'active' : ''}`}
                            onClick={() => setMode('quizzes')}
                        >
                            Quizzes
                            <Badge variant="primary" style={{ marginLeft: '6px' }}>
                                {quizAttempts.length}
                            </Badge>
                        </button>
                    </div>
                </div>
            </div>

            <Card style={{ marginBottom: 'var(--space-lg)', padding: 'var(--space-md)' }}>
                <div className="flex flex-mobile-col gap-md items-center" style={{ flexWrap: 'wrap' }}>
                    <div style={{ flex: '1', minWidth: '200px' }}>
                        <Input
                            placeholder={mode === 'tasks' ? "Search by name or task..." : "Search by name or quiz..."}
                            icon={Search}
                            value={searchQuery}
                            onChange={(e) => setSearchQuery(e.target.value)}
                        />
                    </div>
                    {mode === 'tasks' && (
                        <div className="tabs" style={{ width: 'auto' }}>
                            {['all', 'pending', 'approved', 'rejected'].map(status => (
                                <button
                                    key={status}
                                    className={`tab ${filterStatus === status ? 'active' : ''}`}
                                    onClick={() => setFilterStatus(status)}
                                >
                                    {status.charAt(0).toUpperCase() + status.slice(1)}
                                    {status === 'pending' && (
                                        <Badge variant="warning" style={{ marginLeft: '6px' }}>
                                            {submissions.filter(s => s.status === 'pending').length}
                                        </Badge>
                                    )}
                                </button>
                            ))}
                        </div>
                    )}
                </div>
            </Card>

            {/* List */}
            {mode === 'tasks' ? (
                /* Submissions List */
                filteredSubmissions.length === 0 ? (
                    <Card>
                        <div className="empty-state">
                            <div className="empty-state-icon">
                                <CheckCircle size={32} />
                            </div>
                            <h3>No submissions found</h3>
                            <p>
                                {filterStatus === 'pending'
                                    ? 'All caught up! No pending submissions to review.'
                                    : 'No submissions match your current filters.'}
                            </p>
                        </div>
                    </Card>
                ) : (
                    <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-sm)' }}>
                        {filteredSubmissions.map(sub => (
                            <Link
                                key={sub.id}
                                to={`/admin/evaluations/tasks/${sub.id}`}
                                style={{ textDecoration: 'none' }}
                            >
                                <Card className="evaluation-card">
                                    <Avatar name={sub.profiles?.name} image={sub.profiles?.avatar_url} size="lg" />

                                    <div className="evaluation-card-content" style={{ flex: 1, minWidth: 0 }}>
                                        <div className="flex items-center gap-sm mb-xs">
                                            <h4 style={{ margin: 0 }}>{sub.profiles?.name}</h4>
                                            <Badge variant={getStatusColor(sub.status)}>{sub.status}</Badge>
                                            {sub.is_resubmission && <Badge variant="primary">Resubmitted</Badge>}
                                        </div>
                                        <p style={{
                                            margin: 0,
                                            color: 'var(--text-muted)',
                                            fontSize: 'var(--text-sm)'
                                        }}>
                                            {sub.tasks?.title}
                                        </p>
                                    </div>

                                    <div className="evaluation-card-meta">
                                        {sub.score !== null && sub.score !== undefined && (
                                            <div style={{
                                                fontSize: 'var(--text-lg)',
                                                fontWeight: 600,
                                                color: sub.status === 'approved' ? 'var(--success-500)' : 'var(--text-muted)'
                                            }}>
                                                {sub.score}/100
                                            </div>
                                        )}
                                        <div style={{
                                            fontSize: 'var(--text-xs)',
                                            color: 'var(--text-muted)'
                                        }}>
                                            {formatRelativeTime(sub.submitted_at)}
                                        </div>
                                    </div>

                                    <ExternalLink size={20} style={{ color: 'var(--text-muted)' }} />
                                </Card>
                            </Link>
                        ))}
                    </div>
                )
            ) : (
                /* Quizzes List */
                filteredQuizzes.length === 0 ? (
                    <Card>
                        <div className="empty-state">
                            <div className="empty-state-icon">
                                <Award size={32} />
                            </div>
                            <h3>No quiz attempts yet</h3>
                            <p>Students haven't completed any quizzes yet.</p>
                        </div>
                    </Card>
                ) : (
                    <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-sm)' }}>
                        {filteredQuizzes.map(att => (
                            <Link
                                key={att.id}
                                to={`/admin/evaluations/quizzes/${att.id}`}
                                style={{ textDecoration: 'none' }}
                            >
                                <Card className="evaluation-card">
                                    <Avatar name={att.profiles?.name} image={att.profiles?.avatar_url} size="lg" />

                                    <div className="evaluation-card-content" style={{ flex: 1, minWidth: 0 }}>
                                        <div className="flex items-center gap-sm mb-xs">
                                            <h4 style={{ margin: 0 }}>{att.profiles?.name}</h4>
                                            <Badge variant={att.passed ? 'success' : 'error'}>
                                                {att.passed ? 'Passed' : 'Failed'}
                                            </Badge>
                                            {att.metadata?.ai_evaluated ? (
                                                <Badge variant="primary">AI Evaluated</Badge>
                                            ) : (
                                                <Badge variant="warning">🤖 AI Processing...</Badge>
                                            )}
                                            {att.metadata?.finalized ? (
                                                <Badge variant="success">✓ Finalized</Badge>
                                            ) : att.metadata?.manually_evaluated ? (
                                                <Badge variant="accent">Draft Saved</Badge>
                                            ) : null}
                                            {att.metadata?.has_key_error && (
                                                <Badge variant="error">🚩 Key Error?</Badge>
                                            )}
                                        </div>
                                        <p style={{
                                            margin: 0,
                                            color: 'var(--text-muted)',
                                            fontSize: 'var(--text-sm)'
                                        }}>
                                            {att.quizzes?.title}
                                        </p>
                                    </div>

                                    <div className="evaluation-card-meta">
                                        <div style={{
                                            fontSize: 'var(--text-lg)',
                                            fontWeight: 600,
                                            color: att.passed ? 'var(--success-500)' : 'var(--error-500)'
                                        }}>
                                            {att.score}%
                                        </div>
                                        <div style={{
                                            fontSize: 'var(--text-xs)',
                                            color: 'var(--text-muted)'
                                        }}>
                                            {formatRelativeTime(att.created_at || att.completed_at)}
                                        </div>
                                    </div>

                                    <ExternalLink size={20} style={{ color: 'var(--text-muted)' }} />
                                </Card>
                            </Link>
                        ))}
                    </div>
                )
            )}


        </div>
    );
};

// Detailed evaluation view
const EvaluationDetail = ({ submissionId, onBack, onUpdate }) => {
    const [submission, setSubmission] = useState(null);
    const [score, setScore] = useState('');
    const [feedback, setFeedback] = useState('');
    const [loading, setLoading] = useState(true);
    const [saving, setSaving] = useState(false);
    const [evaluating, setEvaluating] = useState(false);

    const loadSubmission = useCallback(async () => {
        try {
            setLoading(true);

            // Safety timeout
            const safetyTimeout = setTimeout(() => {
                if (loading) {
                    console.warn('[EvaluationDetail] loadSubmission taking too long, forcing loading to false');
                    setLoading(false);
                }
            }, 8000);

            const sub = await db.getSubmissionById(submissionId);
            if (sub) {
                setSubmission(sub);
                setScore(sub.score?.toString() || sub.suggested_score?.toString() || '');
                setFeedback(sub.feedback || '');
            }
        } catch (error) {
            console.error('Error loading submission:', error);
        } finally {
            setLoading(false);
        }
    }, [submissionId]);

    useEffect(() => {
        loadSubmission();
    }, [loadSubmission]);

    const handleApprove = async () => {
        if (!score) return;
        setSaving(true);

        try {
            const scoreNum = parseInt(score);
            await db.updateSubmission(submissionId, {
                status: 'approved',
                score: scoreNum,
                feedback,
                evaluated_at: new Date().toISOString()
            });

                // award XP to user
                if (submission.profiles?.id) {
                    const xpEarned = Math.round((scoreNum / 100) * (submission.tasks?.points || 100));
                    const currentXP = submission.profiles.xp || 0;
                    await db.updateProfile(submission.profiles.id, { xp: currentXP + xpEarned });

                    // Notify User (In-app)
                    await db.createNotification({
                        user_id: submission.profiles.id,
                        classroom_id: submission.tasks?.classroom_id,
                        title: 'Task Approved! 🥳',
                        message: `Your submission for "${submission.tasks?.title}" was approved with a score of ${scoreNum}/100. You earned ${xpEarned} XP!`,
                        type: 'success',
                        link: `/tasks/${submission.tasks?.id}`
                    });
                }

            onUpdate();
            onBack();
        } catch (error) {
            console.error('Error approving submission:', error);
        } finally {
            setSaving(false);
        }
    };

    const [revisionDeadline, setRevisionDeadline] = useState('');

    const handleReject = async () => {
        setSaving(true);
        try {
            const scoreNum = parseInt(score) || 0;
            const updateData = {
                status: 'rejected',
                score: scoreNum,
                feedback,
                evaluated_at: new Date().toISOString()
            };

            if (revisionDeadline) {
                updateData.revision_deadline = new Date(revisionDeadline).toISOString();
            }

            await db.updateSubmission(submissionId, updateData);

                // Notify User (In-app)
                if (submission.profiles?.id) {
                    let msg = `Reviewer requested a revision for "${submission.tasks?.title}". Check feedback for details.`;
                    if (revisionDeadline) {
                        msg += ` New deadline: ${new Date(revisionDeadline).toLocaleDateString()}`;
                    }

                    await db.createNotification({
                        user_id: submission.profiles.id,
                        classroom_id: submission.tasks?.classroom_id,
                        title: 'Revision Requested 📝',
                        message: msg,
                        type: 'error',
                        link: `/tasks/${submission.tasks?.id}`
                    });
                }

            onUpdate();
            onBack();
        } catch (error) {
            console.error('Error rejecting submission:', error);
        } finally {
            setSaving(false);
        }
    };

    const handleAiReview = async () => {
        if (!submission) return;
        setEvaluating(true);
        try {
            const report = await evaluateTaskSubmission(submission.tasks, submission);
            if (report) {
                setScore(report.suggestedScore.toString());
                setFeedback(report.feedback);
                // We don't save yet, let the admin review the AI suggestion
            }
        } catch (error) {
            console.error('AI Task Review Error:', error);
            alert('Failed to get AI review. Please try again.');
        } finally {
            setEvaluating(false);
        }
    };

    if (loading) {
        return (
            <div className="flex items-center justify-center" style={{ minHeight: '400px' }}>
                <div className="loading-spinner" />
            </div>
        );
    }

    if (!submission) {
        return <div>Submission not found</div>;
    }

    const autoEval = submission.auto_evaluation || {};
    const taskCriteria = submission.tasks?.criteria || [];

    return (
        <div className="animate-fade-in">
            {/* Header */}
            <div className="flex flex-mobile-col items-center gap-md mb-lg">
                <Button variant="ghost" size="icon" onClick={onBack}>
                    <ArrowLeft size={20} />
                </Button>
                <div>
                    <h2 style={{ margin: 0 }}>Evaluate Submission</h2>
                    <p style={{ margin: 0, color: 'var(--text-muted)' }}>
                        {submission.tasks?.title}
                    </p>
                </div>
            </div>

            <div className="grid-2-1">
                {/* Left Column - Submission Details */}
                <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-lg)' }}>
                    {/* Submitter Info */}
                    <Card>
                        <div className="flex items-center gap-md">
                            <Avatar name={submission.profiles?.name} image={submission.profiles?.avatar_url} size="lg" />
                            <div>
                                <h4 style={{ margin: 0 }}>{submission.profiles?.name}</h4>
                                <p style={{ margin: 0, color: 'var(--text-muted)', fontSize: 'var(--text-sm)' }}>
                                    {submission.profiles?.email}
                                </p>
                            </div>
                            <div style={{ marginLeft: 'auto', textAlign: 'right' }}>
                                <Badge variant={getStatusColor(submission.status)}>
                                    {submission.status}
                                </Badge>
                                <p style={{ margin: '4px 0 0', fontSize: 'var(--text-xs)', color: 'var(--text-muted)' }}>
                                    Submitted {formatDate(submission.submitted_at)}
                                </p>
                            </div>
                        </div>
                    </Card>

                    {/* Repository Link */}
                    <Card>
                        <h4 style={{ marginBottom: 'var(--space-md)' }}>Repository</h4>
                        <a
                            href={submission.repo_url}
                            target="_blank"
                            rel="noopener noreferrer"
                            style={{
                                display: 'flex',
                                alignItems: 'center',
                                gap: 'var(--space-sm)',
                                padding: 'var(--space-md)',
                                background: 'var(--card)',
                                borderRadius: 'var(--radius-md)',
                                border: '1px solid var(--border)',
                                color: 'var(--primary-400)',
                                fontSize: 'var(--text-sm)',
                                wordBreak: 'break-all'
                            }}
                        >
                            <ExternalLink size={16} />
                            {submission.repo_url}
                        </a>
                        {submission.notes && (
                            <div style={{ marginTop: 'var(--space-md)' }}>
                                <p style={{ fontSize: 'var(--text-sm)', color: 'var(--text-muted)', marginBottom: '4px' }}>
                                    Submission Notes:
                                </p>
                                <p style={{
                                    padding: 'var(--space-md)',
                                    background: 'var(--card)',
                                    borderRadius: 'var(--radius-md)',
                                    fontSize: 'var(--text-sm)'
                                }}>
                                    {submission.notes}
                                </p>
                            </div>
                        )}
                    </Card>

                    {/* Feedback */}
                    <Card>
                        <h4 style={{ marginBottom: 'var(--space-md)' }}>
                            <MessageSquare size={18} style={{ marginRight: '8px', verticalAlign: 'middle' }} />
                            Your Feedback
                        </h4>
                        <Input
                            type="textarea"
                            placeholder="Provide detailed feedback for the team member..."
                            value={feedback}
                            onChange={(e) => setFeedback(e.target.value)}
                            style={{ minHeight: '150px' }}
                        />
                        <div style={{ marginTop: 'var(--space-md)' }}>
                            <p style={{ margin: '0 0 4px', fontSize: 'var(--text-sm)', color: 'var(--text-muted)' }}>
                                Revision Deadline (Optional)
                            </p>
                            <Input
                                type="date"
                                value={revisionDeadline}
                                onChange={(e) => setRevisionDeadline(e.target.value)}
                            />
                        </div>
                    </Card>
                </div>

                {/* Right Column - Auto Evaluation & Scoring */}
                <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-lg)' }}>
                    {/* Auto Evaluation */}
                    <Card>
                        <h4 style={{ marginBottom: 'var(--space-md)' }}>
                            <RefreshCw size={18} style={{ marginRight: '8px', verticalAlign: 'middle' }} />
                            Auto-Evaluation
                        </h4>
                        <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-sm)' }}>
                            {taskCriteria.map(criteriaId => {
                                const criteria = EVALUATION_CRITERIA.find(c => c.id === criteriaId);
                                const passed = autoEval[criteriaId];

                                return (
                                    <div
                                        key={criteriaId}
                                        className="flex items-center gap-sm"
                                        style={{
                                            padding: 'var(--space-sm) var(--space-md)',
                                            background: 'var(--card)',
                                            borderRadius: 'var(--radius-md)',
                                            borderLeft: `3px solid ${passed === true ? 'var(--success-500)' : passed === false ? 'var(--error-500)' : 'var(--warning-500)'}`
                                        }}
                                    >
                                        {passed === true ? (
                                            <Check size={16} style={{ color: 'var(--success-500)' }} />
                                        ) : passed === false ? (
                                            <X size={16} style={{ color: 'var(--error-500)' }} />
                                        ) : (
                                            <AlertTriangle size={16} style={{ color: 'var(--warning-500)' }} />
                                        )}
                                        <span style={{ fontSize: 'var(--text-sm)' }}>
                                            {criteria?.label || criteriaId}
                                        </span>
                                    </div>
                                );
                            })}
                        </div>

                        {submission.suggested_score && (
                            <div style={{
                                marginTop: 'var(--space-lg)',
                                padding: 'var(--space-md)',
                                background: 'rgba(99, 102, 241, 0.1)',
                                borderRadius: 'var(--radius-md)',
                                textAlign: 'center'
                            }}>
                                <p style={{ fontSize: 'var(--text-sm)', color: 'var(--text-muted)', margin: '0 0 4px' }}>
                                    Suggested Score
                                </p>
                                <p style={{ fontSize: 'var(--text-2xl)', fontWeight: 700, margin: 0, color: 'var(--primary-400)' }}>
                                    {submission.suggested_score}/100
                                </p>
                            </div>
                        )}
                    </Card>

                    {/* Final Score */}
                    <Card>
                        <h4 style={{ marginBottom: 'var(--space-md)' }}>
                            <Award size={18} style={{ marginRight: '8px', verticalAlign: 'middle' }} />
                            Final Score
                        </h4>
                        <Button
                            variant="ghost"
                            size="sm"
                            icon={Brain}
                            onClick={handleAiReview}
                            loading={evaluating}
                            style={{ width: '100%', marginBottom: 'var(--space-md)', border: '1px dashed var(--primary-300)', color: 'var(--primary-600)' }}
                        >
                            {evaluating ? 'AI Reviewing...' : '🤖 AI Assistant Review'}
                        </Button>
                        <Input
                            type="number"
                            placeholder="0-100"
                            min="0"
                            max="100"
                            value={score}
                            onChange={(e) => setScore(e.target.value)}
                        />

                        {score && submission.tasks?.points && (
                            <div style={{
                                marginTop: 'var(--space-md)',
                                padding: 'var(--space-sm) var(--space-md)',
                                background: 'var(--card)',
                                borderRadius: 'var(--radius-md)',
                                fontSize: 'var(--text-sm)',
                                color: 'var(--text-muted)'
                            }}>
                                XP to award: <strong style={{ color: 'var(--success-500)' }}>
                                    +{Math.round((parseInt(score) / 100) * submission.tasks.points)} XP
                                </strong>
                            </div>
                        )}
                    </Card>

                    {/* Action Buttons */}
                    <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-sm)' }}>
                        <Button
                            variant="success"
                            onClick={handleApprove}
                            disabled={!score || saving}
                            loading={saving}
                            icon={CheckCircle}
                            style={{ width: '100%' }}
                        >
                            Approve & Award XP
                        </Button>
                        <Button
                            variant="danger"
                            onClick={handleReject}
                            disabled={saving}
                            icon={XCircle}
                            style={{ width: '100%' }}
                        >
                            Request Revision
                        </Button>
                    </div>
                </div>
            </div>


        </div>
    );
};

// Detailed Quiz review view
const QuizReviewDetail = ({ attemptId, onBack, onUpdate }) => {
    const [attempt, setAttempt] = useState(null);
    const [loading, setLoading] = useState(true);
    const [saving, setSaving] = useState(false);
    const [success, setSuccess] = useState(false);
    const [overrides, setOverrides] = useState({}); // { questionIndex: boolean }
    const [aiReport, setAiReport] = useState(null);
    const [evaluating, setEvaluating] = useState(false);
    const [selectedModel, setSelectedModel] = useState('');
    const [availableModels, setAvailableModels] = useState([]);
    const [evalAbortController, setEvalAbortController] = useState(null);
    const [evalStatus, setEvalStatus] = useState(''); // 'busy', 'retrying', etc.
    const [retryCount, setRetryCount] = useState(0);
    const [manualFeedback, setManualFeedback] = useState('');

    const loadAttempt = useCallback(async () => {
        try {
            setLoading(true);

            // Safety timeout
            const safetyTimeout = setTimeout(() => {
                if (loading) {
                    console.warn('[QuizReviewDetail] loadAttempt taking too long, forcing loading to false');
                    setLoading(false);
                }
            }, 8000);
            const data = await db.getQuizAttempts();
            const att = data.find(a => a.id === attemptId);
            if (att) {
                // Fetch the actual quiz questions for reference
                const quiz = await db.getQuizById(att.quiz_id);
                setAttempt({ ...att, quiz });
            }
        } catch (error) {
            console.error('Error loading quiz attempt:', error);
        } finally {
            setLoading(false);
        }
    }, [attemptId]);

    useEffect(() => {
        loadAttempt();
        
        // Load configured models
        const loadModels = async () => {
            const { AVAILABLE_MODELS, isAPIKeyConfigured, getSelectedModel } = await import('../../services/aiService');
            const configured = AVAILABLE_MODELS.filter(m => isAPIKeyConfigured(m.provider));
            setAvailableModels(configured);
            const preferredModel = configured.find(m => m.provider === 'sambanova')?.id || getSelectedModel();
            setSelectedModel(preferredModel);
        };
        loadModels();
    }, [loadAttempt]);

    // Update local state from metadata when attempt loads
    useEffect(() => {
        if (attempt?.metadata) {
            // Load AI Report if it exists
            if (attempt.metadata.ai_report && !aiReport) {
                setAiReport(attempt.metadata.ai_report);
            }
            
            // Load Overrides (Manual or AI)
            if (attempt.metadata.overrides && Object.keys(overrides).length === 0) {
                const typedOverrides = {};
                Object.entries(attempt.metadata.overrides).forEach(([k, v]) => {
                    typedOverrides[Number(k)] = v;
                });
                setOverrides(typedOverrides);
            }

            // Load manual feedback if it exists
            if (attempt.metadata.manual_feedback && !manualFeedback) {
                setManualFeedback(attempt.metadata.manual_feedback);
            }
        }
    }, [attempt, aiReport, overrides, manualFeedback]);

    const handleAiEvaluation = async () => {
        if (!attempt) return;
        
        if (!selectedModel) {
            alert('Please select an AI model first.');
            return;
        }

        const controller = new AbortController();
        setEvalAbortController(controller);
        setEvaluating(true);
        setEvalStatus('Evaluating...');
        setRetryCount(0);
        
        try {
            // Define a local interceptor for the signal to track retries if possible
            // But since evaluateQuizAttempt is a service call, we'll just handle it there
            const report = await evaluateQuizAttempt(attempt.quiz, attempt.answers, selectedModel, controller.signal, {
                onRetry: (attempt, delay) => {
                    setEvalStatus(`Busy... Retrying in ${Math.round(delay/1000)}s`);
                    setRetryCount(attempt);
                }
            });
            setAiReport(report);
            
            // Auto-apply logic
            const newOverrides = { ...overrides };
            report.suggestions.forEach(s => {
                let qIndex = Number(s.questionIndex);
                
                // If AI used 1-based indexing (Common LLM quirk), adjust to 0-based
                if (qIndex > 0 && qIndex >= attempt.quiz.questions.length) {
                    qIndex -= 1;
                }

                if (qIndex >= 0 && qIndex < attempt.quiz.questions.length) {
                    newOverrides[qIndex] = s.isCorrect;
                }
            });
            setOverrides(prev => ({ ...prev, ...newOverrides }));

            // Calculate final score with AI suggestions applied
            const finalCorrect = attempt.quiz.questions.reduce((acc, q, idx) => {
                const override = newOverrides[idx];
                const isCorrect = override !== undefined ? override : (attempt.answers[idx] === q.correctAnswer);
                return acc + (isCorrect ? 1 : 0);
            }, 0);
            const finalScore = Math.round((finalCorrect / attempt.total) * 100);

            // Check for Key Errors to flag for Admin
            const hasKeyError = report.suggestions.some(s => s.isKeyError === true);

            await db.updateQuizAttempt(attempt.id, {
                correct: finalCorrect,
                score: finalScore,
                passed: finalScore >= 70,
                metadata: { 
                    ...attempt.metadata, 
                    ai_evaluated: true, 
                    ai_report: report, 
                    model_used: selectedModel,
                    overrides: newOverrides,
                    has_key_error: hasKeyError 
                }
            });
        } catch (error) {
            // SILENCE AbortError: Don't show alert if user cancelled
            if (error.name === 'AbortError' || error.message?.includes('cancelled') || error.message?.includes('AbortError')) {
                console.log('AI Evaluation cancelled by user.');
                return;
            }
            console.error('AI Eval Error:', error);
            alert('❌ AI Review Failed: ' + (error.message.includes('not configured') ? 'Please check your API keys in Settings.' : error.message));
        } finally {
            setEvaluating(false);
            setEvalAbortController(null);
            setEvalStatus('');
        }
    };

    const handleAbortEvaluation = () => {
        if (evalAbortController) {
            evalAbortController.abort();
            setEvaluating(false);
            setEvalAbortController(null);
            setEvalStatus('');
        }
    };

    if (loading) {
        return (
            <div className="flex items-center justify-center" style={{ minHeight: '400px' }}>
                <div className="loading-spinner" />
            </div>
        );
    }

    if (!attempt) return <div>Attempt not found</div>;

    return (
        <div className="animate-fade-in">
            <div className="flex items-center justify-between gap-md mb-lg">
                <div className="flex items-center gap-md">
                    <Button variant="ghost" size="icon" onClick={onBack}>
                        <ArrowLeft size={20} />
                    </Button>
                    <div>
                        <h2 style={{ margin: 0 }}>Quiz Results Review</h2>
                        <p style={{ margin: 0, color: 'var(--text-muted)' }}>
                            {attempt.quiz?.title}
                        </p>
                    </div>
                </div>
                
                {/* Quick Model Selector */}
                <div className="flex items-center gap-sm">
                    <span style={{ fontSize: 'var(--text-xs)', color: 'var(--text-muted)', fontWeight: 600 }}>Model:</span>
                    <select 
                        value={selectedModel}
                        onChange={(e) => setSelectedModel(e.target.value)}
                        style={{ 
                            padding: '4px 8px', 
                            fontSize: 'var(--text-xs)', 
                            background: 'var(--surface)', 
                            border: '1px solid var(--border)',
                            borderRadius: 'var(--radius-md)',
                            color: 'var(--text)'
                        }}
                    >
                        {availableModels.map(model => (
                            <option key={model.id} value={model.id}>
                                {model.provider.charAt(0).toUpperCase() + model.provider.slice(1)}: {model.name}
                            </option>
                        ))}
                        {availableModels.length === 0 && <option value="">No models configured</option>}
                    </select>
                </div>
            </div>

            <div style={{ 
                display: 'grid',
                gridTemplateColumns: 'repeat(auto-fit, minmax(300px, 1fr))',
                gap: 'var(--space-lg)', 
                alignItems: 'start' 
            }}>
                {/* Summary Info */}
                <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-lg)' }}>
                    <Card>
                        <div className="flex justify-between items-center mb-lg">
                            <div className="flex items-center gap-md">
                                <Avatar name={attempt.profiles?.name} image={attempt.profiles?.avatar_url} size="lg" />
                                <div>
                                    <h4 style={{ margin: 0 }}>{attempt.profiles?.name}</h4>
                                    <p style={{ margin: 0, color: 'var(--text-muted)', fontSize: 'var(--text-sm)' }}>
                                        {attempt.profiles?.email}
                                    </p>
                                </div>
                            </div>
                            {evaluating ? (
                                <div className="flex flex-col gap-sm">
                                    <Button 
                                        variant="warning" 
                                        size="sm"
                                        loading={true}
                                    >
                                        {evalStatus || 'AI is Reviewing...'}
                                    </Button>
                                    {evalStatus.includes('busy') && (
                                        <p style={{ fontSize: '10px', color: 'var(--warning-500)', margin: 0, textAlign: 'center', fontWeight: 600 }}>
                                            ⚠️ AI Provider is busy. Retrying...
                                        </p>
                                    )}
                                    <Button 
                                        variant="ghost" 
                                        size="sm" 
                                        onClick={handleAbortEvaluation}
                                        style={{ color: 'var(--error-500)' }}
                                    >
                                        Cancel
                                    </Button>
                                </div>
                            ) : (
                                <Button 
                                    size="sm" 
                                    variant={attempt.metadata?.has_key_error ? "danger" : "warning"} 
                                    icon={RefreshCw}
                                    onClick={handleAiEvaluation}
                                    className={attempt.metadata?.has_key_error ? "animate-pulse" : ""}
                                >
                                    {attempt.metadata?.has_key_error ? "🚨 Intercept & Resolve Flagged" : "Intercept & Re-evaluate All"}
                                </Button>
                            )}
                        </div>
                        <div className="grid grid-cols-2 gap-sm mb-lg">
                            <div style={{ padding: 'var(--space-md)', background: 'var(--card)', borderRadius: 'var(--radius-md)', textAlign: 'center' }}>
                                <p style={{ fontSize: 'var(--text-2xl)', fontWeight: 700, margin: 0, color: attempt.passed ? 'var(--success-500)' : 'var(--error-500)' }}>
                                    {Math.round((attempt.quiz.questions.reduce((acc, q, idx) => {
                                        const userAnswer = attempt.answers[idx];
                                        const override = overrides[idx];
                                        
                                        if (q.type === 'short') {
                                            const isCorrect = override !== undefined ? override : false;
                                            return acc + (isCorrect ? 1 : 0);
                                        }
                                        // For MCQ/Boolean, overrides can still happen but usually we use userAnswer
                                        const isCorrect = override !== undefined ? override : (userAnswer === q.correctAnswer);
                                        return acc + (isCorrect ? 1 : 0);
                                    }, 0) / attempt.total) * 100)}%
                                </p>
                                <p style={{ fontSize: 'var(--text-xs)', color: 'var(--text-muted)', margin: 0 }}>Score</p>
                            </div>
                            <div style={{ padding: 'var(--space-md)', background: 'var(--card)', borderRadius: 'var(--radius-md)', textAlign: 'center' }}>
                                <p style={{ fontSize: 'var(--text-2xl)', fontWeight: 700, margin: 0 }}>
                                    {attempt.quiz.questions.reduce((acc, q, idx) => {
                                        const userAnswer = attempt.answers[idx];
                                        const override = overrides[idx];
                                        
                                        if (q.type === 'short') {
                                            const isCorrect = override !== undefined ? override : false;
                                            return acc + (isCorrect ? 1 : 0);
                                        }
                                        const isCorrect = override !== undefined ? override : (userAnswer === q.correctAnswer);
                                        return acc + (isCorrect ? 1 : 0);
                                    }, 0)}/{attempt.total}
                                </p>
                                <p style={{ fontSize: 'var(--text-xs)', color: 'var(--text-muted)', margin: 0 }}>Correct</p>
                            </div>
                        </div>

                        {Object.keys(overrides).length > 0 && (
                            <>
                                <Button 
                                    variant="success" 
                                    style={{ width: '100%' }} 
                                    loading={saving}
                                    onClick={async () => {
                                        setSaving(true);
                                        try {
                                            const finalCorrect = attempt.quiz.questions.reduce((acc, q, idx) => {
                                                const userAnswer = attempt.answers[idx];
                                                const override = overrides[idx];
                                                
                                                if (q.type === 'short') {
                                                    const isCorrect = override !== undefined ? override : false;
                                                    return acc + (isCorrect ? 1 : 0);
                                                }
                                                const isCorrect = override !== undefined ? override : (userAnswer === q.correctAnswer);
                                                return acc + (isCorrect ? 1 : 0);
                                            }, 0);
                                            const finalScore = Math.round((finalCorrect / attempt.total) * 100);
                                            const xpToAward = Math.round((finalCorrect / attempt.total) * (attempt.quizzes?.points || 100));

                                            // Update the saved attempt with Manual results
                                            await db.updateQuizAttempt(attempt.id, {
                                                correct: finalCorrect,
                                                score: finalScore,
                                                passed: finalScore >= 70,
                                                metadata: {
                                                    ...attempt.metadata,
                                                    manually_evaluated: true,
                                                    overrides,
                                                    manual_feedback: manualFeedback,
                                                    finalized: true,
                                                    xp_earned: xpToAward
                                                }
                                            });

                                            // Update the user's profile XP
                                            await db.updateProfile(attempt.user_id, {
                                                xp: (attempt.profiles?.xp || 0) + xpToAward
                                            });

                                            // --- NOTIFY STUDENT ---
                                            await db.createNotification({
                                                user_id: attempt.user_id,
                                                title: 'Quiz Evaluated! 🧠',
                                                message: `Your attempt on "${attempt.quizzes?.title}" has been reviewed. Final Score: ${finalScore}% (+${xpToAward} XP)`,
                                                type: 'success',
                                                link: `/quizzes`,
                                                is_read: false,
                                                created_at: new Date().toISOString()
                                            });

                                            setSuccess(true);
                                            if (onUpdate) onUpdate(); // Real-time update parent list
                                            setTimeout(() => setSuccess(false), 3000);
                                            loadAttempt();
                                        } catch (e) {
                                            console.error('Save Error:', e);
                                            alert('Failed to save evaluation');
                                        } finally {
                                            setSaving(false);
                                        }
                                    }}
                                >
                                    {success ? '✓ Saved Successfully!' : '💾 Save Changes (Draft)'}
                                </Button>
                                
                                {!attempt.metadata?.finalized && (
                                    <Button 
                                        variant="primary" 
                                        style={{ width: '100%' }} 
                                        loading={saving}
                                        onClick={async () => {
                                            if (!window.confirm('Finalize this evaluation? The student will be able to see their final score and this cannot be undone.')) {
                                                return;
                                            }
                                            
                                            setSaving(true);
                                            try {
                                                const finalCorrect = attempt.quiz.questions.reduce((acc, q, idx) => {
                                                    const userAnswer = attempt.answers[idx];
                                                    const override = overrides[idx];
                                                    
                                                    if (q.type === 'short') {
                                                        const isCorrect = override !== undefined ? override : false;
                                                        return acc + (isCorrect ? 1 : 0);
                                                    }
                                                    
                                                    // Standardize for boolean and multiple choice
                                                    const isCorrect = override !== undefined 
                                                        ? override 
                                                        : (q.type === 'boolean' 
                                                            ? String(userAnswer) === String(q.correctAnswer)
                                                            : userAnswer === q.correctAnswer);
                                                            
                                                    return acc + (isCorrect ? 1 : 0);
                                                }, 0);
                                                const finalScore = Math.round((finalCorrect / attempt.total) * 100);
                                                const xpToAward = Math.round((finalCorrect / attempt.total) * (attempt.quizzes?.points || 100));
                                                
                                                // Update the saved attempt with Manual results AND finalize
                                                await db.updateQuizAttempt(attempt.id, {
                                                    correct: finalCorrect,
                                                    score: finalScore,
                                                    passed: finalScore >= 70,
                                                    metadata: { 
                                                        ...attempt.metadata, 
                                                        manually_evaluated: true, 
                                                        overrides, 
                                                        manual_feedback: manualFeedback,
                                                        finalized: true,
                                                        xp_earned: xpToAward
                                                    }
                                                });

                                                // Update the user's profile XP
                                                await db.updateProfile(attempt.user_id, {
                                                    xp: (attempt.profiles?.xp || 0) + xpToAward
                                                });

                                                // --- NOTIFY STUDENT ---
                                                await db.createNotification({
                                                    user_id: attempt.user_id,
                                                    title: '✅ Quiz Finalized!',
                                                    message: `Your quiz "${attempt.quizzes?.title}" has been finalized! Final Score: ${finalScore}% (+${xpToAward} XP). You can now view your detailed results.`,
                                                    type: 'success',
                                                    link: `/quizzes/${attempt.quiz_id}`,
                                                    is_read: false,
                                                    created_at: new Date().toISOString()
                                                });

                                                setSuccess(true);
                                                if (onUpdate) onUpdate(); // Real-time update parent list
                                                setTimeout(() => {
                                                    setSuccess(false);
                                                    onBack(); // Return to list after finalization
                                                }, 2000);
                                                loadAttempt();
                                            } catch (e) {
                                                console.error('Finalize Error:', e);
                                                alert('Failed to finalize evaluation');
                                            } finally {
                                                setSaving(false);
                                            }
                                        }}
                                    >
                                        {success ? '✓ Finalized!' : '🎯 Finalize & Release to Student'}
                                    </Button>
                                )}
                                
                                {attempt.metadata?.finalized && (
                                    <div style={{ 
                                        padding: 'var(--space-md)', 
                                        background: 'rgba(34, 197, 94, 0.1)', 
                                        borderRadius: 'var(--radius-md)',
                                        border: '1px solid rgba(34, 197, 94, 0.3)',
                                        textAlign: 'center',
                                        fontSize: 'var(--text-sm)',
                                        color: 'var(--success-600)',
                                        fontWeight: 600
                                    }}>
                                        ✓ This evaluation has been finalized. Student can view their results.
                                    </div>
                                )}
                            </>
                        )}


                    </Card>

                    {aiReport && (
                        <Card style={{ border: '1px solid #a78bfa', background: 'rgba(167, 139, 250, 0.05)' }}>
                            <div className="flex items-center gap-sm mb-md">
                                <Brain size={20} color="#8b5cf6" />
                                <h4 style={{ margin: 0, color: '#7c3aed' }}>AI Mentor Report</h4>
                                <Badge style={{ marginLeft: 'auto', background: '#7c3aed' }}>Grade: {aiReport.overallGrade}</Badge>
                            </div>
                            <p style={{ fontSize: 'var(--text-sm)', marginBottom: 'var(--space-md)' }}>
                                {aiReport.summary}
                            </p>
                            <div style={{ padding: 'var(--space-sm)', background: 'var(--surface)', borderRadius: 'var(--radius-md)', border: '1px dashed #a78bfa' }}>
                                <p style={{ margin: 0, fontSize: 'var(--text-xs)', fontWeight: 600, color: '#7c3aed', marginBottom: '4px' }}>MENTOR NOTE:</p>
                                <p style={{ margin: 0, fontSize: 'var(--text-xs)', fontStyle: 'italic' }}>{aiReport.mentorNote}</p>
                            </div>
                        </Card>
                    )}

                    <Card>
                        <h4 style={{ marginBottom: 'var(--space-md)' }}>
                            <MessageSquare size={18} style={{ marginRight: '8px', verticalAlign: 'middle' }} />
                            Your Manual Feedback
                        </h4>
                        <Input
                            type="textarea"
                            placeholder="Add your own assessment or notes for the student..."
                            value={manualFeedback}
                            onChange={(e) => setManualFeedback(e.target.value)}
                            style={{ minHeight: '120px' }}
                        />
                    </Card>
                </div>

                {/* Answers Review */}
                <Card>
                    <div style={{ marginBottom: 'var(--space-md)' }}>
                        <h4 style={{ marginBottom: 'var(--space-sm)' }}>Question Review</h4>
                        <div style={{ 
                            display: 'flex', 
                            gap: 'var(--space-md)', 
                            fontSize: 'var(--text-xs)', 
                            color: 'var(--text-muted)',
                            padding: 'var(--space-sm)',
                            background: 'var(--surface)',
                            borderRadius: 'var(--radius-md)'
                        }}>
                            <span style={{ display: 'flex', alignItems: 'center', gap: '4px' }}>
                                <div style={{ width: '12px', height: '12px', background: 'var(--success-500)', borderRadius: '2px' }}></div>
                                Correct
                            </span>
                            <span style={{ display: 'flex', alignItems: 'center', gap: '4px' }}>
                                <div style={{ width: '12px', height: '12px', background: 'var(--error-500)', borderRadius: '2px' }}></div>
                                Wrong
                            </span>
                            <span style={{ display: 'flex', alignItems: 'center', gap: '4px' }}>
                                <div style={{ width: '12px', height: '12px', background: '#3b82f6', borderRadius: '2px' }}></div>
                                AI Suggestion
                            </span>
                        </div>
                    </div>
                    <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-lg)' }}>
                        {attempt.quiz?.questions.map((q, index) => {
                            const userAnswer = attempt.answers[index];
                            // Check manual override first, then AI suggestion, then basic match
                            const isCorrect = overrides[index] !== undefined 
                                ? overrides[index] 
                                : (q.type === 'short' ? false : (q.type === 'boolean' ? String(userAnswer) === String(q.correctAnswer) : userAnswer === q.correctAnswer));
                            
                            const aiSuggestion = aiReport?.suggestions?.find(s => Number(s.questionIndex) === Number(index));
                            
                            return (
                                <div key={index} style={{
                                    padding: 'var(--space-md)',
                                    background: 'var(--card)',
                                    borderRadius: 'var(--radius-lg)',
                                    borderLeft: `4px solid ${
                                        aiSuggestion && overrides[index] !== undefined 
                                            ? '#3b82f6' // Blue for AI-suggested changes
                                            : isCorrect ? 'var(--success-500)' : 'var(--error-500)'
                                    }`
                                }}>
                                    {aiSuggestion?.isKeyError && (
                                        <div style={{ 
                                            padding: 'var(--space-sm)', 
                                            background: 'var(--error-50)', 
                                            border: '1px solid var(--error-200)', 
                                            borderRadius: 'var(--radius-md)',
                                            marginBottom: 'var(--space-sm)',
                                            display: 'flex',
                                            justifyContent: 'space-between',
                                            alignItems: 'center',
                                            boxShadow: '0 4px 12px rgba(239, 68, 68, 0.1)'
                                        }}>
                                            <div style={{ display: 'flex', gap: '8px', alignItems: 'center' }}>
                                                <AlertTriangle size={18} color="var(--error-500)" />
                                                <div style={{ display: 'flex', flexDirection: 'column' }}>
                                                    <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                                                        <span style={{ fontSize: 'var(--text-xs)', color: 'var(--error-700)', fontWeight: 700 }}>
                                                            AI ALERT: This Question Key may be wrong!
                                                        </span>
                                                        {aiSuggestion.isCorrect && (
                                                            <span style={{ 
                                                                fontSize: '10px', 
                                                                background: 'var(--success-500)', 
                                                                color: 'white', 
                                                                padding: '2px 8px', 
                                                                borderRadius: '999px',
                                                                fontWeight: 800,
                                                                textTransform: 'uppercase',
                                                                letterSpacing: '0.05em',
                                                                boxShadow: '0 2px 4px rgba(16, 185, 129, 0.2)'
                                                            }}>
                                                                Student Deserves Points! 🏆
                                                            </span>
                                                        )}
                                                    </div>
                                                    <span style={{ fontSize: '11px', color: 'var(--error-600)' }}>
                                                        {aiSuggestion.feedback}
                                                    </span>
                                                </div>
                                            </div>
                                            <Button 
                                                size="xs" 
                                                variant="success" 
                                                icon={CheckCircle}
                                                className="animate-bounce-subtle"
                                                onClick={() => {
                                                    const newValue = aiSuggestion.isCorrect !== undefined ? aiSuggestion.isCorrect : true;
                                                    setOverrides(prev => ({ 
                                                        ...prev, 
                                                        [index]: newValue 
                                                    }));
                                                }}
                                            >
                                                {aiSuggestion.isCorrect ? "Apply AI Fix & Award Point" : "Apply AI Fix"}
                                            </Button>
                                        </div>
                                    )}

                                    <div className="flex justify-between items-start" style={{ marginBottom: 'var(--space-md)' }}>
                                        <p style={{ fontWeight: 600, margin: 0, flex: 1 }}>
                                            {index + 1}. {q.question}
                                        </p>
                                        <div style={{ 
                                            marginLeft: 'var(--space-md)',
                                            display: 'flex',
                                            flexDirection: 'column',
                                            alignItems: 'flex-end',
                                            gap: '4px'
                                        }}>
                                            {(() => {
                                                const originalCorrect = q.type === 'short' 
                                                    ? false 
                                                    : (q.type === 'boolean' 
                                                        ? String(attempt.answers[index]) === String(q.correctAnswer)
                                                        : attempt.answers[index] === q.correctAnswer);
                                                const currentCorrect = overrides[index] !== undefined ? overrides[index] : originalCorrect;
                                                const hasChange = originalCorrect !== currentCorrect;

                                                return (
                                                    <div style={{ 
                                                        display: 'flex', 
                                                        alignItems: 'center', 
                                                        gap: '8px',
                                                        padding: '6px 12px',
                                                        background: 'var(--surface)',
                                                        borderRadius: 'var(--radius-lg)',
                                                        border: '1px solid var(--border)'
                                                    }}>
                                                        {/* Original */}
                                                        <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
                                                            <span style={{ fontSize: '9px', color: 'var(--text-muted)', textTransform: 'uppercase', fontWeight: 700 }}>Org</span>
                                                            <span style={{ 
                                                                color: originalCorrect ? 'var(--success-500)' : 'var(--error-500)', 
                                                                fontWeight: 800,
                                                                fontSize: 'var(--text-lg)'
                                                            }}>
                                                                {originalCorrect ? '+1' : '-1'}
                                                            </span>
                                                        </div>

                                                        {hasChange && (
                                                            <div style={{ color: 'var(--text-muted)', display: 'flex', alignItems: 'center' }}>
                                                                <ChevronRight size={16} />
                                                            </div>
                                                        )}

                                                        {/* Current/AI */}
                                                        <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
                                                            <span style={{ fontSize: '9px', color: 'var(--text-muted)', textTransform: 'uppercase', fontWeight: 700 }}>New</span>
                                                            <div style={{ display: 'flex', alignItems: 'center', gap: '4px' }}>
                                                                {aiSuggestion && !hasChange && (
                                                                    <Brain size={12} color="#3b82f6" />
                                                                )}
                                                                <span style={{ 
                                                                    color: currentCorrect ? 'var(--success-500)' : 'var(--error-500)', 
                                                                    fontWeight: 800,
                                                                    fontSize: 'var(--text-lg)'
                                                                }}>
                                                                    {currentCorrect ? '+1' : '-1'}
                                                                </span>
                                                            </div>
                                                        </div>
                                                    </div>
                                                );
                                            })()}
                                            
                                            {/* Manual Override Buttons */}
                                            <div style={{ display: 'flex', gap: '4px' }}>
                                                <Button 
                                                    size="xs" 
                                                    variant={overrides[index] === true ? "success" : "ghost"}
                                                    onClick={() => setOverrides(prev => ({ ...prev, [index]: true }))}
                                                    title="Manually Award Point"
                                                >
                                                    <Check size={14} />
                                                </Button>
                                                <Button 
                                                    size="xs" 
                                                    variant={overrides[index] === false ? "danger" : "ghost"}
                                                    onClick={() => setOverrides(prev => ({ ...prev, [index]: false }))}
                                                    title="Manually Deduct Point"
                                                >
                                                    <X size={14} />
                                                </Button>
                                                {overrides[index] !== undefined && (
                                                    <Button 
                                                        size="xs" 
                                                        variant="ghost"
                                                        onClick={() => {
                                                            const newOverrides = { ...overrides };
                                                            delete newOverrides[index];
                                                            setOverrides(newOverrides);
                                                        }}
                                                        title="Reset to Original"
                                                    >
                                                        <RefreshCw size={12} />
                                                    </Button>
                                                )}
                                            </div>
                                        </div>
                                    </div>
                                        {q.type === 'multiple' ? (
                                            q.options.map((opt, optIndex) => {
                                                // State variables for clarity
                                                const isCorrectKey = q.type === 'boolean' 
                                                    ? String(optIndex) === String(q.correctAnswer)
                                                    : optIndex === q.correctAnswer;
                                                const isStudentChoice = q.type === 'boolean'
                                                    ? String(optIndex) === String(userAnswer)
                                                    : optIndex === userAnswer;
                                                const aiRecommendsCorrect = aiSuggestion?.isCorrect && isStudentChoice;
                                                
                                                return (
                                                    <div key={optIndex} style={{
                                                        fontSize: 'var(--text-sm)',
                                                        padding: '6px 12px',
                                                        borderRadius: 'var(--radius-md)',
                                                        marginBottom: '4px',
                                                        display: 'flex',
                                                        alignItems: 'center',
                                                        gap: '12px',
                                                        background: isStudentChoice ? 'var(--surface)' : 'transparent',
                                                        border: isStudentChoice ? '1px solid var(--border)' : '1px solid transparent'
                                                    }}>
                                                        <div style={{ display: 'flex', alignItems: 'center', minWidth: '80px', gap: '4px' }}>
                                                            {isCorrectKey && (
                                                                <Badge size="xs" variant="success" style={{ fontSize: '8px' }}>KEY</Badge>
                                                            )}
                                                            {isStudentChoice && (
                                                                <Badge size="xs" variant="primary" style={{ fontSize: '8px' }}>CHOICE</Badge>
                                                            )}
                                                        </div>

                                                        <span style={{ 
                                                            flex: 1,
                                                            color: isCorrectKey ? 'var(--success-500)' : (isStudentChoice && !aiRecommendsCorrect ? 'var(--error-500)' : 'var(--text-main)'),
                                                            fontWeight: (isCorrectKey || isStudentChoice) ? 600 : 400
                                                        }}>
                                                            {opt}
                                                        </span>

                                                        <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                                                            {/* Original System Status */}
                                                            <div style={{ display: 'flex', alignItems: 'center', color: isCorrectKey ? 'var(--success-500)' : (isStudentChoice ? 'var(--error-500)' : 'var(--text-muted)') }}>
                                                                {isCorrectKey ? <Check size={14} /> : (isStudentChoice ? <X size={14} /> : null)}
                                                            </div>

                                                            {/* AI Transition */}
                                                            {aiRecommendsCorrect && (
                                                                <>
                                                                    <div style={{ color: 'var(--text-muted)' }}>➔</div>
                                                                    <div style={{ 
                                                                        display: 'flex', 
                                                                        alignItems: 'center', 
                                                                        gap: '4px', 
                                                                        color: '#3b82f6',
                                                                        fontWeight: 700,
                                                                        padding: '2px 8px',
                                                                        background: 'rgba(59, 130, 246, 0.1)',
                                                                        borderRadius: '4px'
                                                                    }}>
                                                                        <Check size={14} />
                                                                        <span style={{ fontSize: '10px' }}>AI VALIDATED</span>
                                                                    </div>
                                                                </>
                                                            )}
                                                        </div>
                                                    </div>
                                                );
                                            })
                                        ) : q.type === 'boolean' ? (
                                            <div style={{ fontSize: 'var(--text-sm)' }}>
                                                <div style={{ display: 'flex', gap: '12px', marginBottom: '12px' }}>
                                                    <div style={{ display: 'flex', alignItems: 'center', gap: '4px' }}>
                                                        {q.correctAnswer === true && <Badge size="xs" variant="success" style={{ fontSize: '8px' }}>KEY</Badge>}
                                                        <span style={{ color: q.correctAnswer === true ? 'var(--success-500)' : 'var(--text-muted)', fontWeight: q.correctAnswer === true ? 600 : 400 }}>True</span>
                                                    </div>
                                                    <div style={{ display: 'flex', alignItems: 'center', gap: '4px' }}>
                                                        {q.correctAnswer === false && <Badge size="xs" variant="success" style={{ fontSize: '8px' }}>KEY</Badge>}
                                                        <span style={{ color: q.correctAnswer === false ? 'var(--success-500)' : 'var(--text-muted)', fontWeight: q.correctAnswer === false ? 600 : 400 }}>False</span>
                                                    </div>
                                                </div>
                                                
                                                <div style={{ 
                                                    padding: '12px', 
                                                    background: 'var(--surface)', 
                                                    borderRadius: 'var(--radius-md)',
                                                    border: '1px solid var(--border)',
                                                    display: 'flex',
                                                    justifyContent: 'space-between',
                                                    alignItems: 'center'
                                                }}>
                                                    <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
                                                        <Badge size="xs" variant="primary">STUDENT CHOICE</Badge>
                                                        <span style={{ fontWeight: 600 }}>{userAnswer === true ? 'True' : 'False'}</span>
                                                        {isCorrect ? <Check size={16} color="var(--success-500)" /> : <X size={16} color="var(--error-500)" />}
                                                    </div>

                                                    {aiSuggestion?.isCorrect && (
                                                        <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                                                            <div style={{ color: 'var(--text-muted)' }}>➔</div>
                                                            <div style={{ 
                                                                display: 'flex', 
                                                                alignItems: 'center', 
                                                                gap: '6px',
                                                                color: '#3b82f6',
                                                                fontWeight: 700,
                                                                padding: '4px 10px',
                                                                background: 'rgba(59, 130, 246, 0.1)',
                                                                borderRadius: '6px'
                                                            }}>
                                                                <Brain size={14} />
                                                                <span>AI CORRECTED</span>
                                                            </div>
                                                        </div>
                                                    )}
                                                </div>
                                            </div>
                                        ) : (
                                            <div style={{ fontSize: 'var(--text-sm)' }}>
                                                <div style={{ padding: 'var(--space-sm)', background: 'var(--surface)', borderRadius: 'var(--radius-md)', border: '1px solid var(--border)', marginBottom: 'var(--space-sm)' }}>
                                                    <p style={{ margin: 0, color: 'var(--text-muted)', fontSize: 'var(--text-xs)' }}>Expected Answer:</p>
                                                    <p style={{ margin: 0, fontWeight: 600, color: 'var(--success-500)' }}>{q.correctAnswer}</p>
                                                </div>
                                                <div style={{ padding: 'var(--space-sm)', background: 'var(--surface)', borderRadius: 'var(--radius-md)', border: `1px solid ${isCorrect ? 'var(--success-500)' : 'var(--error-500)'}` }}>
                                                    <p style={{ margin: 0, color: 'var(--text-muted)', fontSize: 'var(--text-xs)' }}>Student Answer:</p>
                                                    <p style={{ margin: 0, fontWeight: 600 }}>{userAnswer || '(No answer)'}</p>
                                                </div>
                                                
                                                    {/* AI Badge & Glow logic */}
                                                    {(() => {
                                                        const suggestion = aiReport?.suggestions?.find(s => Number(s.questionIndex) === Number(index));
                                                        const aiIsCorrect = suggestion?.isCorrect;
                                                        
                                                        return (
                                                            <div className="flex flex-mobile-col gap-sm mt-md w-full">
                                                                <div className="flex gap-sm w-full">
                                                                    <Button 
                                                                        size="md" 
                                                                        variant={
                                                                            (overrides[index] === true || overrides[index.toString()] === true) 
                                                                                ? (aiIsCorrect === true ? 'primary' : 'success')
                                                                                : 'secondary'
                                                                        }
                                                                        style={{ 
                                                                            flex: 1,
                                                                            minHeight: '48px',
                                                                            background: (overrides[index] === true || overrides[index.toString()] === true) 
                                                                                ? (aiIsCorrect === true ? '#3b82f6' : 'var(--success-500)')
                                                                                : '',
                                                                            color: (overrides[index] === true || overrides[index.toString()] === true) ? 'white' : ''
                                                                        }}
                                                                        onClick={() => setOverrides(prev => ({ ...prev, [index]: true }))}
                                                                        icon={Check}
                                                                    >
                                                                        Correct {aiIsCorrect === true && '(AI)'}
                                                                    </Button>
                                                                    <Button 
                                                                        size="md" 
                                                                        variant={
                                                                            (overrides[index] === false || overrides[index.toString()] === false) 
                                                                                ? (aiIsCorrect === false ? 'primary' : 'danger')
                                                                                : 'secondary'
                                                                        }
                                                                        style={{ 
                                                                            flex: 1,
                                                                            minHeight: '48px',
                                                                            background: (overrides[index] === false || overrides[index.toString()] === false) 
                                                                                ? (aiIsCorrect === false ? '#3b82f6' : 'var(--error-500)')
                                                                                : '',
                                                                            color: (overrides[index] === false || overrides[index.toString()] === false) ? 'white' : ''
                                                                        }}
                                                                        onClick={() => setOverrides(prev => ({ ...prev, [index]: false }))}
                                                                        icon={X}
                                                                    >
                                                                        Wrong {aiIsCorrect === false && '(AI)'}
                                                                    </Button>
                                                                </div>

                                                                {suggestion && (
                                                                    <Badge 
                                                                        variant="outline"
                                                                        style={{ 
                                                                            borderColor: '#3b82f6',
                                                                            color: '#3b82f6',
                                                                            background: 'rgba(59, 130, 246, 0.1)',
                                                                            display: 'flex',
                                                                            alignItems: 'center',
                                                                            gap: '4px',
                                                                            padding: '4px 8px',
                                                                            fontWeight: 600
                                                                        }}
                                                                    >
                                                                        <Brain size={12} />
                                                                        AI: {aiIsCorrect ? '✓ Correct' : '✗ Wrong'}
                                                                    </Badge>
                                                                )}
                                                            </div>
                                                        );
                                                    })()}

                                                {aiReport && aiReport.suggestions.find(s => Number(s.questionIndex) === Number(index)) && (
                                                    <div style={{ marginTop: 'var(--space-md)', padding: 'var(--space-sm)', background: 'rgba(167, 139, 250, 0.1)', borderRadius: 'var(--radius-md)', border: '1px solid rgba(167, 139, 250, 0.2)' }}>
                                                        <div className="flex items-center gap-xs mb-xs">
                                                            <Brain size={12} color="#8b5cf6" />
                                                            <span style={{ fontSize: 'var(--text-xs)', fontWeight: 700, color: '#7c3aed' }}>AI SUGGESTION</span>
                                                        </div>
                                                        <p style={{ margin: 0, fontSize: 'var(--text-xs)', color: 'var(--text-main)' }}>
                                                            {aiReport.suggestions.find(s => Number(s.questionIndex) === Number(index)).feedback}
                                                        </p>
                                                        <p style={{ margin: '4px 0 0', fontSize: 'var(--text-xs)', color: 'var(--text-muted)', fontStyle: 'italic' }}>
                                                            Tip: {aiReport.suggestions.find(s => Number(s.questionIndex) === Number(index)).improvementTip}
                                                        </p>
                                                    </div>
                                                )}
                                            </div>
                                        )}
                                    </div>
                                );
                            })}
                    </div>
                </Card>
            </div>
        </div>
    );
};

export default EvaluationCenter;

import { useState, useEffect } from 'react';
import { Card, Button, Badge, Modal, Input } from '../../components/common';
import {
    Plus,
    Trash2,
    Copy,
    Users,
    Key,
    CheckCircle,
    XCircle,
    Calendar,
    School,
    RotateCcw
} from 'lucide-react';
import * as inviteCodes from '../../services/inviteCodes';
import * as db from '../../services/database';
import { useAuth } from '../../context/AuthContext';

const InviteCodes = () => {
    const { user } = useAuth();
    const [codes, setCodes] = useState([]);
    const [classrooms, setClassrooms] = useState([]);
    const [selectedClassroom, setSelectedClassroom] = useState(user?.classroom_id || '');

    const [showCreateModal, setShowCreateModal] = useState(false);
    const [newCode, setNewCode] = useState('');
    const [customCode, setCustomCode] = useState('');
    const [useCustom, setUseCustom] = useState(false);
    const [quantity, setQuantity] = useState(1);
    const [loading, setLoading] = useState(false);
    const [copiedCode, setCopiedCode] = useState('');

    useEffect(() => {
        loadData();
    }, []);

    // Update selected classroom when user context changes or modal opens
    useEffect(() => {
        if (user?.classroom_id) {
            setSelectedClassroom(user.classroom_id);
        }
    }, [user?.classroom_id, showCreateModal]);

    const loadData = async () => {
        const [inviteCodeList, classroomList] = await Promise.all([
            inviteCodes.getInviteCodes(),
            db.getClassrooms()
        ]);
        setCodes(inviteCodeList);
        setClassrooms(classroomList);
    };

    const handleCreateCode = async () => {
        setLoading(true);
        console.log('InviteCodes: Starting creation process...', { useCustom, quantity, selectedClassroom, userClassroom: user?.classroom_id });
        
        try {
            const targetClassroomId = selectedClassroom || user?.classroom_id;
            
            if (!targetClassroomId) {
                console.warn('InviteCodes: No classroom ID found.');
                throw new Error('Please select a classroom first.');
            }

            if (useCustom) {
                if (!customCode) throw new Error('Please enter a custom code.');
                const code = customCode.toUpperCase();
                console.log('InviteCodes: Creating custom code:', code);
                await inviteCodes.createInviteCode(code, targetClassroomId);
            } else {
                // Bulk or Single Random
                console.log(`InviteCodes: Creating ${quantity} random codes for classroom ${targetClassroomId}`);
                const promises = [];
                for (let i = 0; i < quantity; i++) {
                    const code = (i === 0 && newCode) ? newCode : Math.random().toString(36).substring(2, 8).toUpperCase();
                    promises.push(inviteCodes.createInviteCode(code, targetClassroomId));
                }
                await Promise.all(promises);
            }

            console.log('InviteCodes: Success! Reloading data...');
            await loadData();
            setShowCreateModal(false);
            setNewCode('');
            setCustomCode('');
            setUseCustom(false);
            setQuantity(1);
            alert('Invite code(s) created successfully!');
        } catch (error) {
            console.error('InviteCodes: Creation failed:', error);
            alert('Failed to create invite code: ' + error.message);
        } finally {
            setLoading(false);
        }
    };

    const handleDeleteCode = async (id, codeStr) => {
        if (confirm(`Are you sure you want to delete invite code "${codeStr}"?`)) {
            setLoading(true);
            try {
                const success = await inviteCodes.deleteInviteCode(id);
                if (success) {
                    setCodes(codes.filter(c => c.id !== id));
                } else {
                    alert('Failed to delete invite code. You might not have permission or it might already be deleted.');
                }
            } catch (error) {
                console.error('Error deleting code:', error);
                alert('Error deleting code: ' + error.message);
            } finally {
                setLoading(false);
            }
        }
    };

    const handleClearUsed = async () => {
        if (confirm('Delete all used invite codes? This cannot be undone.')) {
            setLoading(true);
            try {
                const usedCodes = codes.filter(c => c.is_used);
                const results = await Promise.all(usedCodes.map(c => inviteCodes.deleteInviteCode(c.id)));

                if (results.every(r => r)) {
                    await loadData();
                } else {
                    alert('Some used codes could not be deleted.');
                    await loadData();
                }
            } catch (error) {
                console.error('Error clearing codes:', error);
                alert('Error clearing codes: ' + error.message);
            } finally {
                setLoading(false);
            }
        }
    };

    const handleCopyCode = (code) => {
        navigator.clipboard.writeText(code);
        setCopiedCode(code);
        setTimeout(() => setCopiedCode(''), 2000);
    };

    const generateRandomCode = () => {
        const random = Math.random().toString(36).substring(2, 8).toUpperCase();
        setNewCode(random);
    };

    const stats = {
        total: codes.length,
        used: codes.filter(c => c.is_used).length,
        available: codes.filter(c => !c.is_used).length
    };

    const currentClassroomName = classrooms.find(c => c.id === selectedClassroom)?.name || user?.classroom_name;

    return (
        <div className="animate-fade-in">
            {/* Header */}
            <div className="flex flex-mobile-col justify-between items-center mb-lg">
                <div>
                    <h2 style={{ margin: 0, marginBottom: '4px' }}>
                        Invite Codes
                        {user?.classroom_name && <span className="text-muted text-lg font-normal ml-sm">for {user.classroom_name}</span>}
                    </h2>
                    <p style={{ color: 'var(--text-muted)', margin: 0 }}>
                        Manage registration invite codes for your friends in this classroom
                    </p>
                </div>
                <div className="flex gap-sm">
                    <Button variant="ghost" onClick={loadData} title="Refresh List">
                        <RotateCcw size={18} />
                    </Button>
                    {codes.some(c => c.is_used) && (
                        <Button variant="danger" onClick={handleClearUsed} title="Delete all used codes">
                            Clear Used
                        </Button>
                    )}
                    <Button icon={Plus} onClick={() => setShowCreateModal(true)}>
                        Create Code
                    </Button>
                </div>
            </div>

            {/* Stats */}
            <div className="grid grid-cols-3 grid-3-mobile-1 mb-xl">
                <Card style={{ textAlign: 'center' }}>
                    <Key size={24} style={{ color: 'var(--primary-500)', marginBottom: '8px' }} />
                    <h3 style={{ margin: 0, fontSize: 'var(--text-2xl)' }}>{stats.total}</h3>
                    <p style={{ margin: 0, fontSize: 'var(--text-sm)', color: 'var(--text-muted)' }}>
                        Total Codes
                    </p>
                </Card>
                <Card style={{ textAlign: 'center' }}>
                    <CheckCircle size={24} style={{ color: 'var(--success-500)', marginBottom: '8px' }} />
                    <h3 style={{ margin: 0, fontSize: 'var(--text-2xl)' }}>{stats.used}</h3>
                    <p style={{ margin: 0, fontSize: 'var(--text-sm)', color: 'var(--text-muted)' }}>
                        Used Codes
                    </p>
                </Card>
                <Card style={{ textAlign: 'center' }}>
                    <Users size={24} style={{ color: 'var(--warning-500)', marginBottom: '8px' }} />
                    <h3 style={{ margin: 0, fontSize: 'var(--text-2xl)' }}>{stats.available}</h3>
                    <p style={{ margin: 0, fontSize: 'var(--text-sm)', color: 'var(--text-muted)' }}>
                        Available Codes
                    </p>
                </Card>
            </div>

            {/* Codes List */}
            <Card>
                <h3 style={{ marginBottom: 'var(--space-lg)' }}>All Invite Codes</h3>
                {codes.length === 0 ? (
                    <div className="empty-state">
                        <Key size={32} />
                        <h3>No invite codes yet</h3>
                        <p>Create your first invite code to allow friends to register</p>
                        <Button icon={Plus} onClick={() => setShowCreateModal(true)}>
                            Create Code
                        </Button>
                    </div>
                ) : (
                    <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-sm)' }}>
                        {codes.map((code) => (
                            <div
                                key={code.code}
                                style={{
                                    display: 'flex',
                                    alignItems: 'center',
                                    justifyContent: 'space-between',
                                    padding: 'var(--space-md)',
                                    background: 'var(--card)',
                                    border: '1px solid var(--border)',
                                    borderRadius: 'var(--radius-md)'
                                }}
                            >
                                <div style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-md)' }}>
                                    <div style={{
                                        width: '40px',
                                        height: '40px',
                                        borderRadius: 'var(--radius-md)',
                                        background: code.is_used
                                            ? 'rgba(16, 185, 129, 0.1)'
                                            : 'rgba(99, 102, 241, 0.1)',
                                        display: 'flex',
                                        alignItems: 'center',
                                        justifyContent: 'center'
                                    }}>
                                        {code.is_used ? (
                                            <CheckCircle size={20} style={{ color: 'var(--success-500)' }} />
                                        ) : (
                                            <Key size={20} style={{ color: 'var(--primary-500)' }} />
                                        )}
                                    </div>
                                    <div>
                                        <div style={{ fontWeight: 600, fontSize: 'var(--text-lg)' }}>
                                            {code.code}
                                        </div>
                                        <div style={{ fontSize: 'var(--text-sm)', color: 'var(--text-muted)' }}>
                                            {code.is_used ? 'Used' : 'Available'}
                                            {code.classroom_id && (
                                                <span style={{ marginLeft: '8px', opacity: 0.8 }}>
                                                    • {classrooms.find(c => c.id === code.classroom_id)?.name || 'Classroom'}
                                                </span>
                                            )}
                                            {!code.classroom_id && (
                                                <span style={{ marginLeft: '8px', opacity: 0.8 }}>
                                                    • Global
                                                </span>
                                            )}
                                        </div>
                                    </div>
                                </div>
                                <div style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-sm)' }}>
                                    {code.is_used && (
                                        <Badge variant="success" style={{ fontSize: '10px' }}>
                                            Used
                                        </Badge>
                                    )}
                                    <Button
                                        variant="ghost"
                                        size="icon"
                                        onClick={() => handleCopyCode(code.code)}
                                        title="Copy code"
                                    >
                                        <Copy size={16} />
                                    </Button>
                                    <Button
                                        variant="ghost"
                                        size="icon"
                                        onClick={() => handleDeleteCode(code.id, code.code)}
                                        title="Delete code"
                                    >
                                        <Trash2 size={16} />
                                    </Button>
                                </div>
                            </div>
                        ))}
                    </div>
                )}
            </Card>

            {/* Create Modal */}
            <Modal
                isOpen={showCreateModal}
                onClose={() => setShowCreateModal(false)}
                title="Create Invite Code"
                size="sm"
            >
                <form onSubmit={(e) => { e.preventDefault(); handleCreateCode(); }}>
                    <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-md)' }}>
                        <div className="input-group">
                            <label className="input-label">Assign to Classroom</label>
                            <div className="relative">
                                <School size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-muted" />
                                <select
                                    className="input pl-10"
                                    value={selectedClassroom}
                                    onChange={(e) => setSelectedClassroom(e.target.value)}
                                >
                                    <option value="">Global (No Classroom)</option>
                                    {classrooms.map(c => (
                                        <option key={c.id} value={c.id}>
                                            {c.name} {c.id === user?.classroom_id ? '(Current)' : ''}
                                        </option>
                                    ))}
                                </select>
                            </div>
                        </div>

                        <div className="input-group">
                            <label className="input-label">Code Type</label>
                            <div style={{ display: 'flex', gap: 'var(--space-sm)' }}>
                                <label style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-sm)' }}>
                                    <input
                                        type="radio"
                                        checked={!useCustom}
                                        onChange={() => setUseCustom(false)}
                                    />
                                    <span>Random Code</span>
                                </label>
                                <label style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-sm)' }}>
                                    <input
                                        type="radio"
                                        checked={useCustom}
                                        onChange={() => setUseCustom(true)}
                                    />
                                    <span>Custom Code</span>
                                </label>
                            </div>
                        </div>

                        {!useCustom ? (
                            <>
                                <div className="input-group">
                                    <label className="input-label">Random Code Preview</label>
                                    <div style={{ display: 'flex', gap: 'var(--space-sm)' }}>
                                        <Input
                                            value={newCode}
                                            onChange={(e) => setNewCode(e.target.value.toUpperCase())}
                                            placeholder="Generate or enter"
                                            style={{ textTransform: 'uppercase' }}
                                        />
                                        <Button type="button" onClick={generateRandomCode}>
                                            Generate
                                        </Button>
                                    </div>
                                </div>
                                <div className="input-group">
                                    <label className="input-label">Quantity to Generate</label>
                                    <Input
                                        type="number"
                                        min="1"
                                        max="20"
                                        value={quantity}
                                        onChange={(e) => setQuantity(parseInt(e.target.value) || 1)}
                                    />
                                    <p style={{ fontSize: 'var(--text-xs)', color: 'var(--text-muted)', marginTop: '4px' }}>
                                        Generate multiple unique codes at once
                                    </p>
                                </div>
                            </>
                        ) : (
                            <Input
                                label="Custom Code"
                                value={customCode}
                                onChange={(e) => setCustomCode(e.target.value.toUpperCase())}
                                placeholder="Enter custom code"
                                style={{ textTransform: 'uppercase' }}
                            />
                        )}
                    </div>

                    <div className="flex justify-end gap-md" style={{ marginTop: 'var(--space-lg)' }}>
                        <Button type="button" variant="secondary" onClick={() => setShowCreateModal(false)}>
                            Cancel
                        </Button>
                        <Button type="submit" loading={loading}>
                            Create Code
                        </Button>
                    </div>
                </form>
            </Modal>

            {/* Copy Success Toast */}
            {copiedCode && (
                <div style={{
                    position: 'fixed',
                    bottom: '20px',
                    right: '20px',
                    padding: 'var(--space-md)',
                    background: 'var(--success-500)',
                    color: 'white',
                    borderRadius: 'var(--radius-md)',
                    fontSize: 'var(--text-sm)',
                    animation: 'slideInUp 0.3s ease'
                }}>
                    Copied {copiedCode} to clipboard!
                </div>
            )}

        </div>
    );
};

export default InviteCodes;

import { useState, useEffect } from 'react';
import { Card, Button, Badge, Modal, Input, Avatar } from '../../components/common';
import {
    Plus,
    Search,
    Edit2,
    Trash2,
    HelpCircle,
    Clock,
    Award,
    Users,
    GripVertical,
    X,
    Upload
} from 'lucide-react';
import * as db from '../../services/database';
import { useAuth } from '../../context/AuthContext';
import {
    TASK_CATEGORIES,
    DIFFICULTY_LEVELS,
    QUESTION_TYPES,
    getDifficultyColor
} from '../../utils/constants';

const QuizBuilder = () => {
    const { user } = useAuth();
    const [quizzes, setQuizzes] = useState([]);
    const [members, setMembers] = useState([]);
    const [searchQuery, setSearchQuery] = useState('');
    const [showCreateModal, setShowCreateModal] = useState(false);
    const [editingQuiz, setEditingQuiz] = useState(null);
    const [deleteConfirm, setDeleteConfirm] = useState(null);
    const [loading, setLoading] = useState(true);
    const [saving, setSaving] = useState(false);
    const [showCSVGuide, setShowCSVGuide] = useState(false);

    // Form state
    const [formData, setFormData] = useState({
        title: '',
        description: '',
        category: 'Frontend',
        difficulty: 'easy',
        time_limit: 10,
        assigned_to: [],
        questions: [],
        is_global: false,
        assignment_type: 'everyone',
        classroom_id: ''
    });
    const [classrooms, setClassrooms] = useState([]);

    useEffect(() => {
        loadData();
    }, []);

    const loadData = async () => {
        try {
            setLoading(true);
            const [quizzesData, membersData, classroomsData] = await Promise.all([
                db.getQuizzes(),
                db.getMembers(),
                db.getClassrooms()
            ]);
            setQuizzes(quizzesData);
            setMembers(membersData);
            setClassrooms(classroomsData);
        } catch (error) {
            console.error('Error loading data:', error);
        } finally {
            setLoading(false);
        }
    };

    const resetForm = () => {
        setFormData({
            title: '',
            description: '',
            category: 'Frontend',
            difficulty: 'easy',
            time_limit: 10,
            assigned_to: [],
            questions: [],
            is_global: false,
            assignment_type: 'everyone',
            classroom_id: '',
            passing_score: 70
        });
    };

    const openCreateModal = () => {
        resetForm();
        setEditingQuiz(null);
        setShowCreateModal(true);
    };

    const openEditModal = (quiz) => {
        setFormData({
            title: quiz.title,
            description: quiz.description || '',
            category: quiz.category,
            difficulty: quiz.difficulty,
            time_limit: quiz.time_limit,
            assigned_to: quiz.assigned_to || [],
            questions: quiz.questions || [],
            is_global: quiz.is_global || false,
            assignment_type: quiz.assignment_type || (quiz.assigned_to?.length > 0 ? 'specific' : 'everyone'),
            classroom_id: quiz.classroom_id || '',
            passing_score: quiz.passing_score || 70
        });
        setEditingQuiz(quiz);
        setShowCreateModal(true);
    };

    const addQuestion = () => {
        const newQuestion = {
            id: Date.now().toString(),
            type: 'multiple',
            question: '',
            options: ['', '', '', ''],
            correctAnswer: 0
        };
        setFormData(prev => ({
            ...prev,
            questions: [...prev.questions, newQuestion]
        }));
    };

    const updateQuestion = (index, updates) => {
        setFormData(prev => ({
            ...prev,
            questions: prev.questions.map((q, i) =>
                i === index ? { ...q, ...updates } : q
            )
        }));
    };

    const removeQuestion = (index) => {
        setFormData(prev => ({
            ...prev,
            questions: prev.questions.filter((_, i) => i !== index)
        }));
    };

    const updateOption = (questionIndex, optionIndex, value) => {
        setFormData(prev => ({
            ...prev,
            questions: prev.questions.map((q, i) => {
                if (i === questionIndex) {
                    const newOptions = [...q.options];
                    newOptions[optionIndex] = value;
                    return { ...q, options: newOptions };
                }
                return q;
            })
        }));
    };

    const handleFileUpload = (e) => {
        const file = e.target.files?.[0];
        if (!file) return;

        const reader = new FileReader();
        reader.onload = (event) => {
            const csvData = event.target.result;
            parseCSV(csvData);
            e.target.value = '';
        };
        reader.readAsText(file);
    };

    const parseCSV = (csvText) => {
        const lines = [];
        let currentLine = [];
        let currentCell = '';
        let inQuotes = false;
        
        for (let i = 0; i < csvText.length; i++) {
            const char = csvText[i];
            const nextChar = csvText[i + 1];
            
            if (char === '"') {
                if (inQuotes && nextChar === '"') {
                    currentCell += '"';
                    i++;
                } else {
                    inQuotes = !inQuotes;
                }
            } else if (char === ',' && !inQuotes) {
                currentLine.push(currentCell.trim());
                currentCell = '';
            } else if (char === '\n' && !inQuotes) {
                currentLine.push(currentCell.trim());
                lines.push(currentLine);
                currentLine = [];
                currentCell = '';
            } else if (char !== '\r') {
                currentCell += char;
            }
        }
        if (currentCell || currentLine.length > 0) {
            currentLine.push(currentCell.trim());
            lines.push(currentLine);
        }

        if (lines.length < 2) {
            alert('CSV is too short. Please provide at least metadata and one question.');
            return;
        }

        // Row 1: Metadata (Title, Description, Category, Difficulty, TimeLimit)
        const metadata = lines[0];
        const newFormData = { ...formData };
        
        if (metadata.length >= 2) {
            newFormData.title = metadata[0] || formData.title;
            newFormData.description = metadata[1] || formData.description;
            if (metadata[2]) newFormData.category = metadata[2];
            if (metadata[3]) newFormData.difficulty = metadata[3].toLowerCase();
            if (metadata[4]) newFormData.time_limit = parseInt(metadata[4]) || 10;
        }

        // Row 2 is usually headers, skip if it looks like one
        const startIndex = lines[1].some(cell => cell.toLowerCase().includes('type') || cell.toLowerCase().includes('question')) ? 2 : 1;
        const dataLines = lines.slice(startIndex);

        const newQuestions = [];
        dataLines.forEach((row, index) => {
            if (row.length < 2) return;
            
            const type = row[0].toLowerCase();
            const questionText = row[1];
            
            if (type.includes('mcq') || type.includes('multiple')) {
                const options = [row[2], row[3], row[4], row[5]];
                let correctIdx = parseInt(row[6]);
                
                // Human-friendly indexing: If user puts 1, it should be the 1st option (index 0)
                // If they put 0, we still keep it as 0.
                if (!isNaN(correctIdx) && correctIdx > 0 && correctIdx <= 4) {
                    correctIdx = correctIdx - 1;
                } else if (isNaN(correctIdx)) {
                    correctIdx = 0;
                }
                
                newQuestions.push({
                    id: `q-${Date.now()}-${index}`,
                    type: 'multiple',
                    question: questionText,
                    options: options,
                    correctAnswer: correctIdx
                });
            } else if (type.includes('bool') || type.includes('true')) {
                const answer = row[2].toLowerCase() === 'true';
                newQuestions.push({
                    id: `q-${Date.now()}-${index}`,
                    type: 'boolean',
                    question: questionText,
                    options: [],
                    correctAnswer: answer
                });
            } else if (type.includes('short')) {
                newQuestions.push({
                    id: `q-${Date.now()}-${index}`,
                    type: 'short',
                    question: questionText,
                    options: [],
                    correctAnswer: row[2]
                });
            }
        });

        if (newQuestions.length > 0) {
            setFormData({
                ...newFormData,
                questions: newQuestions
            });
            alert(`Successfully imported Quiz: "${newFormData.title}" with ${newQuestions.length} questions!`);
        } else {
            alert('Could not find valid questions. Ensure the Type (mcq/boolean/short) is in the first column.');
        }
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        setSaving(true);

        const quizData = {
            title: formData.title,
            description: formData.description,
            category: formData.category,
            difficulty: formData.difficulty,
            time_limit: formData.time_limit,
            passing_score: formData.passing_score,
            points: DIFFICULTY_LEVELS.find(d => d.value === formData.difficulty)?.points || 30,
            questions: formData.questions,
            assigned_to: formData.assignment_type === 'specific' ? formData.assigned_to : [],
            status: 'active',
            created_by: user?.id,
            classroom_id: formData.is_global ? null : (formData.classroom_id || user?.classroom_id),
            is_global: formData.is_global,
            assignment_type: formData.assignment_type
        };

        try {
            const saveAction = editingQuiz 
                ? db.updateQuiz(editingQuiz.id, quizData) 
                : db.createQuiz(quizData);
                
            const timeoutPromise = new Promise((_, reject) => 
                setTimeout(() => reject(new Error('Save timeout. The server took too long to respond.')), 10000)
            );

            const result = await Promise.race([saveAction, timeoutPromise]);

            // --- SEND NOTIFICATIONS TO ASSIGNED MEMBERS ---
            try {
                // Determine who to notify
                let targetMemberIds = [];
                if (quizData.assignment_type === 'everyone') {
                    targetMemberIds = members
                        .filter(m => quizData.is_global || m.classroom_id === quizData.classroom_id)
                        .filter(m => m.id !== user?.id) // Exclude admin who created the quiz
                        .map(m => m.id);
                } else {
                    targetMemberIds = (quizData.assigned_to || []).filter(id => id !== user?.id); // Exclude admin
                }

                // Send notifications to each assigned member (excluding the admin who assigned it)
                const notifyPromises = targetMemberIds.map(async (memberId) => {
                    // 1. Create in-app notification
                    await db.createNotification({
                        user_id: memberId,
                        classroom_id: quizData.classroom_id,
                        title: editingQuiz ? 'Quiz Updated 📝' : 'New Quiz Assigned 🧠',
                        message: `${quizData.title} has been ${editingQuiz ? 'updated' : 'assigned to you'}.`,
                        type: 'quiz',
                        link: `/quizzes`
                    });
                });

                await Promise.allSettled(notifyPromises);
            } catch (notifyError) {
                console.error('Failed to send notifications:', notifyError);
                // Don't block the main flow if notifications fail
            }
            // -------------------------------

            await loadData();
            setShowCreateModal(false);
            resetForm();
        } catch (error) {
            console.error('Error saving quiz:', error);
            alert(`Failed to save quiz: ${error.message}`);
        } finally {
            setSaving(false);
        }
    };

    const handleDelete = async (quizId) => {
        try {
            await db.deleteQuiz(quizId);
            await loadData();
            setDeleteConfirm(null);
        } catch (error) {
            console.error('Error deleting quiz:', error);
        }
    };

    const toggleAssignment = (userId) => {
        setFormData(prev => ({
            ...prev,
            assigned_to: prev.assigned_to.includes(userId)
                ? prev.assigned_to.filter(id => id !== userId)
                : [...prev.assigned_to, userId]
        }));
    };

    const filteredQuizzes = quizzes.filter(quiz =>
        quiz.title.toLowerCase().includes(searchQuery.toLowerCase())
    );

    if (loading) {
        return (
            <div className="flex items-center justify-center" style={{ minHeight: '400px' }}>
                <div className="loading-spinner" />
            </div>
        );
    }

    return (
        <div className="animate-fade-in">
            {/* Header */}
            <div className="flex flex-mobile-col justify-between items-center mb-lg">
                <p style={{ color: 'var(--text-muted)' }}>
                    Create and manage quizzes for your team
                </p>
                <Button icon={Plus} onClick={openCreateModal}>
                    Create Quiz
                </Button>
            </div>

            {/* Search */}
            <Card style={{ marginBottom: 'var(--space-lg)', padding: 'var(--space-md)' }}>
                <Input
                    placeholder="Search quizzes..."
                    icon={Search}
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                />
            </Card>

            {/* Quizzes Grid */}
            {filteredQuizzes.length === 0 ? (
                <Card>
                    <div className="empty-state">
                        <div className="empty-state-icon">
                            <HelpCircle size={32} />
                        </div>
                        <h3>No quizzes found</h3>
                        <p>Create your first quiz to test your team's knowledge.</p>
                        <Button icon={Plus} onClick={openCreateModal}>
                            Create Quiz
                        </Button>
                    </div>
                </Card>
            ) : (
                <div className="grid grid-cols-3 grid-3-mobile-1">
                    {filteredQuizzes.map(quiz => {
                        const assignedMembers = quiz.assigned_to?.map(id =>
                            members.find(m => m.id === id)
                        ).filter(Boolean) || [];

                        return (
                            <Card
                                key={quiz.id}
                                style={{
                                    display: 'flex',
                                    flexDirection: 'column',
                                    gap: 'var(--space-md)'
                                }}
                            >
                                <div className="flex justify-between items-start">
                                    <div>
                                        <Badge variant={getDifficultyColor(quiz.difficulty)}>
                                            {quiz.difficulty}
                                        </Badge>
                                        <Badge variant="primary" style={{ marginLeft: '8px' }}>
                                            {quiz.category}
                                        </Badge>
                                        {quiz.is_global && (
                                            <Badge variant="accent" style={{ marginLeft: '8px' }}>Global</Badge>
                                        )}
                                    </div>
                                    <div className="flex gap-sm" style={{ position: 'relative', zIndex: 10 }}>
                                        <Button
                                            variant="secondary"
                                            size="sm"
                                            onClick={(e) => {
                                                e.stopPropagation();
                                                openEditModal(quiz);
                                            }}
                                            style={{ padding: '8px' }}
                                        >
                                            <Edit2 size={16} color="var(--primary-400)" />
                                        </Button>
                                        <Button
                                            variant="secondary"
                                            size="sm"
                                            onClick={(e) => {
                                                e.stopPropagation();
                                                setDeleteConfirm(quiz);
                                            }}
                                            style={{ padding: '8px' }}
                                        >
                                            <Trash2 size={16} color="var(--error-400)" />
                                        </Button>
                                    </div>
                                </div>

                                <div>
                                    <h4 style={{ marginBottom: '4px' }}>{quiz.title}</h4>
                                    <p style={{
                                        fontSize: 'var(--text-sm)',
                                        color: 'var(--text-muted)',
                                        display: '-webkit-box',
                                        WebkitLineClamp: 2,
                                        WebkitBoxOrient: 'vertical',
                                        overflow: 'hidden'
                                    }}>
                                        {quiz.description}
                                    </p>
                                </div>

                                <div className="flex gap-lg" style={{ fontSize: 'var(--text-sm)' }}>
                                    <div className="flex items-center gap-xs" style={{ color: 'var(--text-muted)' }}>
                                        <HelpCircle size={16} />
                                        {quiz.questions?.length || 0} questions
                                    </div>
                                    <div className="flex items-center gap-xs" style={{ color: 'var(--text-muted)' }}>
                                        <Clock size={16} />
                                        {quiz.time_limit} min
                                    </div>
                                    <div className="flex items-center gap-xs" style={{ color: 'var(--text-muted)' }}>
                                        <Award size={16} />
                                        {quiz.points} pts
                                    </div>
                                </div>

                                <div className="flex items-center" style={{
                                    paddingTop: 'var(--space-md)',
                                    borderTop: '1px solid var(--border)'
                                }}>
                                    <Users size={16} style={{ color: 'var(--text-muted)', marginRight: '8px' }} />
                                    <div style={{ display: 'flex' }}>
                                        {quiz.assignment_type === 'everyone' ? (
                                            <Badge variant="secondary">Everyone</Badge>
                                        ) : (
                                            assignedMembers.slice(0, 3).map((member, i) => (
                                                <div
                                                    key={member.id}
                                                    style={{
                                                        marginLeft: i > 0 ? '-8px' : 0,
                                                        position: 'relative',
                                                        zIndex: 3 - i
                                                    }}
                                                >
                                                    <Avatar name={member.name} image={member.avatar_url} size="sm" />
                                                </div>
                                            ))
                                        )}
                                    </div>
                                    {quiz.assignment_type === 'specific' && (
                                        <span style={{
                                            fontSize: 'var(--text-xs)',
                                            color: 'var(--text-muted)',
                                            marginLeft: '8px'
                                        }}>
                                            {assignedMembers.length} assigned
                                        </span>
                                    )}
                                </div>
                            </Card>
                        );
                    })}
                </div>
            )}

            {/* Create/Edit Modal */}
            <Modal
                isOpen={showCreateModal}
                onClose={() => setShowCreateModal(false)}
                title={editingQuiz ? 'Edit Quiz' : 'Create New Quiz'}
                size="xl"
            >
                <form onSubmit={handleSubmit}>
                    <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-md)' }}>
                        <Input
                            label="Quiz Title"
                            placeholder="e.g., HTML Fundamentals"
                            value={formData.title}
                            onChange={(e) => setFormData({ ...formData, title: e.target.value })}
                            required
                        />

                        <Input
                            type="textarea"
                            label="Description"
                            placeholder="Describe what this quiz covers..."
                            value={formData.description}
                            onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                            required
                        />

                        <div className="grid grid-4-mobile-1" style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr 1fr', gap: 'var(--space-md)' }}>
                            <div className="input-group">
                                <label className="input-label">Category</label>
                                <select
                                    className="input select"
                                    value={formData.category}
                                    onChange={(e) => setFormData({ ...formData, category: e.target.value })}
                                >
                                    {TASK_CATEGORIES.map(cat => (
                                        <option key={cat} value={cat}>{cat}</option>
                                    ))}
                                </select>
                            </div>

                            <div className="input-group">
                                <label className="input-label">Difficulty</label>
                                <select
                                    className="input select"
                                    value={formData.difficulty}
                                    onChange={(e) => setFormData({ ...formData, difficulty: e.target.value })}
                                >
                                    {DIFFICULTY_LEVELS.map(level => (
                                        <option key={level.value} value={level.value}>
                                            {level.label}
                                        </option>
                                    ))}
                                </select>
                            </div>

                            <Input
                                type="number"
                                label="Time Limit (min)"
                                min="1"
                                max="120"
                                value={formData.time_limit}
                                onChange={(e) => setFormData({ ...formData, time_limit: parseInt(e.target.value) })}
                            />
                            <Input
                                type="number"
                                label="Pass Grade (%)"
                                min="0"
                                max="100"
                                value={formData.passing_score}
                                onChange={(e) => setFormData({ ...formData, passing_score: parseInt(e.target.value) })}
                            />
                        </div>

                        {/* Assignment Mode */}
                        <div className="input-group">
                            <label className="input-label">Target Audience</label>
                            <div className="flex flex-mobile-col gap-md">
                                <button
                                    type="button"
                                    onClick={() => setFormData({ ...formData, is_global: false })}
                                    className={`btn ${!formData.is_global ? 'btn-primary' : 'btn-secondary'} flex-1`}
                                >
                                    Current Classroom
                                </button>
                                <button
                                    type="button"
                                    onClick={() => setFormData({ ...formData, is_global: true })}
                                    className={`btn ${formData.is_global ? 'btn-primary' : 'btn-secondary'} flex-1`}
                                >
                                    All Classrooms (Global)
                                </button>
                            </div>
                        </div>
                        
                        {!formData.is_global && (
                            <div className="input-group">
                                <label className="input-label">Select Target Classroom</label>
                                <select
                                    className="input select"
                                    value={formData.classroom_id}
                                    onChange={(e) => setFormData({ ...formData, classroom_id: e.target.value })}
                                    required={!formData.is_global}
                                >
                                    <option value="">-- Choose a Classroom --</option>
                                    {classrooms.map(cls => (
                                        <option key={cls.id} value={cls.id}>{cls.name}</option>
                                    ))}
                                </select>
                            </div>
                        )}

                        <div className="input-group">
                            <label className="input-label">Assignment Type</label>
                            <div className="flex flex-mobile-col gap-md">
                                <button
                                    type="button"
                                    onClick={() => setFormData({ ...formData, assignment_type: 'everyone' })}
                                    className={`btn ${formData.assignment_type === 'everyone' ? 'btn-primary' : 'btn-secondary'} flex-1`}
                                >
                                    Assign to Everyone
                                </button>
                                <button
                                    type="button"
                                    onClick={() => setFormData({ ...formData, assignment_type: 'specific' })}
                                    className={`btn ${formData.assignment_type === 'specific' ? 'btn-primary' : 'btn-secondary'} flex-1`}
                                >
                                    Specific Members
                                </button>
                            </div>
                        </div>

                        {/* Assign Members - only show if specific */}
                        {formData.assignment_type === 'specific' && (
                            <div className="input-group">
                                <label className="input-label">Select Members</label>
                                <div style={{
                                    display: 'flex',
                                    flexWrap: 'wrap',
                                    gap: 'var(--space-sm)'
                                }}>
                                    {members.map(member => (
                                        <div
                                            key={member.id}
                                            onClick={() => toggleAssignment(member.id)}
                                            style={{
                                                display: 'flex',
                                                alignItems: 'center',
                                                gap: 'var(--space-sm)',
                                                padding: 'var(--space-xs) var(--space-md)',
                                                background: formData.assigned_to.includes(member.id)
                                                    ? 'rgba(99, 102, 241, 0.1)'
                                                    : 'var(--card)',
                                                border: `2px solid ${formData.assigned_to.includes(member.id) ? 'var(--primary-500)' : 'var(--border)'}`,
                                                borderRadius: 'var(--radius-full)',
                                                cursor: 'pointer',
                                                transition: 'all var(--transition-fast)'
                                            }}
                                        >
                                            <Avatar name={member.name} image={member.avatar_url} size="sm" />
                                            <span style={{ fontSize: 'var(--text-sm)' }}>{member.name}</span>
                                        </div>
                                    ))}
                                </div>
                                {members.length === 0 && (
                                    <p className="text-xs text-muted italic">No members found in this classroom.</p>
                                )}
                            </div>
                        )}

                        {/* Questions */}
                        <div className="input-group">
                            <div className="flex justify-between items-center mb-xs">
                                <label className="input-label" style={{ margin: 0 }}>Questions</label>
                                <div className="flex gap-sm">
                                    <input 
                                        type="file" 
                                        accept=".csv" 
                                        id="csv-upload" 
                                        style={{ display: 'none' }} 
                                        onChange={handleFileUpload} 
                                    />
                                    <Button type="button" variant="ghost" size="sm" icon={Upload} onClick={() => document.getElementById('csv-upload').click()}>
                                        Import CSV
                                    </Button>
                                    <Button type="button" variant="secondary" size="sm" icon={Plus} onClick={addQuestion}>
                                        Add Question
                                    </Button>
                                </div>
                                <Button type="button" variant="ghost" size="sm" icon={HelpCircle} onClick={() => setShowCSVGuide(!showCSVGuide)}>
                                    {showCSVGuide ? 'Hide Format Guide' : 'Show Format Guide'}
                                </Button>
                            </div>
                            
                            {showCSVGuide && (
                                <div className="text-xs text-muted mb-md p-md bg-surface border border-border rounded-lg animate-fade-in" style={{ opacity: 0.9 }}>
                                    <h4 className="text-xs font-black uppercase tracking-widest mb-sm" style={{ color: 'var(--primary-500)' }}>CSV Import Format Guide</h4>
                                    <p className="mb-sm">To import a quiz, upload a CSV with the following structure:</p>
                                    <ul style={{ listStyle: 'none', padding: 0, display: 'flex', flexDirection: 'column', gap: '4px' }}>
                                        <li>• <strong>Row 1:</strong> Title, Description, Category, Difficulty, TimeLimit</li>
                                        <li>• <strong>Row 2:</strong> Headers (Type, Question, Opt1, Opt2, Opt3, Opt4, Correct)</li>
                                        <li>• <strong>MCQ:</strong> mcq, Question, Opt 1, Opt 2, Opt 3, Opt 4, Correct Index (0-3)</li>
                                        <li>• <strong>Boolean:</strong> boolean, Question, True/False</li>
                                        <li>• <strong>Short Answer:</strong> short, Question, Expected Answer</li>
                                    </ul>
                                    <div className="mt-sm p-xs bg-card rounded border border-border/50 font-mono" style={{ fontSize: '10px' }}>
                                        "HTML Basics","Intro to HTML","Frontend","easy",15<br/>
                                        "mcq","What is HTML?","Language","Bird","Car","Plane",0
                                    </div>
                                </div>
                            )}

                            {formData.questions.length === 0 ? (
                                <div style={{
                                    padding: 'var(--space-xl)',
                                    background: 'var(--card)',
                                    borderRadius: 'var(--radius-lg)',
                                    textAlign: 'center',
                                    color: 'var(--text-muted)'
                                }}>
                                    <HelpCircle size={32} style={{ marginBottom: 'var(--space-sm)', opacity: 0.5 }} />
                                    <p style={{ margin: 0 }}>No questions yet. Click "Add Question" to get started.</p>
                                </div>
                            ) : (
                                <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-md)' }}>
                                    {formData.questions.map((question, qIndex) => (
                                        <Card key={question.id} style={{ background: 'var(--surface)' }}>
                                            <div className="flex justify-between items-start mb-md">
                                                <div className="flex items-center gap-sm">
                                                    <GripVertical size={16} style={{ color: 'var(--text-muted)' }} />
                                                    <Badge variant="primary">Q{qIndex + 1}</Badge>
                                                </div>
                                                <div className="flex items-center gap-sm">
                                                    <select
                                                        className="input select"
                                                        style={{ width: 'auto', padding: '0.5rem' }}
                                                        value={question.type}
                                                        onChange={(e) => updateQuestion(qIndex, {
                                                            type: e.target.value,
                                                            correctAnswer: e.target.value === 'boolean' ? true : 0,
                                                            options: e.target.value === 'boolean' ? [] : ['', '', '', '']
                                                        })}
                                                    >
                                                        {QUESTION_TYPES.map(type => (
                                                            <option key={type.value} value={type.value}>{type.label}</option>
                                                        ))}
                                                    </select>
                                                    <Button
                                                        type="button"
                                                        variant="ghost"
                                                        size="icon"
                                                        onClick={() => removeQuestion(qIndex)}
                                                    >
                                                        <X size={16} />
                                                    </Button>
                                                </div>
                                            </div>

                                            <Input
                                                placeholder="Enter your question..."
                                                value={question.question}
                                                onChange={(e) => updateQuestion(qIndex, { question: e.target.value })}
                                                wrapperClassName="mb-md"
                                            />

                                            {question.type === 'multiple' && (
                                                <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-sm)' }}>
                                                    {question.options.map((option, oIndex) => (
                                                        <div
                                                            key={oIndex}
                                                            className="flex items-center gap-sm"
                                                            onClick={() => updateQuestion(qIndex, { correctAnswer: oIndex })}
                                                            style={{ cursor: 'pointer' }}
                                                        >
                                                            <div style={{
                                                                width: '20px',
                                                                height: '20px',
                                                                borderRadius: '50%',
                                                                border: `2px solid ${question.correctAnswer === oIndex ? 'var(--success-500)' : 'var(--border)'}`,
                                                                background: question.correctAnswer === oIndex ? 'var(--success-500)' : 'transparent',
                                                                display: 'flex',
                                                                alignItems: 'center',
                                                                justifyContent: 'center',
                                                                flexShrink: 0
                                                            }}>
                                                                {question.correctAnswer === oIndex && (
                                                                    <svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="white" strokeWidth="3">
                                                                        <polyline points="20 6 9 17 4 12" />
                                                                    </svg>
                                                                )}
                                                            </div>
                                                            <Input
                                                                placeholder={`Option ${oIndex + 1}`}
                                                                value={option}
                                                                onChange={(e) => {
                                                                    e.stopPropagation();
                                                                    updateOption(qIndex, oIndex, e.target.value);
                                                                }}
                                                                onClick={(e) => e.stopPropagation()}
                                                                style={{ flex: 1 }}
                                                            />
                                                        </div>
                                                    ))}
                                                    <p style={{ fontSize: 'var(--text-xs)', color: 'var(--text-muted)', marginTop: '4px' }}>
                                                        Click the circle to mark the correct answer
                                                    </p>
                                                </div>
                                            )}

                                            {question.type === 'boolean' && (
                                                <div className="flex gap-md">
                                                    {[{ label: 'True', value: true }, { label: 'False', value: false }].map(opt => (
                                                        <div
                                                            key={opt.label}
                                                            onClick={() => updateQuestion(qIndex, { correctAnswer: opt.value })}
                                                            style={{
                                                                flex: 1,
                                                                padding: 'var(--space-md)',
                                                                background: question.correctAnswer === opt.value
                                                                    ? 'rgba(16, 185, 129, 0.1)'
                                                                    : 'var(--card)',
                                                                border: `2px solid ${question.correctAnswer === opt.value ? 'var(--success-500)' : 'var(--border)'}`,
                                                                borderRadius: 'var(--radius-md)',
                                                                textAlign: 'center',
                                                                cursor: 'pointer'
                                                            }}
                                                        >
                                                            {opt.label}
                                                        </div>
                                                    ))}
                                                </div>
                                            )}

                                            {question.type === 'short' && (
                                                <Input
                                                    placeholder="Expected answer (for grading reference)"
                                                    value={question.correctAnswer || ''}
                                                    onChange={(e) => updateQuestion(qIndex, { correctAnswer: e.target.value })}
                                                />
                                            )}
                                        </Card>
                                    ))}
                                </div>
                            )}
                        </div>
                    </div>

                    <div className="flex justify-end gap-md" style={{ marginTop: 'var(--space-lg)' }}>
                        <Button type="button" variant="secondary" onClick={() => setShowCreateModal(false)}>
                            Cancel
                        </Button>
                        <Button type="submit" disabled={formData.questions.length === 0} loading={saving}>
                            {editingQuiz ? 'Save Changes' : 'Create Quiz'}
                        </Button>
                    </div>
                </form>
            </Modal>

            {/* Delete Confirmation */}
            <Modal
                isOpen={!!deleteConfirm}
                onClose={() => setDeleteConfirm(null)}
                title="Delete Quiz"
                size="sm"
            >
                <p style={{ marginBottom: 'var(--space-lg)' }}>
                    Are you sure you want to delete "<strong>{deleteConfirm?.title}</strong>"?
                </p>
                <div className="flex justify-end gap-md">
                    <Button variant="secondary" onClick={() => setDeleteConfirm(null)}>
                        Cancel
                    </Button>
                    <Button variant="danger" onClick={() => handleDelete(deleteConfirm.id)}>
                        Delete Quiz
                    </Button>
                </div>
            </Modal>


        </div>
    );
};

export default QuizBuilder;

import { useState, useEffect } from 'react';
import { Link, useLocation, useParams, useNavigate } from 'react-router-dom';
import { Card, Button, Badge, Modal, Input, Avatar } from '../../components/common';
import {
    Plus,
    Search,
    Filter,
    Edit2,
    Trash2,
    Users,
    Calendar,
    Award,
    MoreVertical,
    Eye,
    Key,
    Clock
} from 'lucide-react';
import * as db from '../../services/database';
import { supabase } from '../../lib/supabase';
import { useAuth } from '../../context/AuthContext';
import {
    formatDate,
    TASK_CATEGORIES,
    DIFFICULTY_LEVELS,
    EVALUATION_CRITERIA,
    getDifficultyColor
} from '../../utils/constants';

const TaskManager = () => {
    const { user } = useAuth();
    const location = useLocation();
    const { taskId } = useParams(); // If configured in routes as /tasks/:taskId
    const navigate = useNavigate();

    const [tasks, setTasks] = useState([]);
    const [members, setMembers] = useState([]);
    const [submissions, setSubmissions] = useState([]);
    const [searchQuery, setSearchQuery] = useState('');
    const [filterCategory, setFilterCategory] = useState('all');
    const [showCreateModal, setShowCreateModal] = useState(false);
    const [editingTask, setEditingTask] = useState(null);
    const [deleteConfirm, setDeleteConfirm] = useState(null);
    const [loading, setLoading] = useState(true);
    const [saving, setSaving] = useState(false);

    // Form state
    const [formData, setFormData] = useState({
        title: '',
        description: '',
        categories: ['Frontend'],
        difficulty: 'medium',
        points: 100,
        start_date: '',
        deadline: '',
        assigned_to: [],
        criteria: [],
        deliverable_types: ['repo_url'],
        is_global: false,
        assignment_type: 'everyone'
    });

    const [currentUserProfile, setCurrentUserProfile] = useState(null);

    useEffect(() => {
        loadData();
    }, []);

    // Effect to handle URL-based modal opening
    useEffect(() => {
        if (!loading && tasks.length > 0) {
            if (location.pathname.endsWith('/new')) {
                openCreateModal();
            } else if (taskId) {
                const taskToEdit = tasks.find(t => t.id == taskId);
                if (taskToEdit) {
                    openEditModal(taskToEdit);
                }
            }
        } else if (!loading && location.pathname.endsWith('/new')) {
            // Even if no tasks exist, we should allow creating new one
            openCreateModal();
        }
    }, [location.pathname, taskId, loading, tasks]);

    const loadData = async () => {
        setLoading(true);
        try {
            // Fetch everything independently to avoid one failure blocking all
            const [tasksResult, membersResult, submissionsResult] = await Promise.allSettled([
                db.getTasks(),
                db.getMembers(),
                db.getSubmissions()
            ]);

            // Get current user profile for filtering
            const { data: { user } } = await supabase.auth.getUser();
            if (user) {
                const { data: profile } = await supabase.from('profiles').select('*').eq('id', user.id).single();
                setCurrentUserProfile(profile);
            }

            if (tasksResult.status === 'fulfilled') {
                setTasks(tasksResult.value);
            } else {
                console.error('Failed to load tasks:', tasksResult.reason);
                alert('Error loading tasks: ' + (tasksResult.reason?.message || 'Unknown error'));
            }

            if (membersResult.status === 'fulfilled') {
                setMembers(membersResult.value);
            } else {
                console.error('Failed to load members:', membersResult.reason);
            }

            if (submissionsResult.status === 'fulfilled') {
                setSubmissions(submissionsResult.value);
            } else {
                console.error('Failed to load submissions:', submissionsResult.reason);
            }
        } catch (error) {
            console.error('Error loading data:', error);
        } finally {
            setLoading(false);
        }
    };

    const resetForm = () => {
        setFormData({
            title: '',
            description: '',
            categories: ['Frontend'],
            difficulty: 'medium',
            points: 100,
            start_date: '',
            deadline: '',
            assigned_to: [],
            criteria: [],
            deliverable_types: ['repo_url'],
            is_global: false,
            assignment_type: 'everyone'
        });
    };

    const openCreateModal = () => {
        resetForm();
        setEditingTask(null);
        setShowCreateModal(true);
    };

    const openEditModal = (task) => {
        setFormData({
            title: task.title,
            description: task.description || '',
            categories: task.categories && task.categories.length > 0
                ? task.categories
                : (Array.isArray(task.category) ? task.category : [task.category || 'Frontend']),
            difficulty: task.difficulty,
            points: task.points,
            start_date: task.start_date?.split('T')[0] || '',
            deadline: task.deadline ? new Date(task.deadline).toISOString().slice(0, 16) : '',
            assigned_to: task.assigned_to || [],
            criteria: task.criteria || [],
            deliverable_types: task.deliverable_types || ['repo_url'],
            is_global: task.is_global || false,
            assignment_type: task.assignment_type || (task.assigned_to?.length > 0 ? 'specific' : 'everyone')
        });
        setEditingTask(task);
        setShowCreateModal(true);
    };

    const closeModal = () => {
        setShowCreateModal(false);
        setEditingTask(null);
        resetForm();
        navigate('/admin/tasks');
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        setSaving(true);

        const taskData = {
            title: formData.title,
            description: formData.description,
            categories: formData.categories,
            category: formData.categories[0] || 'General',
            difficulty: formData.difficulty,
            points: DIFFICULTY_LEVELS.find(d => d.value === formData.difficulty)?.points || 100,
            start_date: formData.start_date ? new Date(formData.start_date).toISOString() : new Date().toISOString(),
            deadline: formData.deadline ? new Date(formData.deadline).toISOString() : null,
            assigned_to: formData.assignment_type === 'specific' ? formData.assigned_to : [],
            criteria: formData.criteria,
            deliverable_types: formData.deliverable_types,
            status: 'active',
            created_by: user?.id,
            classroom_id: formData.is_global ? null : user?.classroom_id,
            is_global: formData.is_global,
            assignment_type: formData.assignment_type
        };

        try {
            let result;
            if (editingTask) {
                result = await db.updateTask(editingTask.id, taskData);
            } else {
                result = await db.createTask(taskData);
            }

            // --- ONE SIGNAL NOTIFICATION + IN-APP NOTIFICATION ---
            try {
                // Determine who to notify
                let targetMemberIds = [];
                if (taskData.assignment_type === 'everyone') {
                    targetMemberIds = members
                        .filter(m => taskData.is_global || m.classroom_id === taskData.classroom_id)
                        .filter(m => m.id !== user?.id) // Exclude admin who created the task
                        .map(m => m.id);
                } else {
                    targetMemberIds = (taskData.assigned_to || []).filter(id => id !== user?.id); // Exclude admin
                }

                // Send notifications to each assigned member (excluding the admin who assigned it)
                const notifyPromises = targetMemberIds.map(async (memberId) => {
                    // 1. Create in-app notification
                    await db.createNotification({
                        user_id: memberId,
                        classroom_id: taskData.classroom_id,
                        title: editingTask ? 'Task Updated 📝' : 'New Task Assigned 🚀',
                        message: `${taskData.title} has been ${editingTask ? 'updated' : 'assigned to you'}.`,
                        type: 'task',
                        link: `/tasks/${editingTask ? editingTask.id : (result?.[0]?.id || '')}`
                    });
                });

                await Promise.allSettled(notifyPromises);
            } catch (notifyError) {
                console.error('Failed to send notifications:', notifyError);
                // Don't block the main flow if notifications fail
            }
            // -------------------------------
            await loadData();
            closeModal();
        } catch (error) {
            console.error('Error saving task:', error);
            alert('Failed to save task: ' + error.message);
        } finally {
            setSaving(false);
        }
    };

    const handleDelete = async (taskId) => {
        try {
            await db.deleteTask(taskId);
            await loadData();
            setDeleteConfirm(null);
        } catch (error) {
            console.error('Error deleting task:', error);
            alert(`Failed to delete task: ${error.message}`);
        }
    };

    const handlePostpone = async (e, task) => {
        e.stopPropagation();
        const days = prompt('How many days do you want to start extending the deadline by?', '3');
        if (!days || isNaN(days)) return;

        setSaving(true); // Re-using saving state for loading indication
        try {
            const currentDeadline = task.deadline ? new Date(task.deadline) : new Date();
            const newDeadline = new Date(currentDeadline);
            newDeadline.setDate(newDeadline.getDate() + parseInt(days));

            const taskData = {
                deadline: newDeadline.toISOString()
            };

            await db.updateTask(task.id, taskData);
            await loadData();
            alert(`Task deadline extended by ${days} days.`);
        } catch (error) {
            console.error('Error postponing task:', error);
            alert('Failed to postpone task: ' + error.message);
        } finally {
            setSaving(false);
        }
    };

    const toggleCategory = (category) => {
        setFormData(prev => ({
            ...prev,
            categories: prev.categories.includes(category)
                ? prev.categories.filter(c => c !== category)
                : [...prev.categories, category]
        }));
    };

    const toggleDeliverableType = (type) => {
        setFormData(prev => ({
            ...prev,
            deliverable_types: prev.deliverable_types.includes(type)
                ? prev.deliverable_types.filter(t => t !== type)
                : [...prev.deliverable_types, type]
        }));
    };

    const toggleAssignment = (userId) => {
        setFormData(prev => ({
            ...prev,
            assigned_to: prev.assigned_to.includes(userId)
                ? prev.assigned_to.filter(id => id !== userId)
                : [...prev.assigned_to, userId]
        }));
    };

    const toggleCriteria = (criteriaId) => {
        setFormData(prev => ({
            ...prev,
            criteria: prev.criteria.includes(criteriaId)
                ? prev.criteria.filter(id => id !== criteriaId)
                : [...prev.criteria, criteriaId]
        }));
    };

    const filteredTasks = tasks.filter(task => {
        const matchesSearch = task.title.toLowerCase().includes(searchQuery.toLowerCase());
        const matchesCategory = filterCategory === 'all' ||
            (task.categories ? task.categories.includes(filterCategory) : task.category === filterCategory);
        return matchesSearch && matchesCategory;
    });

    if (loading) {
        return (
            <div className="flex items-center justify-center" style={{ minHeight: '400px' }}>
                <div className="loading-spinner" />
            </div>
        );
    }

    return (
        <div className="animate-fade-in">
            {/* Header */}
            <div className="flex flex-mobile-col justify-between items-center mb-lg">
                <div>
                    <p style={{ color: 'var(--text-muted)', marginBottom: '4px' }}>
                        Manage and assign tasks to your team
                    </p>
                </div>
                <Button icon={Plus} onClick={() => navigate('/admin/tasks/new')}>
                    Create Task
                </Button>
            </div>

            {/* Filters */}
            <Card style={{ marginBottom: 'var(--space-lg)', padding: 'var(--space-md)' }}>
                <div className="flex flex-mobile-col gap-md items-center" style={{ flexWrap: 'wrap' }}>
                    <div style={{ flex: '1', minWidth: '200px' }}>
                        <Input
                            placeholder="Search tasks..."
                            icon={Search}
                            value={searchQuery}
                            onChange={(e) => setSearchQuery(e.target.value)}
                        />
                    </div>
                    <div style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-sm)' }}>
                        <Filter size={18} style={{ color: 'var(--text-muted)' }} />
                        <select
                            className="input select"
                            value={filterCategory}
                            onChange={(e) => setFilterCategory(e.target.value)}
                            style={{ width: 'auto' }}
                        >
                            <option value="all">All Categories</option>
                            {TASK_CATEGORIES.map(cat => (
                                <option key={cat} value={cat}>{cat}</option>
                            ))}
                        </select>
                    </div>
                </div>
            </Card>

            {/* Tasks Grid */}
            {filteredTasks.length === 0 ? (
                <Card>
                    <div className="empty-state">
                        <div className="empty-state-icon">
                            <Plus size={32} />
                        </div>
                        <h3>No tasks found</h3>
                        <p>Create your first task to start assigning work to your team.</p>
                        <Button icon={Plus} onClick={() => navigate('/admin/tasks/new')}>
                            Create Task
                        </Button>
                    </div>
                </Card>
            ) : (
                <div className="grid grid-cols-3 grid-3-mobile-1">
                    {filteredTasks.map(task => {
                        const assignedMembers = task.assigned_to?.map(id =>
                            members.find(m => m.id === id)
                        ).filter(Boolean) || [];
                        const taskSubmissions = submissions.filter(s => s.task_id === task.id);
                        const pendingCount = taskSubmissions.filter(s => s.status === 'pending').length;

                        return (
                            <Card
                                key={task.id}
                                onClick={() => navigate(`/admin/tasks/${task.id}`)}
                                style={{
                                    display: 'flex',
                                    flexDirection: 'column',
                                    gap: 'var(--space-md)',
                                    cursor: 'pointer',
                                    transition: 'transform 0.2s, box-shadow 0.2s'
                                }}
                                className="task-card-hover"
                            >
                                {/* Header */}
                                <div className="flex justify-between items-start">
                                    <div>
                                        <Badge variant={getDifficultyColor(task.difficulty)}>
                                            {task.difficulty}
                                        </Badge>
                                        {(task.categories || (Array.isArray(task.category) ? task.category : [task.category])).map((cat, index) => (
                                            <Badge key={`${cat}-${index}`} variant="primary" style={{ marginLeft: '4px' }}>
                                                {cat}
                                            </Badge>
                                        ))}
                                        {task.is_global && (
                                            <Badge variant="accent" style={{ marginLeft: '4px' }}>Global</Badge>
                                        )}
                                    </div>
                                    <div className="flex gap-xs" onClick={(e) => e.stopPropagation()}>
                                        <Button
                                            variant="ghost"
                                            size="icon"
                                            title="Postpone Deadline"
                                            onClick={(e) => handlePostpone(e, task)}
                                        >
                                            <Clock size={16} />
                                        </Button>
                                        <Button
                                            variant="ghost"
                                            size="icon"
                                            onClick={() => navigate(`/admin/tasks/${task.id}`)}
                                        >
                                            <Edit2 size={16} />
                                        </Button>
                                        <Button
                                            variant="ghost"
                                            size="icon"
                                            onClick={() => setDeleteConfirm(task)}
                                        >
                                            <Trash2 size={16} />
                                        </Button>
                                    </div>
                                </div>

                                {/* Title & Description */}
                                <div>
                                    <h4 style={{ marginBottom: '4px' }}>{task.title}</h4>
                                    <p style={{
                                        fontSize: 'var(--text-sm)',
                                        color: 'var(--text-muted)',
                                        display: '-webkit-box',
                                        WebkitLineClamp: 2,
                                        WebkitBoxOrient: 'vertical',
                                        overflow: 'hidden'
                                    }}>
                                        {task.description}
                                    </p>
                                </div>

                                {/* Stats */}
                                <div className="flex gap-lg" style={{ fontSize: 'var(--text-sm)' }}>
                                    <div className="flex items-center gap-xs" style={{ color: 'var(--text-muted)' }}>
                                        <Award size={16} />
                                        {task.points} pts
                                    </div>
                                    {task.deadline && (
                                        <div className="flex items-center gap-xs" style={{ color: 'var(--text-muted)' }}>
                                            <Calendar size={16} />
                                            Due: {formatDate(task.deadline)}
                                        </div>
                                    )}
                                </div>

                                {/* Assigned Members */}
                                <div
                                    className="flex justify-between items-center"
                                    style={{
                                        paddingTop: 'var(--space-md)',
                                        borderTop: '1px solid var(--border)'
                                    }}
                                >
                                    <div className="flex items-center">
                                        <div style={{ display: 'flex', marginRight: 'var(--space-sm)' }}>
                                            {task.assignment_type === 'everyone' ? (
                                                <Badge variant="secondary">Everyone</Badge>
                                            ) : (
                                                assignedMembers.slice(0, 3).map((member, i) => (
                                                    <div
                                                        key={member.id}
                                                        style={{
                                                            marginLeft: i > 0 ? '-8px' : 0,
                                                            position: 'relative',
                                                            zIndex: 3 - i
                                                        }}
                                                    >
                                                        <Avatar name={member.name} image={member.avatar_url} size="sm" />
                                                    </div>
                                                ))
                                            )}
                                        </div>
                                        {task.assignment_type === 'specific' && assignedMembers.length > 3 && (
                                            <span style={{ fontSize: 'var(--text-xs)', color: 'var(--text-muted)' }}>
                                                +{assignedMembers.length - 3} more
                                            </span>
                                        )}
                                        {task.assignment_type === 'specific' && assignedMembers.length === 0 && (
                                            <span style={{ fontSize: 'var(--text-xs)', color: 'var(--text-muted)' }}>
                                                Not assigned
                                            </span>
                                        )}
                                    </div>
                                    {pendingCount > 0 && (
                                        <Badge variant="warning">
                                            {pendingCount} pending
                                        </Badge>
                                    )}
                                </div>
                            </Card>
                        );
                    })}
                </div>
            )}

            {/* Create/Edit Modal */}
            <Modal
                isOpen={showCreateModal}
                onClose={closeModal}
                title={editingTask ? 'Edit Task' : 'Create New Task'}
                size="lg"
            >
                <form onSubmit={handleSubmit}>
                    <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-md)' }}>
                        <Input
                            label="Task Title"
                            placeholder="e.g., Create a Responsive Login Page"
                            value={formData.title}
                            onChange={(e) => setFormData({ ...formData, title: e.target.value })}
                            required
                        />

                        <Input
                            type="textarea"
                            label="Description"
                            placeholder="Describe the task requirements, expectations, and any resources..."
                            value={formData.description}
                            onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                            required
                        />

                        <div className="dashboard-grid" style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 'var(--space-md)' }}>
                            <div className="input-group">
                                <label className="input-label">Difficulty</label>
                                <select
                                    className="input select"
                                    value={formData.difficulty}
                                    onChange={(e) => setFormData({ ...formData, difficulty: e.target.value })}
                                >
                                    {DIFFICULTY_LEVELS.map(level => (
                                        <option key={level.value} value={level.value}>
                                            {level.label} ({level.points} pts)
                                        </option>
                                    ))}
                                </select>
                            </div>
                        </div>

                        {/* Categories */}
                        <div className="input-group">
                            <label className="input-label">Categories (select all that apply)</label>
                            <div style={{
                                display: 'grid',
                                gridTemplateColumns: 'repeat(auto-fill, minmax(120px, 1fr))',
                                gap: 'var(--space-sm)'
                            }}>
                                {TASK_CATEGORIES.map(category => (
                                    <div
                                        key={category}
                                        onClick={() => toggleCategory(category)}
                                        style={{
                                            display: 'flex',
                                            alignItems: 'center',
                                            gap: 'var(--space-sm)',
                                            padding: 'var(--space-sm)',
                                            background: formData.categories.includes(category)
                                                ? 'rgba(99, 102, 241, 0.1)'
                                                : 'var(--card)',
                                            border: `2px solid ${formData.categories.includes(category) ? 'var(--primary-500)' : 'var(--border)'}`,
                                            borderRadius: 'var(--radius-md)',
                                            cursor: 'pointer',
                                            transition: 'all var(--transition-fast)'
                                        }}
                                    >
                                        <div className={`checkbox ${formData.categories.includes(category) ? 'checked' : ''}`}>
                                            {formData.categories.includes(category) && (
                                                <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3">
                                                    <polyline points="20 6 9 17 4 12" />
                                                </svg>
                                            )}
                                        </div>
                                        <span style={{ fontSize: 'var(--text-sm)' }}>{category}</span>
                                    </div>
                                ))}
                            </div>
                        </div>

                        {/* Date Fields */}
                        <div className="dashboard-grid" style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 'var(--space-md)' }}>
                            <Input
                                type="date"
                                label="Start Date"
                                value={formData.start_date}
                                onChange={(e) => setFormData({ ...formData, start_date: e.target.value })}
                            />
                            <Input
                                type="datetime-local"
                                label="Deadline"
                                value={formData.deadline}
                                onChange={(e) => setFormData({ ...formData, deadline: e.target.value })}
                            />
                        </div>

                        {/* Assignment Mode */}
                        <div className="input-group">
                            <label className="input-label">Target Audience</label>
                            <div className="flex gap-md">
                                <button
                                    type="button"
                                    onClick={() => setFormData({ ...formData, is_global: false })}
                                    className={`btn ${!formData.is_global ? 'btn-primary' : 'btn-secondary'} flex-1`}
                                >
                                    Current Classroom
                                </button>
                                <button
                                    type="button"
                                    onClick={() => setFormData({ ...formData, is_global: true })}
                                    className={`btn ${formData.is_global ? 'btn-primary' : 'btn-secondary'} flex-1`}
                                >
                                    All Classrooms (Global)
                                </button>
                            </div>
                        </div>

                        <div className="input-group">
                            <label className="input-label">Assignment Type</label>
                            <div className="flex gap-md">
                                <button
                                    type="button"
                                    onClick={() => setFormData({ ...formData, assignment_type: 'everyone' })}
                                    className={`btn ${formData.assignment_type === 'everyone' ? 'btn-primary' : 'btn-secondary'} flex-1`}
                                >
                                    Assign to Everyone
                                </button>
                                <button
                                    type="button"
                                    onClick={() => setFormData({ ...formData, assignment_type: 'specific' })}
                                    className={`btn ${formData.assignment_type === 'specific' ? 'btn-primary' : 'btn-secondary'} flex-1`}
                                >
                                    Specific Members
                                </button>
                            </div>
                        </div>

                        {/* Assign Members - only show if specific */}
                        {formData.assignment_type === 'specific' && (
                            <div className="input-group">
                                <label className="input-label">Select Members</label>
                                <div style={{
                                    display: 'grid',
                                    gridTemplateColumns: 'repeat(auto-fill, minmax(150px, 1fr))',
                                    gap: 'var(--space-sm)'
                                }}>
                                    {members
                                        .filter(member => {
                                            // If global assignment, show everyone
                                            if (formData.is_global) return true;
                                            // If local assignment, only show members of current user's classroom
                                            return member.classroom_id === currentUserProfile?.classroom_id;
                                        })
                                        .map(member => (
                                            <div
                                                key={member.id}
                                                onClick={() => toggleAssignment(member.id)}
                                                style={{
                                                    display: 'flex',
                                                    alignItems: 'center',
                                                    gap: 'var(--space-sm)',
                                                    padding: 'var(--space-sm) var(--space-md)',
                                                    background: formData.assigned_to.includes(member.id)
                                                        ? 'rgba(99, 102, 241, 0.1)'
                                                        : 'var(--card)',
                                                    border: `2px solid ${formData.assigned_to.includes(member.id) ? 'var(--primary-500)' : 'var(--border)'}`,
                                                    borderRadius: 'var(--radius-md)',
                                                    cursor: 'pointer',
                                                    transition: 'all var(--transition-fast)'
                                                }}
                                            >
                                                <Avatar name={member.name} image={member.avatar_url} size="sm" />
                                                <span style={{ fontSize: 'var(--text-sm)' }}>{member.name}</span>
                                            </div>
                                        ))}
                                </div>
                                {members.filter(member => formData.is_global || member.classroom_id === currentUserProfile?.classroom_id).length === 0 && (
                                    <p className="text-xs text-muted italic">No members found in this classroom.</p>
                                )}
                            </div>
                        )}

                        {/* Deliverables */}
                        <div className="input-group">
                            <label className="input-label">Acceptable Deliverables</label>
                            <div style={{
                                display: 'grid',
                                gridTemplateColumns: 'repeat(auto-fill, minmax(180px, 1fr))',
                                gap: 'var(--space-sm)'
                            }}>
                                {[
                                    { id: 'repo_url', label: 'Repository URL', icon: '🔗' },
                                    { id: 'file_upload', label: 'File Upload', icon: '📁' },
                                    { id: 'live_demo', label: 'Live Demo URL', icon: '🌐' },
                                    { id: 'design_file', label: 'Design Files', icon: '🎨' },
                                    { id: 'documentation', label: 'Documentation', icon: '📄' },
                                    { id: 'other', label: 'Other', icon: '📝' }
                                ].map(type => (
                                    <div
                                        key={type.id}
                                        onClick={() => toggleDeliverableType(type.id)}
                                        style={{
                                            display: 'flex',
                                            alignItems: 'center',
                                            gap: 'var(--space-sm)',
                                            padding: 'var(--space-sm) var(--space-md)',
                                            background: formData.deliverable_types.includes(type.id)
                                                ? 'rgba(99, 102, 241, 0.1)'
                                                : 'var(--card)',
                                            border: `2px solid ${formData.deliverable_types.includes(type.id) ? 'var(--primary-500)' : 'var(--border)'}`,
                                            borderRadius: 'var(--radius-md)',
                                            cursor: 'pointer',
                                            transition: 'all var(--transition-fast)'
                                        }}
                                    >
                                        <div className={`checkbox ${formData.deliverable_types.includes(type.id) ? 'checked' : ''}`}>
                                            {formData.deliverable_types.includes(type.id) && (
                                                <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3">
                                                    <polyline points="20 6 9 17 4 12" />
                                                </svg>
                                            )}
                                        </div>
                                        <span style={{ fontSize: 'var(--text-sm)', marginRight: 'auto' }}>{type.label}</span>
                                        <span style={{ fontSize: '16px' }}>{type.icon}</span>
                                    </div>
                                ))}
                            </div>
                        </div>

                        {/* Evaluation Criteria */}
                        <div className="input-group">
                            <label className="input-label">Evaluation Criteria</label>
                            <div style={{ display: 'flex', gap: 'var(--space-sm)', marginBottom: 'var(--space-sm)' }}>
                                <Input
                                    placeholder="Add custom criteria (e.g. 'Unit tests passing')"
                                    id="custom-criteria-input"
                                />
                                <Button
                                    type="button"
                                    size="sm"
                                    onClick={() => {
                                        const input = document.getElementById('custom-criteria-input');
                                        if (input && input.value.trim()) {
                                            const newVal = input.value.trim();
                                            if (!formData.criteria.includes(newVal)) {
                                                setFormData(prev => ({ ...prev, criteria: [...prev.criteria, newVal] }));
                                            }
                                            input.value = '';
                                        }
                                    }}
                                >
                                    Add Custom
                                </Button>
                            </div>

                            <div style={{
                                display: 'grid',
                                gridTemplateColumns: 'repeat(auto-fill, minmax(180px, 1fr))',
                                gap: 'var(--space-sm)'
                            }}>
                                {EVALUATION_CRITERIA.map(criteria => (
                                    <div
                                        key={criteria.id}
                                        onClick={() => toggleCriteria(criteria.id)}
                                        style={{
                                            padding: 'var(--space-sm) var(--space-md)',
                                            background: formData.criteria.includes(criteria.id)
                                                ? 'rgba(99, 102, 241, 0.1)'
                                                : 'var(--card)',
                                            border: `2px solid ${formData.criteria.includes(criteria.id) ? 'var(--primary-500)' : 'var(--border)'}`,
                                            borderRadius: 'var(--radius-md)',
                                            cursor: 'pointer',
                                            display: 'flex',
                                            alignItems: 'center',
                                            gap: 'var(--space-sm)'
                                        }}
                                    >
                                        <div className={`checkbox ${formData.criteria.includes(criteria.id) ? 'checked' : ''}`}>
                                            {formData.criteria.includes(criteria.id) && (
                                                <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3">
                                                    <polyline points="20 6 9 17 4 12" />
                                                </svg>
                                            )}
                                        </div>
                                        <span style={{ fontSize: 'var(--text-sm)' }}>{criteria.label}</span>
                                        {criteria.auto && (
                                            <Badge variant="accent" style={{ marginLeft: 'auto', fontSize: '10px' }}>
                                                Auto
                                            </Badge>
                                        )}
                                    </div>
                                ))}

                                {formData.criteria
                                    .filter(c => !EVALUATION_CRITERIA.some(ec => ec.id === c))
                                    .map(customCriteria => (
                                        <div
                                            key={customCriteria}
                                            onClick={() => toggleCriteria(customCriteria)}
                                            style={{
                                                padding: 'var(--space-sm) var(--space-md)',
                                                background: 'rgba(99, 102, 241, 0.1)',
                                                border: '2px solid var(--primary-500)',
                                                borderRadius: 'var(--radius-md)',
                                                cursor: 'pointer',
                                                display: 'flex',
                                                alignItems: 'center',
                                                gap: 'var(--space-sm)'
                                            }}
                                        >
                                            <div className="checkbox checked">
                                                <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3">
                                                    <polyline points="20 6 9 17 4 12" />
                                                </svg>
                                            </div>
                                            <span style={{ fontSize: 'var(--text-sm)' }}>{customCriteria}</span>
                                        </div>
                                    ))}
                            </div>
                        </div>
                    </div>

                    <div className="flex justify-end gap-md" style={{ marginTop: 'var(--space-lg)' }}>
                        <Button type="button" variant="secondary" onClick={closeModal}>
                            Cancel
                        </Button>
                        <Button type="submit" loading={saving}>
                            {editingTask ? 'Save Changes' : 'Create Task'}
                        </Button>
                    </div>
                </form>
            </Modal>

            {/* Delete Confirmation Modal */}
            <Modal
                isOpen={!!deleteConfirm}
                onClose={() => setDeleteConfirm(null)}
                title="Delete Task"
                size="sm"
            >
                <p style={{ marginBottom: 'var(--space-lg)' }}>
                    Are you sure you want to delete "<strong>{deleteConfirm?.title}</strong>"?
                    This action cannot be undone.
                </p>
                <div className="flex justify-end gap-md">
                    <Button variant="secondary" onClick={() => setDeleteConfirm(null)}>
                        Cancel
                    </Button>
                    <Button variant="danger" onClick={() => handleDelete(deleteConfirm.id)}>
                        Delete Task
                    </Button>
                </div>
            </Modal>


        </div>
    );
};

export default TaskManager;

import { useState, useEffect } from 'react';
import { Card, Button, Badge, Avatar, Modal, Input, ProgressBar } from '../../components/common';
import { supabase } from '../../lib/supabase';
import { useNavigate } from 'react-router-dom';
import {
    Search,
    UserPlus,
    Mail,
    Award,
    ListTodo,
    HelpCircle,
    Eye,
    Edit2,
    Trash2,
    Trophy,
    Key
} from 'lucide-react';
import * as db from '../../services/database';
import { formatDate, calculateLevel, calculateLevelProgress, BADGES } from '../../utils/constants';

const TeamManagement = () => {
    const navigate = useNavigate();
    const [members, setMembers] = useState([]);
    const [searchQuery, setSearchQuery] = useState('');
    const [selectedMember, setSelectedMember] = useState(null);
    const [showAddModal, setShowAddModal] = useState(false);
    const [showPasswordModal, setShowPasswordModal] = useState(false);
    const [newPassword, setNewPassword] = useState('');
    const [loading, setLoading] = useState(true);
    const [resetting, setResetting] = useState(false);

    useEffect(() => {
        loadMembers();

        // GOD COMMAND: REALTIME UPDATES
        const channel = supabase
            .channel('team-updates')
            .on('postgres_changes', { event: '*', schema: 'public', table: 'profiles' }, () => {
                console.log('Realtime: Profile update detected');
                loadMembers();
            })
            .on('postgres_changes', { event: '*', schema: 'public', table: 'submissions' }, () => {
                console.log('Realtime: Submission update detected');
                loadMembers();
            })
            .on('postgres_changes', { event: '*', schema: 'public', table: 'quiz_attempts' }, () => {
                console.log('Realtime: Quiz attempt update detected');
                loadMembers();
            })
            .subscribe();

        return () => {
            supabase.removeChannel(channel);
        };
    }, []);

    const handleResetPassword = async (email) => {
        if (!window.confirm(`Are you sure you want to send a password reset email to ${email}?`)) {
            return;
        }

        try {
            const result = await db.sendPasswordResetEmail(email);
            if (result.success) {
                alert(`Password reset email has been sent to ${email}`);
            } else {
                alert(`Failed to send reset email: ${result.error}`);
            }
        } catch (error) {
            console.error('Reset password error:', error);
            alert('An unexpected error occurred while sending the reset email.');
        }
    };

    const handleDirectReset = async () => {
        if (!newPassword || newPassword.length < 6) {
            alert('Password must be at least 6 characters.');
            return;
        }

        setResetting(true);
        try {
            // Note: This requires a Supabase Edge Function or Admin API access
            // For now, we call the database service which will handle the logic
            const result = await db.adminResetPassword(selectedMember.id, newPassword);
            
            if (result.success) {
                alert(`Password for ${selectedMember.name} has been updated successfully!`);
                setShowPasswordModal(false);
                setNewPassword('');
            } else {
                alert(`Error: ${result.error || 'Failed to update password. You may need to enable the Admin Edge Function.'}`);
            }
        } catch (error) {
            console.error('Reset error:', error);
            alert('An unexpected error occurred.');
        } finally {
            setResetting(false);
        }
    };

    const loadMembers = async () => {
        try {
            setLoading(true);
            const [membersData, submissionsData, attemptsData] = await Promise.all([
                db.getMembers(),
                db.getSubmissions(),
                db.getQuizAttempts()
            ]);

            const enrichedMembers = membersData.map(user => {
                const userSubmissions = submissionsData.filter(s => s.user_id === user.id);
                const userQuizzes = attemptsData.filter(a => a.user_id === user.id);

                return {
                    ...user,
                    tasksCompleted: userSubmissions.filter(s => s.status === 'approved').length,
                    tasksPending: userSubmissions.filter(s => s.status === 'pending').length,
                    quizzesTaken: userQuizzes.length
                };
            });

            setMembers(enrichedMembers);
        } catch (error) {
            console.error('Error loading members:', error);
        } finally {
            setLoading(false);
        }
    };

    const filteredMembers = members.filter(member =>
        member.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
        member.email.toLowerCase().includes(searchQuery.toLowerCase())
    );

    if (loading) {
        return (
            <div className="flex items-center justify-center" style={{ minHeight: '400px' }}>
                <div className="loading-spinner" />
            </div>
        );
    }

    return (
        <div className="animate-fade-in">
            {/* Header */}
            <div className="flex flex-mobile-col justify-between items-center mb-lg">
                <p style={{ color: 'var(--text-muted)' }}>
                    View and manage your team members
                </p>
                <Button icon={UserPlus} onClick={() => navigate('/admin/invite-codes')}>
                    Manage Invites
                </Button>
            </div>

            {/* Search */}
            <Card style={{ marginBottom: 'var(--space-lg)', padding: 'var(--space-md)' }}>
                <Input
                    placeholder="Search members..."
                    icon={Search}
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                />
            </Card>

            {/* Stats Bar */}
            <div className="team-stats-grid mb-lg">
                <Card style={{ padding: 'var(--space-md)', textAlign: 'center' }}>
                    <h3 style={{ fontSize: 'var(--text-2xl)', margin: 0 }}>{members.length}</h3>
                    <p style={{ fontSize: 'var(--text-xs)', color: 'var(--text-muted)', margin: 0, marginTop: '4px' }}>
                        Total Members
                    </p>
                </Card>
                <Card style={{ padding: 'var(--space-md)', textAlign: 'center' }}>
                    <h3 style={{ fontSize: 'var(--text-2xl)', margin: 0 }}>
                        {members.reduce((sum, m) => sum + m.tasksCompleted, 0)}
                    </h3>
                    <p style={{ fontSize: 'var(--text-xs)', color: 'var(--text-muted)', margin: 0, marginTop: '4px' }}>
                        Tasks Completed
                    </p>
                </Card>
                <Card style={{ padding: 'var(--space-md)', textAlign: 'center' }}>
                    <h3 style={{ fontSize: 'var(--text-2xl)', margin: 0 }}>
                        {members.reduce((sum, m) => sum + m.quizzesTaken, 0)}
                    </h3>
                    <p style={{ fontSize: 'var(--text-xs)', color: 'var(--text-muted)', margin: 0, marginTop: '4px' }}>
                        Quizzes Taken
                    </p>
                </Card>
                <Card style={{ padding: 'var(--space-md)', textAlign: 'center' }}>
                    <h3 style={{ fontSize: 'var(--text-2xl)', margin: 0 }}>
                        {members.reduce((sum, m) => sum + (m.xp || 0), 0).toLocaleString()}
                    </h3>
                    <p style={{ fontSize: 'var(--text-xs)', color: 'var(--text-muted)', margin: 0, marginTop: '4px' }}>
                        Total XP Earned
                    </p>
                </Card>
            </div>

            {/* Desktop Members Table */}
            <div className="desktop-team-view">
                <Card style={{ padding: 0, overflow: 'hidden' }}>
                    <div className="table-container">
                        <table className="table">
                            <thead>
                                <tr>
                                    <th>Member</th>
                                    <th>XP</th>
                                    <th>Tasks</th>
                                    <th>Quizzes</th>
                                    <th>Badges</th>
                                    <th>Joined</th>
                                    <th></th>
                                </tr>
                            </thead>
                            <tbody>
                                {filteredMembers.map(member => (
                                    <tr key={member.id}>
                                        <td>
                                            <div className="flex items-center gap-md">
                                                <Avatar name={member.name} image={member.avatar_url} size="md" />
                                                <div>
                                                    <p style={{ margin: 0, fontWeight: 500 }}>{member.name}</p>
                                                    <p style={{ margin: 0, fontSize: 'var(--text-xs)', color: 'var(--text-muted)' }}>
                                                        {member.email}
                                                    </p>
                                                </div>
                                            </div>
                                        </td>
                                        <td>
                                            <span style={{ color: 'var(--primary-400)', fontWeight: 600 }}>
                                                {(member.xp || 0).toLocaleString()}
                                            </span>
                                        </td>
                                        <td>
                                            <div className="flex items-center gap-xs">
                                                <span style={{ color: 'var(--success-500)' }}>{member.tasksCompleted}</span>
                                                {member.tasksPending > 0 && (
                                                    <Badge variant="warning" style={{ fontSize: '10px' }}>
                                                        {member.tasksPending} pending
                                                    </Badge>
                                                )}
                                            </div>
                                        </td>
                                        <td>{member.quizzesTaken}</td>
                                        <td>
                                            <div className="flex gap-xs">
                                                {member.badges?.slice(0, 3).map(badgeId => {
                                                    const badge = BADGES.find(b => b.id === badgeId);
                                                    return badge ? (
                                                        <span key={badgeId} title={badge.name} style={{ fontSize: '18px' }}>
                                                            {badge.icon}
                                                        </span>
                                                    ) : null;
                                                })}
                                                {(member.badges?.length || 0) > 3 && (
                                                    <span style={{ fontSize: 'var(--text-xs)', color: 'var(--text-muted)' }}>
                                                        +{member.badges.length - 3}
                                                    </span>
                                                )}
                                            </div>
                                        </td>
                                        <td style={{ color: 'var(--text-muted)', fontSize: 'var(--text-sm)' }}>
                                            {formatDate(member.created_at)}
                                        </td>
                                        <td className="flex justify-end items-center gap-xs">
                                            <Button
                                                variant="ghost"
                                                size="icon"
                                                onClick={() => {
                                                    setSelectedMember(member);
                                                    setShowPasswordModal(true);
                                                }}
                                                title="Directly Set New Password"
                                                style={{ color: 'var(--warning-500)' }}
                                            >
                                                <Key size={16} />
                                            </Button>
                                            <Button
                                                variant="ghost"
                                                size="icon"
                                                onClick={() => navigate(`/admin/member/${member.id}`)}
                                                title="View Details"
                                            >
                                                <Eye size={16} />
                                            </Button>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                </Card>
            </div>

            {/* Mobile Members List */}
            <div className="mobile-team-view">
                <div className="flex flex-col gap-md">
                    {filteredMembers.map(member => (
                        <Card key={member.id} className="mobile-member-card" style={{ padding: 'var(--space-md)' }}>
                            <div className="flex justify-between items-start mb-md">
                                <div className="flex items-center gap-md">
                                    <Avatar name={member.name} image={member.avatar_url} size="md" />
                                    <div>
                                        <p style={{ margin: 0, fontWeight: 600, fontSize: '1rem' }}>{member.name}</p>
                                        <p style={{ margin: 0, fontSize: '0.8rem', color: 'var(--text-muted)' }}>{member.email}</p>
                                    </div>
                                </div>
                                <span style={{ color: 'var(--primary-400)', fontWeight: 700, fontSize: '1.1rem' }}>
                                    {(member.xp || 0).toLocaleString()} XP
                                </span>
                            </div>

                            <div className="mobile-member-stats">
                                <div className="stat-pill">
                                    <span className="stat-label">Tasks</span>
                                    <div className="flex items-center gap-xs">
                                        <span className="stat-val text-success">{member.tasksCompleted}</span>
                                        {member.tasksPending > 0 && <span className="stat-warn">({member.tasksPending} pend)</span>}
                                    </div>
                                </div>
                                <div className="stat-pill">
                                    <span className="stat-label">Quizzes</span>
                                    <span className="stat-val">{member.quizzesTaken}</span>
                                </div>
                                <div className="stat-pill">
                                    <span className="stat-label">Badges</span>
                                    <div className="flex gap-xs items-center">
                                        {member.badges?.slice(0, 3).map(badgeId => {
                                            const badge = BADGES.find(b => b.id === badgeId);
                                            return badge ? <span key={badgeId} style={{ fontSize: '16px' }}>{badge.icon}</span> : null;
                                        })}
                                        {(member.badges?.length || 0) > 3 && (
                                            <span style={{ fontSize: '10px', color: 'var(--text-muted)' }}>+{member.badges.length - 3}</span>
                                        )}
                                        {(!member.badges || member.badges.length === 0) && <span className="stat-val">0</span>}
                                    </div>
                                </div>
                            </div>

                            <div className="flex justify-between items-center mt-md pt-md border-t">
                                <span style={{ fontSize: '0.75rem', color: 'var(--text-muted)' }}>Joined {formatDate(member.created_at)}</span>
                                <div className="flex gap-sm">
                                    <Button
                                        variant="ghost"
                                        size="sm"
                                        onClick={() => {
                                            setSelectedMember(member);
                                            setShowPasswordModal(true);
                                        }}
                                        style={{ color: 'var(--warning-500)', padding: '0.5rem' }}
                                    >
                                        <Key size={16} />
                                    </Button>
                                    <Button
                                        variant="primary"
                                        size="sm"
                                        onClick={() => navigate(`/admin/member/${member.id}`)}
                                        style={{ padding: '0.5rem 1rem' }}
                                    >
                                        View Profile
                                    </Button>
                                </div>
                            </div>
                        </Card>
                    ))}
                </div>
            </div>

            {/* Password Reset Modal */}
            <Modal
                isOpen={showPasswordModal}
                onClose={() => setShowPasswordModal(false)}
                title={`Set Password for ${selectedMember?.name}`}
                size="sm"
            >
                <div className="flex flex-col gap-md">
                    <p style={{ color: 'var(--text-muted)', fontSize: 'var(--text-sm)' }}>
                        Since you are using fake emails, this will directly update the password in the system.
                    </p>
                    <Input
                        type="password"
                        label="New Password"
                        placeholder="Min 6 characters"
                        value={newPassword}
                        onChange={(e) => setNewPassword(e.target.value)}
                        required
                    />
                    <div className="flex gap-sm mt-md">
                        <Button
                            variant="secondary"
                            onClick={() => setShowPasswordModal(false)}
                            style={{ flex: 1 }}
                        >
                            Cancel
                        </Button>
                        <Button
                            onClick={handleDirectReset}
                            loading={resetting}
                            style={{ flex: 1 }}
                        >
                            Update Password
                        </Button>
                    </div>
                </div>
            </Modal>

            {/* Invite Modal */}
            <Modal
                isOpen={showAddModal}
                onClose={() => setShowAddModal(false)}
                title="Invite Team Member"
                size="sm"
            >
                <div className="flex flex-col gap-md">
                    <p style={{ color: 'var(--text-muted)' }}>
                        Share this link with new team members to invite them to join Zenith.
                    </p>
                    <div style={{
                        padding: 'var(--space-md)',
                        background: 'var(--card)',
                        borderRadius: 'var(--radius-md)',
                        border: '1px solid var(--border)',
                        wordBreak: 'break-all',
                        fontSize: 'var(--text-sm)'
                    }}>
                        {window.location.origin}/register
                    </div>
                    <Button
                        onClick={() => {
                            navigator.clipboard.writeText(`${window.location.origin}/register`);
                            alert('Link copied to clipboard!');
                        }}
                    >
                        Copy Invite Link
                    </Button>
                </div>
            </Modal>

            <style>{`
                .team-stats-grid {
                    display: grid;
                    grid-template-columns: repeat(4, 1fr);
                    gap: var(--space-md);
                }
                
                .mobile-team-view {
                    display: none;
                }
                
                .desktop-team-view {
                    display: block;
                }
                
                .border-t {
                    border-top: 1px solid var(--border);
                }

                @media (max-width: 768px) {
                    .team-stats-grid {
                        grid-template-columns: repeat(2, 1fr);
                    }
                    
                    .desktop-team-view {
                        display: none;
                    }
                    
                    .mobile-team-view {
                        display: block;
                    }
                    
                    .mobile-member-card {
                        transition: transform 0.2s, box-shadow 0.2s;
                    }
                    
                    .mobile-member-card:active {
                        transform: scale(0.98);
                    }

                    .mobile-member-stats {
                        display: grid;
                        grid-template-columns: repeat(3, 1fr);
                        gap: var(--space-sm);
                        background: var(--background);
                        padding: var(--space-sm);
                        border-radius: var(--radius-md);
                        margin-bottom: var(--space-sm);
                    }

                    .stat-pill {
                        display: flex;
                        flex-direction: column;
                        align-items: center;
                        text-align: center;
                    }

                    .stat-label {
                        font-size: 0.65rem;
                        text-transform: uppercase;
                        letter-spacing: 0.5px;
                        color: var(--text-muted);
                        margin-bottom: 2px;
                    }

                    .stat-val {
                        font-weight: 600;
                        font-size: 0.9rem;
                    }
                    
                    .text-success {
                        color: var(--success-500);
                    }
                    
                    .stat-warn {
                        color: var(--warning-500);
                        font-size: 0.7rem;
                        font-weight: 500;
                    }
                }
            `}</style>
        </div>
    );
};

export default TeamManagement;

