import { useState, useEffect, useCallback, useRef } from 'react';
import { useAuth } from '../../context/AuthContext';
import { Card, Badge, Button, Input, Modal } from '../../components/common';
import {
    RefreshCw, Plus, Trash2, CheckCircle, Circle, Clock, Bell,
    Calendar, Brain, Send, Flame, X, Edit3, Check, Mic, MicOff,
    Play, Pause, Square, BarChart3, BookOpen, Map, TrendingUp,
    AlertCircle, Timer, FastForward
} from 'lucide-react';

const DAYS = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
const ROUTINE_XP = 15;

const getKey = (uid) => `zenith_routines_v2_${uid}`;
const load = (uid) => { 
    try { 
        return JSON.parse(localStorage.getItem(getKey(uid))) || { 
            routines: [], 
            sessions: [],
            aiChats: [],
            weeklyTimetable: null
        }; 
    } catch { 
        return { routines: [], sessions: [], aiChats: [], weeklyTimetable: null }; 
    } 
};
const save = (uid, d) => localStorage.setItem(getKey(uid), JSON.stringify(d));

const RoutinesEnhanced = () => {
    const { user } = useAuth();
    const [data, setData] = useState({ routines: [], sessions: [], aiChats: [], weeklyTimetable: null });
    const [showAdd, setShowAdd] = useState(false);
    const [showAI, setShowAI] = useState(false);
    const [form, setForm] = useState({ 
        title: '', 
        time: '09:00', 
        days: [1,2,3,4,5], 
        deadline: '',
        category: 'coursework',
        estimatedDuration: 60,
        responseTimeout: 30,
        alarmEnabled: true,
        color: '#6366f1'
    });
    const [aiInput, setAiInput] = useState('');
    const [aiLoading, setAiLoading] = useState(false);
    const [selectedDate, setSelectedDate] = useState(new Date().toISOString().split('T')[0]);
    const [activeSession, setActiveSession] = useState(null);
    const [activeAlarm, setActiveAlarm] = useState(null);
    const [isRecording, setIsRecording] = useState(false);
    const [audioURL, setAudioURL] = useState(null);
    const [sessionForm, setSessionForm] = useState({
        whatLearned: '',
        notes: '',
        timeSpent: 0
    });
    const [view, setView] = useState('today'); // 'today' | 'diary' | 'analytics' | 'timetable'
    
    const timersRef = useRef([]);
    const sessionTimerRef = useRef(null);
    const alarmTimeoutRef = useRef(null);
    const mediaRecorderRef = useRef(null);
    const audioChunksRef = useRef([]);

    useEffect(() => {
        if (user?.id) setData(load(user.id));
    }, [user?.id]);

    const persist = useCallback((d) => { 
        setData(d); 
        if (user?.id) save(user.id, d); 
    }, [user?.id]);

    // This is a comprehensive system - I'll create it in a new file
    // to avoid breaking the existing Routines page
    
    return (
        <div className="animate-fade-in" style={{ paddingBottom: 'var(--space-2xl)' }}>
            <div className="flex flex-mobile-col justify-between items-center mb-lg">
                <div>
                    <h2 style={{ margin: 0 }}>🎯 Coursework Tracker</h2>
                    <p style={{ color: 'var(--text-muted)', margin: 0 }}>
                        Track your learning journey with AI-powered scheduling
                    </p>
                </div>
            </div>

            <Card>
                <div style={{ textAlign: 'center', padding: 'var(--space-2xl)' }}>
                    <RefreshCw size={48} style={{ color: 'var(--primary-500)', marginBottom: 'var(--space-md)' }} />
                    <h3>Enhanced Routine System Coming Soon!</h3>
                    <p style={{ color: 'var(--text-muted)', marginBottom: 'var(--space-lg)' }}>
                        This comprehensive system includes:
                    </p>
                    <div style={{ 
                        display: 'grid', 
                        gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))',
                        gap: 'var(--space-md)',
                        textAlign: 'left',
                        marginTop: 'var(--space-lg)'
                    }}>
                        <div style={{ padding: 'var(--space-md)', background: 'var(--surface)', borderRadius: 'var(--radius-md)' }}>
                            <Timer size={24} style={{ color: 'var(--primary-500)', marginBottom: 'var(--space-sm)' }} />
                            <h4 style={{ margin: '0 0 4px' }}>Time Tracking</h4>
                            <p style={{ fontSize: 'var(--text-sm)', color: 'var(--text-muted)', margin: 0 }}>
                                Log how much time you spend on each task
                            </p>
                        </div>
                        <div style={{ padding: 'var(--space-md)', background: 'var(--surface)', borderRadius: 'var(--radius-md)' }}>
                            <BookOpen size={24} style={{ color: 'var(--success-500)', marginBottom: 'var(--space-sm)' }} />
                            <h4 style={{ margin: '0 0 4px' }}>Learning Diary</h4>
                            <p style={{ fontSize: 'var(--text-sm)', color: 'var(--text-muted)', margin: 0 }}>
                                Document what you learned each day
                            </p>
                        </div>
                        <div style={{ padding: 'var(--space-md)', background: 'var(--surface)', borderRadius: 'var(--radius-md)' }}>
                            <BarChart3 size={24} style={{ color: 'var(--warning-500)', marginBottom: 'var(--space-sm)' }} />
                            <h4 style={{ margin: '0 0 4px' }}>Analytics</h4>
                            <p style={{ fontSize: 'var(--text-sm)', color: 'var(--text-muted)', margin: 0 }}>
                                Track progress, streaks, and completion rates
                            </p>
                        </div>
                        <div style={{ padding: 'var(--space-md)', background: 'var(--surface)', borderRadius: 'var(--radius-md)' }}>
                            <Brain size={24} style={{ color: 'var(--accent-500)', marginBottom: 'var(--space-sm)' }} />
                            <h4 style={{ margin: '0 0 4px' }}>AI Timetable</h4>
                            <p style={{ fontSize: 'var(--text-sm)', color: 'var(--text-muted)', margin: 0 }}>
                                Generate weekly schedules with AI
                            </p>
                        </div>
                    </div>
                    <p style={{ 
                        marginTop: 'var(--space-xl)', 
                        padding: 'var(--space-md)', 
                        background: 'rgba(99, 102, 241, 0.1)',
                        borderRadius: 'var(--radius-md)',
                        color: 'var(--text-muted)'
                    }}>
                        💡 This feature is being built with session tracking, postpone functionality, 
                        response timeouts, mind maps, and comprehensive analytics. Stay tuned!
                    </p>
                </div>
            </Card>
        </div>
    );
};

export default RoutinesEnhanced;

import { useState, useEffect, useRef } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { Card, Button, Badge, LoadingSpinner } from '../../components/common';
import { 
    BookOpen, Send, Printer, Maximize2, Minimize2, 
    ChevronLeft, ChevronRight, Share2, Sparkles, FileText, 
    Download, Info, Settings, MessageSquare,
    Eye, EyeOff, ExternalLink, Globe, RefreshCw,
    Brain, CloudLightning
} from 'lucide-react';
import { supabase } from '../../lib/supabase';
import { generateChat } from '../../services/aiService';
import { useAuth } from '../../context/AuthContext';
import ReactMarkdown from 'react-markdown';

const StudyLab = () => {
    const { id: materialId } = useParams();
    const { user } = useAuth();
    const navigate = useNavigate();
    const [loading, setLoading] = useState(true);
    const [material, setMaterial] = useState(null);
    const [messages, setMessages] = useState([]);
    const [input, setInput] = useState('');
    const [sending, setSending] = useState(false);
    const [isFullScreen, setIsFullScreen] = useState(false);
    const [viewMode, setViewMode] = useState('split'); // 'split', 'doc', 'chat'
    const [showSyncModal, setShowSyncModal] = useState(false);
    const [syncText, setSyncText] = useState('');
    const [history, setHistory] = useState([]);
    const [historyIndex, setHistoryIndex] = useState(-1);
    const [urlInput, setUrlInput] = useState('');
    const [isMobile, setIsMobile] = useState(window.innerWidth < 1024);
    const chatEndRef = useRef(null);
    const printRef = useRef(null);

    useEffect(() => {
        const handleResize = () => setIsMobile(window.innerWidth < 1024);
        window.addEventListener('resize', handleResize);
        return () => window.removeEventListener('resize', handleResize);
    }, []);

    useEffect(() => {
        if (material?.file_url && urlInput === '') {
            setUrlInput(material.file_url);
        }
    }, [material?.file_url]);

    useEffect(() => {
        if (materialId) {
            fetchMaterial();
        }
    }, [materialId]);

    useEffect(() => {
        chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
        if (messages.length > 1) {
            saveChatHistory(messages);
        }
    }, [messages]);

    const fetchMaterial = async () => {
        setLoading(true);
        try {
            // Check both tables
            const [noteRes, kbRes] = await Promise.all([
                supabase.from('study_notes').select('*').eq('id', materialId).maybeSingle(),
                supabase.from('knowledge_base').select('*').eq('id', materialId).maybeSingle()
            ]);

            const foundMaterial = noteRes.data || kbRes.data;
            if (foundMaterial) {
                setMaterial(foundMaterial);
                if (foundMaterial.file_url) {
                    setHistory([foundMaterial.file_url]);
                    setHistoryIndex(0);
                    setUrlInput(foundMaterial.file_url);
                }
                // Load existing chat history from ai_history
                const { data: historyData } = await supabase
                    .from('ai_history')
                    .select('*')
                    .eq('user_id', user.id)
                    .eq('tool', 'study_lab')
                    .eq('title', materialId)
                    .maybeSingle();

                if (historyData?.content?.messages) {
                    setMessages(historyData.content.messages);
                } else {
                    setMessages([
                        { 
                            role: 'assistant', 
                            content: `Zenith Lab Assistant Online. **Note: I cannot see the document viewer directly.** To help you accurately, please copy and paste the specific sections you're studying into our chat. How can I help you today?` 
                        }
                    ]);
                }
            }
        } catch (err) {
            console.error('Error fetching material:', err);
        } finally {
            setLoading(false);
        }
    };

    const syncContext = async () => {
        if (!syncText.trim()) return;
        
        try {
            // Update the source material in DB so AI has it forever
            const table = material?.course_id ? 'knowledge_base' : 'study_notes';
            const { error } = await supabase
                .from(table)
                .update({ content: syncText })
                .eq('id', materialId);

            if (error) throw error;

            setMaterial(prev => ({ ...prev, content: syncText }));
            setShowSyncModal(false);
            setSyncText('');
            setMessages(prev => [...prev, { role: 'assistant', content: "🧠 **Knowledge Sync Complete.** I have successfully indexed the document text and saved it to my long-term memory. I am now fully ready to assist you with this specific content." }]);
        } catch (err) {
            console.error('Error syncing context:', err);
            alert('Failed to sync context. Please try again.');
        }
    };

    const saveChatHistory = async (newMessages) => {
        try {
            await supabase.from('ai_history').upsert({
                user_id: user.id,
                tool: 'study_lab',
                title: materialId,
                content: { messages: newMessages },
                created_at: new Date().toISOString()
            }, { onConflict: 'user_id,tool,title' });
        } catch (err) {
            console.error('Error saving chat history:', err);
        }
    };

    const handleCommand = (text) => {
        const printMatch = text.toLowerCase().match(/print (page|all)\s*(\d+)?/);
        if (printMatch) {
            const type = printMatch[1];
            const pageNum = printMatch[2];
            handlePrint(type, pageNum);
            return true;
        }
        return false;
    };

    const handlePrint = (type, pageNum) => {
        const printWindow = window.open('', '_blank');
        const content = material?.content || 'No content available';
        
        // Basic page splitting by double newline or custom marker
        const pages = content.split(/\n\s*\n/); 
        let printContent = '';

        if (type === 'all') {
            printContent = pages.join('<div style="page-break-after: always;"></div>');
        } else if (pageNum && pages[pageNum - 1]) {
            printContent = pages[pageNum - 1];
        } else {
            printContent = content;
        }

        printWindow.document.write(`
            <html>
                <head>
                    <title>Zenith Lab - ${material?.title}</title>
                    <style>
                        body { font-family: 'Inter', system-ui, sans-serif; line-height: 1.6; color: #1a1a1a; padding: 40px; max-width: 800px; margin: 0 auto; }
                        h1 { color: #000; border-bottom: 2px solid #eee; padding-bottom: 10px; }
                        pre { background: #f4f4f4; padding: 15px; border-radius: 8px; overflow-x: auto; }
                        .footer { margin-top: 50px; font-size: 12px; color: #888; text-align: center; border-top: 1px solid #eee; padding-top: 20px; }
                        @media print { .no-print { display: none; } }
                    </style>
                </head>
                <body>
                    <h1>${material?.title}</h1>
                    <div class="content">${printContent}</div>
                    <div class="footer">Generated by Zenith Study Lab - ${new Date().toLocaleDateString()}</div>
                    <script>window.onload = () => { window.print(); window.close(); };</script>
                </body>
            </html>
        `);
        printWindow.document.close();

        setMessages(prev => [...prev, { role: 'user', content: text }, { role: 'assistant', content: `🖨️ Preparation complete. Sent ${type === 'all' ? 'the full document' : `page ${pageNum}`} to the printer.` }]);
    };

    const handleSendMessage = async (e, systemMessage = null) => {
        e?.preventDefault();
        
        const userMsg = systemMessage || input.trim();
        if (!userMsg || sending) return;

        if (!systemMessage) {
            setInput('');
        }
        
        // 1. Check for local commands (like print)
        if (handleCommand(userMsg)) {
            return;
        }

        // 2. Otherwise use AI
        setMessages(prev => [...prev, { role: 'user', content: userMsg }]);
        setSending(true);

        try {
            // Filter history to remove old apologies
            const cleanHistory = messages.filter(m => !m.content.toLowerCase().includes("don't have access") && !m.content.toLowerCase().includes("sync ai"));

            const systemPrompt = `You are the Zenith Lab Assistant. 
            
            CRITICAL DISCLOSURE:
            1. You CANNOT see the document viewer or the material's file content directly.
            2. You MUST inform the student of this limitation if they ask questions about the current document's specific text.
            3. ASK the student to copy and paste the relevant text into the chat for analysis.
            4. If the student has already pasted content into the chat history, use it.
            
            MATERIAL METADATA:
            TITLE: ${material?.title}
            
            ${material?.content && material.content !== 'Attached Material' ? `STORED INDEX: ${material.content}` : 'The student has not yet synced/pasted content.'}
            
            STRICT DIRECTIVES:
            - Be transparent about your vision limitation.
            - Provide academic guidance based ONLY on pasted text or the TITLE metadata.
            - Maintain a professional CS Professor persona.`;

            const response = await generateChat([...cleanHistory, { role: 'user', content: userMsg }], systemPrompt);
            setMessages(prev => [...prev, { role: 'assistant', content: response }]);
        } catch (err) {
            setMessages(prev => [...prev, { role: 'assistant', content: "Sorry, I ran into an error processing your request. Please try again." }]);
        } finally {
            setSending(false);
        }
    };

    if (loading) return (
        <div style={{ height: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center', background: 'var(--bg-dark)' }}>
            <LoadingSpinner size="lg" color="var(--primary-500)" />
        </div>
    );

    if (!materialId) {
        return (
            <div style={{ padding: 'var(--space-xl)', maxWidth: '1200px', margin: '0 auto' }}>
                <div style={{ marginBottom: 'var(--space-xl)', textAlign: 'center' }}>
                    <h1 style={{ fontSize: 'var(--text-4xl)', fontWeight: 800, marginBottom: 'var(--space-md)' }}>Study <span style={{ color: 'var(--primary-500)' }}>Lab</span></h1>
                    <p style={{ color: 'var(--text-muted)' }}>Select a material to begin your AI-powered deep dive.</p>
                </div>
                <Button onClick={() => navigate('/study-materials')} variant="primary">
                    <BookOpen size={20} style={{ marginRight: '8px' }} /> Browse Materials
                </Button>
            </div>
        );
    }

    return (
        <div style={{ 
            height: '100vh', 
            display: 'flex', 
            flexDirection: 'column', 
            background: 'var(--bg-dark)',
            color: 'white',
            overflow: 'hidden'
        }}>
            {/* Header */}
            <header style={{ 
                height: isMobile ? 'auto' : '64px', 
                padding: isMobile ? 'var(--space-sm) var(--space-md)' : '0 var(--space-lg)', 
                display: 'flex', 
                flexDirection: isMobile ? 'column' : 'row',
                alignItems: isMobile ? 'stretch' : 'center', 
                justifyContent: 'space-between',
                background: 'rgba(20, 20, 25, 0.95)',
                backdropFilter: 'blur(15px)',
                borderBottom: '1px solid rgba(255,255,255,0.1)',
                gap: isMobile ? 'var(--space-sm)' : '0',
                zIndex: 100
            }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-md)' }}>
                    <button 
                        onClick={() => navigate(-1)}
                        style={{ background: 'rgba(255,255,255,0.05)', border: 'none', borderRadius: '50%', width: isMobile ? '32px' : '36px', height: isMobile ? '32px' : '36px', display: 'flex', alignItems: 'center', justifyContent: 'center', color: 'white', cursor: 'pointer' }}
                    >
                        <ChevronLeft size={isMobile ? 18 : 20} />
                    </button>
                    <div>
                        <h2 style={{ fontSize: isMobile ? 'var(--text-xs)' : 'var(--text-sm)', fontWeight: 700, margin: 0 }}>
                            {isMobile ? (material?.title?.length > 25 ? material.title.substring(0, 22) + '...' : material?.title) : material?.title}
                        </h2>
                        <span style={{ fontSize: '9px', color: 'var(--primary-400)', fontWeight: 800, textTransform: 'uppercase', letterSpacing: '0.05em' }}>Study Lab Mode</span>
                    </div>
                </div>

                <div style={{ display: 'flex', alignItems: 'center', gap: 'var(--space-sm)', justifyContent: isMobile ? 'space-between' : 'flex-end' }}>
                    <Button size="sm" variant="outline" onClick={() => handlePrint('all')} style={{ borderColor: 'rgba(255,255,255,0.1)', padding: isMobile ? '6px' : undefined }}>
                        <Printer size={16} />
                    </Button>
                    <div style={{ background: 'rgba(255,255,255,0.05)', borderRadius: 'var(--radius-md)', padding: '4px', display: 'flex', gap: '2px' }}>
                        <button onClick={() => setViewMode('doc')} style={{ padding: '6px 12px', border: 'none', borderRadius: 'var(--radius-sm)', background: viewMode === 'doc' ? 'var(--primary-500)' : 'transparent', color: 'white', cursor: 'pointer' }}><FileText size={16} /></button>
                        <button onClick={() => setViewMode('split')} style={{ padding: '6px 12px', border: 'none', borderRadius: 'var(--radius-sm)', background: viewMode === 'split' ? 'var(--primary-500)' : 'transparent', color: 'white', cursor: 'pointer' }}><Maximize2 size={16} /></button>
                        <button onClick={() => setViewMode('chat')} style={{ padding: '6px 12px', border: 'none', borderRadius: 'var(--radius-sm)', background: viewMode === 'chat' ? 'var(--primary-500)' : 'transparent', color: 'white', cursor: 'pointer' }}><MessageSquare size={16} /></button>
                    </div>
                </div>
            </header>

            <main style={{ 
                flex: 1, 
                display: 'flex', 
                flexDirection: isMobile ? 'column' : 'row',
                overflow: isMobile ? 'auto' : 'hidden' 
            }}>
                {/* Left: Document Viewer */}
                {(viewMode === 'split' || viewMode === 'doc') && (
                    <div style={{ 
                        flex: 1, 
                        display: 'flex', 
                        flexDirection: 'column',
                        borderRight: isMobile ? 'none' : '1px solid rgba(255,255,255,0.05)',
                        borderBottom: isMobile ? '1px solid rgba(255,255,255,0.05)' : 'none',
                        background: '#0f0f12',
                        height: isMobile && viewMode === 'split' ? '55vh' : '100%',
                        minHeight: isMobile && viewMode === 'split' ? '400px' : 'auto'
                    }}>
                        <div style={{ 
                            flex: 1, 
                            padding: isMobile ? 'var(--space-xs)' : 'var(--space-md)', 
                            overflowY: 'auto',
                            display: 'flex',
                            justifyContent: 'center'
                        }}>
                                <div style={{ 
                                    width: '100%',
                                    maxWidth: viewMode === 'doc' ? '1200px' : 'none',
                                    background: '#1a1a20',
                                    borderRadius: isMobile ? 'var(--radius-md)' : 'var(--radius-xl)',
                                    padding: isMobile ? '4px' : 'var(--space-sm)',
                                    boxShadow: '0 20px 40px rgba(0,0,0,0.4)',
                                    border: '1px solid rgba(255,255,255,0.05)',
                                    position: 'relative',
                                    display: 'flex',
                                    flexDirection: 'column',
                                    height: '100%',
                                    overflow: 'hidden'
                                }}>
                                    {/* Mini Browser Toolbar */}
                                    <div style={{
                                        display: 'flex',
                                        alignItems: 'center',
                                        gap: '12px',
                                        padding: '8px 16px',
                                        background: 'rgba(0,0,0,0.2)',
                                        borderBottom: '1px solid rgba(255,255,255,0.05)',
                                        marginBottom: '12px',
                                        borderRadius: 'var(--radius-md)'
                                    }}>
                                            <div style={{ display: 'flex', gap: '4px' }}>
                                                <button 
                                                    onClick={() => {
                                                        if (historyIndex > 0) {
                                                            const newIndex = historyIndex - 1;
                                                            setHistoryIndex(newIndex);
                                                            const prevUrl = history[newIndex];
                                                            setUrlInput(prevUrl);
                                                            setMaterial(prev => ({ ...prev, file_url: prevUrl }));
                                                        }
                                                    }}
                                                    disabled={historyIndex <= 0}
                                                    style={{ background: 'none', border: 'none', color: historyIndex > 0 ? 'rgba(255,255,255,0.8)' : 'rgba(255,255,255,0.2)', cursor: historyIndex > 0 ? 'pointer' : 'default', padding: '4px' }}
                                                >
                                                    <ChevronLeft size={18} />
                                                </button>
                                                <button 
                                                    onClick={() => {
                                                        if (historyIndex < history.length - 1) {
                                                            const newIndex = historyIndex + 1;
                                                            setHistoryIndex(newIndex);
                                                            const nextUrl = history[newIndex];
                                                            setUrlInput(nextUrl);
                                                            setMaterial(prev => ({ ...prev, file_url: nextUrl }));
                                                        }
                                                    }}
                                                    disabled={historyIndex >= history.length - 1}
                                                    style={{ background: 'none', border: 'none', color: historyIndex < history.length - 1 ? 'rgba(255,255,255,0.8)' : 'rgba(255,255,255,0.2)', cursor: historyIndex < history.length - 1 ? 'pointer' : 'default', padding: '4px' }}
                                                >
                                                    <ChevronRight size={18} />
                                                </button>
                                            </div>
                                            
                                            <div style={{ 
                                                flex: 1, 
                                                background: 'rgba(255,255,255,0.1)', 
                                                padding: '4px 12px', 
                                                borderRadius: '8px',
                                                display: 'flex',
                                                alignItems: 'center',
                                                gap: '10px',
                                                border: '1px solid rgba(255,255,255,0.1)'
                                            }}>
                                                <Globe size={14} className="text-primary" />
                                                <input 
                                                    type="text"
                                                    value={urlInput}
                                                    onChange={(e) => setUrlInput(e.target.value)}
                                                    onKeyDown={(e) => {
                                                        if (e.key === 'Enter') {
                                                            const url = e.target.value;
                                                            // Clear future history if we're in the middle and branch off
                                                            const newHistory = history.slice(0, historyIndex + 1);
                                                            newHistory.push(url);
                                                            setHistory(newHistory);
                                                            setHistoryIndex(newHistory.length - 1);
                                                            setMaterial(prev => ({ ...prev, file_url: url }));
                                                        }
                                                    }}
                                                    style={{ 
                                                        background: 'none', 
                                                        border: 'none', 
                                                        color: urlInput !== material?.file_url ? 'var(--primary-400)' : 'white', 
                                                        fontSize: '12px', 
                                                        width: '100%',
                                                        outline: 'none',
                                                        fontWeight: '500',
                                                        transition: 'color 0.3s ease'
                                                    }}
                                                    placeholder="Paste a link to study (Drive, PDF, Doc...)"
                                                />
                                            </div>
                                            
                                            <div style={{ display: 'flex', gap: '10px', alignItems: 'center' }}>
                                                <Badge variant="outline" style={{ background: 'rgba(255,255,255,0.05)', color: 'rgba(255,255,255,0.4)', border: '1px solid rgba(255,255,255,0.1)', gap: '6px' }}>
                                                    <EyeOff size={12} /> AI Visibility Restricted
                                                </Badge>
                                                
                                                <button 
                                                    onClick={() => {
                                                        const currentUrl = material?.file_url;
                                                        setMaterial(prev => ({ ...prev, file_url: '' }));
                                                        setTimeout(() => setMaterial(prev => ({ ...prev, file_url: currentUrl })), 50);
                                                    }}
                                                    style={{ background: 'none', border: 'none', color: 'rgba(255,255,255,0.6)', cursor: 'pointer', padding: '4px' }}
                                                    title="Refresh View"
                                                >
                                                    <RefreshCw size={16} />
                                                </button>

                                                <a 
                                                    href={material?.file_url} 
                                                    target="_blank" 
                                                    rel="noopener noreferrer"
                                                    style={{ color: 'rgba(255,255,255,0.6)', display: 'flex', alignItems: 'center' }}
                                                    title="Open in Full Browser"
                                                >
                                                    <ExternalLink size={16} />
                                                </a>
                                            </div>
                                    </div>

                                    <div style={{ flex: 1, position: 'relative', overflowY: 'auto' }}>
                                        {material?.file_url ? (
                                            <div style={{ width: '100%', height: '100%', position: 'relative' }}>
                                                {material.file_url.match(/\.(jpeg|jpg|gif|png|webp|svg)$/i) ? (
                                                    <img 
                                                        src={material.file_url} 
                                                        alt="Attached Material" 
                                                        style={{ width: '100%', height: '100%', objectFit: 'contain', borderRadius: 'var(--radius-md)' }} 
                                                    />
                                                ) : (
                                                    <iframe 
                                                        key={material.file_url} // Force reload on URL change
                                                        src={(() => {
                                                            const url = material.file_url;
                                                            if (!url) return '';
                                                            
                                                            if (url.includes('drive.google.com') && (url.includes('/file/d/') || url.includes('id=')) && !url.includes('/folders/')) {
                                                                const fileId = url.match(/\/file\/d\/([a-zA-Z0-9_-]+)/)?.[1] || url.match(/id=([a-zA-Z0-9_-]+)/)?.[1];
                                                                if (fileId && !url.includes('folders')) {
                                                                    // Use the stable /preview mode but with relaxed sandbox for selection
                                                                    return `https://drive.google.com/file/d/${fileId}/preview`;
                                                                }
                                                            }
                                                            
                                                            if (url.includes('drive.google.com') && url.includes('folders')) {
                                                                // Robust folder ID extraction
                                                                const folderId = url.match(/\/folders\/([a-zA-Z0-9_-]+)/)?.[1] || url.match(/id=([a-zA-Z0-9_-]+)/)?.[1];
                                                                if (folderId) {
                                                                    return `https://drive.google.com/embeddedfolderview?id=${folderId}#grid`;
                                                                }
                                                            }

                                                            if (url.includes('drive.google.com')) {
                                                                // Fallback for other drive links
                                                                if (url.includes('/view') || url.includes('/edit')) {
                                                                    return url.replace(/\/view.*$/, '/preview').replace(/\/edit.*$/, '/preview');
                                                                }
                                                                return url;
                                                            }
                                                            
                                                            if (url.includes('docs.google.com')) {
                                                                if (!url.includes('embedded=true')) {
                                                                    const separator = url.includes('?') ? '&' : '?';
                                                                    return `${url}${separator}embedded=true`;
                                                                }
                                                                return url;
                                                            }

                                                            if (url.toLowerCase().endsWith('.pdf') || url.includes('/public/study_materials/')) {
                                                                return `https://docs.google.com/gview?url=${encodeURIComponent(url)}&embedded=true`;
                                                            }

                                                            if (url.match(/\.(doc|docx|ppt|pptx|xls|xlsx)$/i)) {
                                                                return `https://docs.google.com/gview?url=${encodeURIComponent(url)}&embedded=true`;
                                                            }

                                                            return url;
                                                        })()} 
                                                        style={{ width: '100%', height: '100%', border: 'none', borderRadius: 'var(--radius-md)', background: 'white' }}
                                                        title="Resource Viewer"
                                                        allow="autoplay; encrypted-media; clipboard-read; clipboard-write; camera; microphone"
                                                    />
                                                )}
                                            </div>
                                        ) : (
                                            <div className="lab-content" style={{ color: '#d1d1d1', lineHeight: 1.8, fontSize: 'var(--text-base)', padding: 'var(--space-md)' }}>
                                                {material?.content && material.content !== 'Attached Material' ? (
                                                    <ReactMarkdown>{material.content}</ReactMarkdown>
                                                ) : (
                                                    <div style={{ textAlign: 'center', padding: 'var(--space-2xl)', color: 'var(--text-muted)' }}>
                                                        <Info size={48} style={{ marginBottom: 'var(--space-md)', opacity: 0.5 }} />
                                                        <p>Load a URL to begin your deep-study session. AI will automatically index the content.</p>
                                                    </div>
                                                )}
                                            </div>
                                        )}
                                    </div>
                                </div>
                        </div>
                    </div>
                )}

                    {/* Sync Context Modal */}
                    {showSyncModal && (
                        <div style={{
                            position: 'fixed',
                            top: 0,
                            left: 0,
                            right: 0,
                            bottom: 0,
                            background: 'rgba(0,0,0,0.8)',
                            backdropFilter: 'blur(10px)',
                            display: 'flex',
                            alignItems: 'center',
                            justifyContent: 'center',
                            zIndex: 1000,
                            padding: 'var(--space-md)'
                        }}>
                            <div style={{
                                width: '100%',
                                maxWidth: '600px',
                                background: '#1a1a20',
                                borderRadius: 'var(--radius-xl)',
                                border: '1px solid rgba(255,255,255,0.1)',
                                padding: 'var(--space-xl)',
                                display: 'flex',
                                flexDirection: 'column',
                                gap: 'var(--space-md)'
                            }}>
                                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                                    <h3 style={{ margin: 0, display: 'flex', alignItems: 'center', gap: '8px' }}>
                                        <Brain className="text-primary" size={20} />
                                        AI Deep Scan & Sync
                                    </h3>
                                    <button onClick={() => setShowSyncModal(false)} style={{ background: 'none', border: 'none', color: 'rgba(255,255,255,0.5)', cursor: 'pointer' }}><Maximize2 size={16} /></button>
                                </div>
                                <p style={{ fontSize: '12px', color: 'rgba(255,255,255,0.5)', margin: 0 }}>
                                    Because Google Drive and private storage protect content, the AI cannot "see" inside the document automatically. 
                                    **Paste the text from the document below** to sync it with the AI's deep memory.
                                </p>
                                <textarea 
                                    value={syncText}
                                    onChange={(e) => setSyncText(e.target.value)}
                                    placeholder="Paste document content here..."
                                    style={{
                                        width: '100%',
                                        height: '300px',
                                        background: 'rgba(0,0,0,0.2)',
                                        border: '1px solid rgba(255,255,255,0.1)',
                                        borderRadius: 'var(--radius-md)',
                                        padding: 'var(--space-md)',
                                        color: 'white',
                                        fontSize: '13px',
                                        fontFamily: 'monospace',
                                        resize: 'none',
                                        outline: 'none'
                                    }}
                                />
                                <div style={{ display: 'flex', gap: '12px', justifyContent: 'flex-end' }}>
                                    <Button variant="outline" onClick={() => setShowSyncModal(false)}>Cancel</Button>
                                    <Button 
                                        disabled={!syncText.trim()} 
                                        onClick={syncContext}
                                        style={{ display: 'flex', alignItems: 'center', gap: '8px' }}
                                    >
                                        <CloudLightning size={16} /> Sync Brain
                                    </Button>
                                </div>
                            </div>
                        </div>
                    )}

                {/* Right: AI Assistant */}
                {(viewMode === 'split' || viewMode === 'chat') && (
                    <div style={{ 
                        width: isMobile || viewMode === 'chat' ? '100%' : '450px', 
                        flex: isMobile && viewMode === 'split' ? 1 : (isMobile || viewMode === 'chat' ? 'none' : 1),
                        height: isMobile && viewMode === 'split' ? 'auto' : '100%',
                        minHeight: isMobile && viewMode === 'split' ? '500px' : 'auto',
                        display: 'flex', 
                        flexDirection: 'column',
                        background: 'rgba(20, 20, 25, 0.4)',
                        backdropFilter: 'blur(20px)'
                    }}>
                        {/* Chat History */}
                        <div style={{ 
                            flex: 1, 
                            overflowY: 'auto', 
                            padding: isMobile ? 'var(--space-md)' : 'var(--space-lg)',
                            display: 'flex',
                            flexDirection: 'column',
                            gap: isMobile ? 'var(--space-md)' : 'var(--space-lg)'
                        }}>
                            {messages.map((msg, i) => (
                                <div key={i} style={{ 
                                    alignSelf: msg.role === 'user' ? 'flex-end' : 'flex-start',
                                    maxWidth: '90%',
                                    display: 'flex',
                                    flexDirection: 'column',
                                    gap: '6px'
                                }}>
                                    <div style={{ 
                                        padding: isMobile ? '12px 14px' : '16px', 
                                        borderRadius: msg.role === 'user' ? '20px 20px 4px 20px' : '20px 20px 20px 4px',
                                        background: msg.role === 'user' ? 'var(--primary-600)' : 'rgba(255,255,255,0.08)',
                                        color: 'white',
                                        fontSize: isMobile ? '13px' : '14px',
                                        fontWeight: '500',
                                        lineHeight: 1.5,
                                        boxShadow: '0 4px 12px rgba(0,0,0,0.1)',
                                        border: msg.role === 'user' ? 'none' : '1px solid rgba(255,255,255,0.1)',
                                        wordBreak: 'break-word',
                                        overflowWrap: 'anywhere'
                                    }}>
                                        <ReactMarkdown>{msg.content}</ReactMarkdown>
                                    </div>
                                    <span style={{ fontSize: '10px', color: 'rgba(255,255,255,0.3)', textAlign: msg.role === 'user' ? 'right' : 'left', display: 'flex', alignItems: 'center', gap: '4px', justifyContent: msg.role === 'user' ? 'flex-end' : 'flex-start' }}>
                                        {msg.role === 'assistant' && <Sparkles size={10} style={{ color: 'var(--primary-400)' }} />}
                                        {msg.role === 'user' ? 'Student' : 'Lab Assistant'}
                                    </span>
                                </div>
                            ))}
                            {sending && (
                                <div style={{ alignSelf: 'flex-start', padding: '12px', display: 'flex', gap: '8px' }}>
                                    <div className="typing-dot" style={{ width: '8px', height: '8px', borderRadius: '50%', background: 'var(--primary-500)', opacity: 0.6 }}></div>
                                    <div className="typing-dot" style={{ width: '8px', height: '8px', borderRadius: '50%', background: 'var(--primary-500)', opacity: 0.6, animationDelay: '0.2s' }}></div>
                                    <div className="typing-dot" style={{ width: '8px', height: '8px', borderRadius: '50%', background: 'var(--primary-500)', opacity: 0.6, animationDelay: '0.4s' }}></div>
                                </div>
                            )}
                            <div ref={chatEndRef} />
                        </div>

                        {/* Input Area */}
                        <div style={{ padding: isMobile ? 'var(--space-md)' : 'var(--space-lg)', borderTop: '1px solid rgba(255,255,255,0.05)' }}>
                            <form onSubmit={handleSendMessage} style={{ position: 'relative' }}>
                                <textarea 
                                    value={input}
                                    onChange={(e) => setInput(e.target.value)}
                                    placeholder="Ask anything about this material..."
                                    style={{ 
                                        width: '100%', 
                                        padding: '16px 56px 16px 16px', 
                                        background: 'rgba(255,255,255,0.05)', 
                                        border: '1px solid rgba(255,255,255,0.1)',
                                        borderRadius: 'var(--radius-lg)',
                                        color: 'white',
                                        fontSize: 'var(--text-sm)',
                                        resize: 'none',
                                        minHeight: '60px',
                                        maxHeight: '150px',
                                        outline: 'none',
                                        transition: 'border-color 0.2s'
                                    }}
                                    onKeyDown={(e) => {
                                        if (e.key === 'Enter' && !e.shiftKey) {
                                            e.preventDefault();
                                            handleSendMessage();
                                        }
                                    }}
                                />
                                <button 
                                    type="submit"
                                    disabled={!input.trim() || sending}
                                    style={{ 
                                        position: 'absolute', 
                                        right: '12px', 
                                        bottom: '12px', 
                                        width: '36px', 
                                        height: '36px', 
                                        borderRadius: 'var(--radius-md)', 
                                        background: 'var(--primary-500)', 
                                        border: 'none', 
                                        color: 'white', 
                                        display: 'flex', 
                                        alignItems: 'center', 
                                        justifyContent: 'center', 
                                        cursor: 'pointer',
                                        opacity: (!input.trim() || sending) ? 0.5 : 1,
                                        transition: 'transform 0.2s'
                                    }}
                                >
                                    <Send size={18} />
                                </button>
                            </form>
                        </div>
                    </div>
                )}
            </main>

            <style>{`
                .lab-content h1, .lab-content h2, .lab-content h3 { color: white; margin-top: var(--space-lg); }
                .lab-content p { margin-bottom: var(--space-md); }
                .lab-content code { background: rgba(255,255,255,0.1); padding: 2px 4px; borderRadius: 4px; }
                .lab-content pre { background: rgba(0,0,0,0.3); padding: var(--space-md); borderRadius: var(--radius-md); overflow-x: auto; }
                
                @keyframes typing {
                    0%, 100% { transform: translateY(0); }
                    50% { transform: translateY(-5px); }
                }
                .typing-dot { animation: typing 1s infinite ease-in-out; }
            `}</style>
        </div>
    );
};

export default StudyLab;

import { useState, useEffect, useRef } from 'react';
import { useAuth } from '../../context/AuthContext';
import { routineService } from '../../services/routineService';
import { manageRoutinesChat } from '../../services/aiService';
import { supabase } from '../../lib/supabase';
import { Card, Badge, Button, Input, LoadingSpinner } from '../../components/common';
import { 
    Calendar, Sparkles, Send, Clock, 
    MessageSquare, Brain, RefreshCw, ChevronLeft, ChevronRight,
    User, Bot, CheckCircle, AlertTriangle, Zap
} from 'lucide-react';
import { format12h, getLocalDatePickerDate } from '../../utils/timeFormat';

const Timetable = () => {
    const { user } = useAuth();
    const [loading, setLoading] = useState(true);
    const [sending, setSending] = useState(false);
    const [routines, setRoutines] = useState([]);
    const [todayLogs, setTodayLogs] = useState([]);
    const [messages, setMessages] = useState([
        { role: 'assistant', content: "Hello! I'm your AI Scheduling Architect. How can I help you organize your week? You can say things like 'Add DSA study at 8am on weekdays' or 'Clear my Wednesday afternoon'." }
    ]);
    const [userInput, setUserInput] = useState('');
    const [isMobile, setIsMobile] = useState(window.innerWidth < 1024);
    const chatEndRef = useRef(null);

    useEffect(() => {
        const handleResize = () => setIsMobile(window.innerWidth < 1024);
        window.addEventListener('resize', handleResize);
        return () => window.removeEventListener('resize', handleResize);
    }, []);

    useEffect(() => {
        fetchRoutines();
    }, [user?.id]);

    useEffect(() => {
        chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
        if (messages.length > 1) {
            saveChatHistory(messages);
        }
    }, [messages]);

    useEffect(() => {
        if (user?.id) {
            fetchChatHistory();
        }
    }, [user?.id]);

    const fetchChatHistory = async () => {
        try {
            const { data } = await supabase
                .from('ai_history')
                .select('*')
                .eq('user_id', user.id)
                .eq('tool', 'timetable_architect')
                .maybeSingle();

            if (data?.content?.messages) {
                setMessages(data.content.messages);
            }
        } catch (err) {
            console.error('Error fetching chat history:', err);
        }
    };

    const saveChatHistory = async (newMessages) => {
        try {
            await supabase.from('ai_history').upsert({
                user_id: user.id,
                tool: 'timetable_architect',
                title: 'Main Timetable Chat',
                content: { messages: newMessages }
            }, { onConflict: 'user_id,tool,title' });
        } catch (err) {
            console.error('Error saving chat history:', err);
        }
    };

    const fetchRoutines = async () => {
        if (!user?.id) return;
        setLoading(true);
        try {
            const [routineData, logData] = await Promise.all([
                routineService.getRoutines(),
                routineService.getLogsForDate(getLocalDatePickerDate())
            ]);
            setRoutines(routineData);
            setTodayLogs(logData);
        } catch (err) {
            console.error('Failed to fetch routines:', err);
        } finally {
            setLoading(false);
        }
    };

    const handleSendMessage = async (e) => {
        e.preventDefault();
        if (!userInput.trim() || sending) return;

        const userMsg = userInput;
        setUserInput('');
        setMessages(prev => [...prev, { role: 'user', content: userMsg }]);
        setSending(true);

        try {
            const response = await manageRoutinesChat(
                [...messages, { role: 'user', content: userMsg }],
                routines,
                todayLogs
            );

            // Robust Split: Find metadata marker anywhere or try to extract JSON
            let text = response;
            let metadataStr = '';
            
            if (response.includes('---METADATA---')) {
                const parts = response.split('---METADATA---');
                text = parts[0];
                metadataStr = parts[1];
            } else if (response.includes('{"routines":')) {
                // Fallback: Try to find start of JSON if marker is missing
                const jsonStart = response.indexOf('{"routines":');
                text = response.substring(0, jsonStart);
                metadataStr = response.substring(jsonStart);
            }
            
            if (metadataStr) {
                try {
                    // Clean metadata string from markdown blocks
                    let cleanedMetadata = metadataStr.trim();
                    if (cleanedMetadata.startsWith('```')) {
                        const lines = cleanedMetadata.split('\n');
                        if (lines[0].startsWith('```')) lines.shift();
                        if (lines[lines.length - 1].startsWith('```')) lines.pop();
                        cleanedMetadata = lines.join('\n').trim();
                    }

                    const metadata = JSON.parse(cleanedMetadata);
                    console.log('Processed AI Metadata:', metadata);
                    
                    // 1. Sync Timetable (Routines)
                    if (metadata.routines) {
                        await routineService.replaceAllRoutines(metadata.routines);
                    }
                    
                    // 2. Perform Log Actions (Today's instances)
                    if (metadata.logUpdates) {
                        for (const update of metadata.logUpdates) {
                            await routineService.logRoutineProgress(update.routine_id, {
                                status: update.status,
                                learning_notes: update.notes || `Updated via AI: ${userMsg}`
                            });
                        }
                    }

                    await fetchRoutines(); // Refresh UI
                } catch (e) {
                    console.error("Failed to parse AI metadata:", e);
                    console.error("Raw metadata string was:", metadataStr);
                }
            }

            setMessages(prev => [...prev, { role: 'assistant', content: text.trim() }]);
        } catch (err) {
            setMessages(prev => [...prev, { role: 'assistant', content: "Sorry, I encountered an error while updating your schedule. " + err.message }]);
        } finally {
            setSending(false);
        }
    };

    const days = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'];
    const daysMap = { 'Monday': 1, 'Tuesday': 2, 'Wednesday': 3, 'Thursday': 4, 'Friday': 5, 'Saturday': 6, 'Sunday': 7 };

    return (
        <div className="page-content animate-fade-in" style={{ height: 'calc(100vh - 100px)', display: 'flex', flexDirection: 'column' }}>
            <div className="flex justify-between items-center mb-lg">
                <div>
                    <h1 style={{ margin: 0, display: 'flex', alignItems: 'center', gap: '12px', fontSize: isMobile ? 'var(--text-xl)' : 'var(--text-4xl)' }}>
                        <Brain className="text-primary-500" /> {isMobile ? 'AI Planner' : 'AI Scheduling Architect'}
                    </h1>
                    <p style={{ color: 'var(--text-muted)', margin: 0, fontSize: isMobile ? '10px' : 'var(--text-sm)' }}>Natural language timetable management</p>
                </div>
                <div style={{ display: 'flex', gap: 'var(--space-sm)' }}>
                    <Button variant="ghost" icon={Calendar} onClick={() => {
                        const icsContent = routineService.generateICS(routines);
                        const blob = new Blob([icsContent], { type: 'text/calendar;charset=utf-8' });
                        const link = document.createElement('a');
                        link.href = window.URL.createObjectURL(blob);
                        link.setAttribute('download', 'zenith_routines.ics');
                        document.body.appendChild(link);
                        link.click();
                        document.body.removeChild(link);
                    }}>Export to Calendar</Button>
                    <Badge variant="primary" icon={RefreshCw}>Live Sync Active</Badge>
                </div>
            </div>

            <div style={{ 
                display: 'flex', 
                flexDirection: isMobile ? 'column' : 'row', 
                gap: 'var(--space-lg)', 
                flex: 1, 
                minHeight: 0,
                overflowY: 'auto'
            }}>
                {/* Chat Column */}
                <Card style={{ 
                    display: 'flex', 
                    flexDirection: 'column', 
                    padding: 0, 
                    overflow: 'hidden', 
                    border: '1px solid var(--border)',
                    width: isMobile ? '100%' : '350px',
                    height: isMobile ? '500px' : 'auto',
                    flexShrink: 0,
                    boxShadow: 'var(--shadow-lg)',
                    borderRadius: 'var(--radius-xl)'
                }}>
                    <div style={{ padding: 'var(--space-md)', borderBottom: '1px solid var(--border)', background: 'rgba(99, 102, 241, 0.05)' }}>
                        <h3 style={{ margin: 0, fontSize: 'var(--text-sm)', display: 'flex', alignItems: 'center', gap: '8px', color: 'var(--primary-500)' }}>
                            <Sparkles size={16} /> Strategy & Planning
                        </h3>
                    </div>
                    
                    <div style={{ flex: 1, overflowY: 'auto', padding: 'var(--space-md)', display: 'flex', flexDirection: 'column', gap: 'var(--space-sm)' }}>
                        {messages.map((msg, i) => (
                            <div key={i} style={{ 
                                alignSelf: msg.role === 'user' ? 'flex-end' : 'flex-start',
                                maxWidth: '90%',
                                display: 'flex',
                                flexDirection: 'column',
                                gap: '2px'
                            }}>
                                <div style={{ 
                                    padding: '10px 14px', 
                                    borderRadius: msg.role === 'user' ? '18px 18px 2px 18px' : '18px 18px 18px 2px',
                                    background: msg.role === 'user' ? 'var(--primary-600)' : 'var(--surface)',
                                    color: msg.role === 'user' ? 'white' : 'var(--text)',
                                    fontSize: '13px',
                                    fontWeight: '500',
                                    boxShadow: 'var(--shadow-sm)',
                                    border: msg.role === 'user' ? 'none' : '1px solid var(--border)',
                                    wordBreak: 'break-word',
                                    lineHeight: '1.4'
                                }}>
                                    {msg.content}
                                </div>
                                <span style={{ fontSize: '9px', color: 'var(--text-muted)', textAlign: msg.role === 'user' ? 'right' : 'left', margin: '0 4px' }}>
                                    {msg.role === 'user' ? 'You' : 'Architect'}
                                </span>
                            </div>
                        ))}
                        {sending && (
                            <div style={{ alignSelf: 'flex-start', padding: '10px 14px', background: 'var(--surface)', borderRadius: '18px 18px 18px 2px', border: '1px solid var(--border)' }}>
                                <LoadingSpinner size="sm" />
                            </div>
                        )}
                        <div ref={chatEndRef} />
                    </div>

                    <form onSubmit={handleSendMessage} style={{ padding: 'var(--space-md)', borderTop: '1px solid var(--border)', background: 'var(--surface)' }}>
                        <div className="flex gap-sm">
                            <Input 
                                placeholder="e.g. Add 2h study every Mon" 
                                value={userInput} 
                                onChange={e => setUserInput(e.target.value)}
                                disabled={sending}
                                style={{ margin: 0, borderRadius: 'var(--radius-full)' }}
                            />
                            <Button variant="primary" type="submit" disabled={sending || !userInput.trim()} style={{ borderRadius: 'var(--radius-full)', width: '42px', height: '42px', padding: 0 }}>
                                <Send size={18} />
                            </Button>
                        </div>
                    </form>
                </Card>

                {/* Timetable View */}
                <div style={{ flex: 1, minWidth: 0, paddingRight: '4px' }}>
                    <Card style={{ marginBottom: 'var(--space-md)', background: 'linear-gradient(135deg, var(--surface) 0%, var(--bg) 100%)', border: '1px solid var(--primary-500)' }}>
                        <div className="flex justify-between items-center">
                            <div className="flex items-center gap-md">
                                <RefreshCw className="text-primary-500 animate-spin-slow" />
                                <div>
                                    <h3 style={{ margin: 0, fontSize: 'var(--text-sm)' }}>Live Calendar Sync</h3>
                                    <p style={{ margin: 0, fontSize: 'var(--text-xs)', color: 'var(--text-muted)' }}>
                                        Subscribe once, and your phone calendar will auto-update with the AI's plan.
                                    </p>
                                </div>
                            </div>
                            <Button variant="primary" size="sm" onClick={() => {
                                const link = routineService.getCalendarSyncLink(user.id);
                                navigator.clipboard.writeText(link);
                                alert('Sync Link Copied! \n\nPaste this into Google Calendar -> "Add by URL" to sync Zenith with your phone.');
                            }}>Copy Sync Link</Button>
                        </div>
                    </Card>

                    {loading ? (
                        <div className="flex justify-center p-2xl"><LoadingSpinner size="lg" /></div>
                    ) : (
                        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: 'var(--space-md)' }}>
                            {days.map(day => {
                                const dayNum = daysMap[day];
                                const dayRoutines = routines.filter(r => r.days_of_week.includes(dayNum))
                                    .sort((a,b) => a.start_time.localeCompare(b.start_time));

                                return (
                                    <Card key={day} style={{ display: 'flex', flexDirection: 'column', minHeight: '150px' }}>
                                        <div className="flex justify-between items-center mb-md">
                                            <h3 style={{ margin: 0, fontSize: 'var(--text-sm)', fontWeight: 800 }}>{day}</h3>
                                            <Badge variant={dayRoutines.length > 0 ? 'primary' : 'secondary'} size="xs">{dayRoutines.length}</Badge>
                                        </div>
                                        <div style={{ display: 'flex', flexDirection: 'column', gap: '6px' }}>
                                            {dayRoutines.map((r, i) => (
                                                <div key={i} style={{ 
                                                    padding: '8px', 
                                                    background: 'var(--bg)', 
                                                    borderRadius: '8px',
                                                    borderLeft: '3px solid var(--primary-500)',
                                                    fontSize: '11px'
                                                }}>
                                                    <div style={{ color: 'var(--primary-500)', fontWeight: 700, marginBottom: '2px', display: 'flex', alignItems: 'center', gap: '4px' }}>
                                                        {r.is_anonymous ? <Zap size={10} fill="currentColor" /> : <Clock size={10} />}
                                                        {r.is_anonymous ? 'Flexible' : format12h(r.start_time)}
                                                    </div>
                                                    <div style={{ fontWeight: 600 }}>{r.title}</div>
                                                </div>
                                            ))}
                                            {dayRoutines.length === 0 && (
                                                <div style={{ flex: 1, display: 'flex', alignItems: 'center', justifyContent: 'center', color: 'var(--text-muted)', fontSize: '10px', fontStyle: 'italic', height: '60px' }}>
                                                    Free Day
                                                </div>
                                            )}
                                        </div>
                                    </Card>
                                );
                            })}
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

export default Timetable;

import { useState, useEffect, useCallback } from 'react';
import { Card, Button, Badge, Input, Modal } from '../../components/common';
import { 
    BookOpen, 
    Plus, 
    Trash2, 
    Search, 
    Tag, 
    Info, 
    Brain,
    Database,
    Clock,
    FileText,
    Sparkles,
    Layout,
    Link as LinkIcon,
    Upload,
    File,
    ExternalLink,
    Download
} from 'lucide-react';
import * as db from '../../services/database';
import { useAuth } from '../../context/AuthContext';
import { supabase } from '../../lib/supabase';
import { formatDate } from '../../utils/constants';

const KnowledgeBase = () => {
    const { user } = useAuth();
    const [knowledge, setKnowledge] = useState([]);
    const [loading, setLoading] = useState(true);
    const [searchQuery, setSearchQuery] = useState('');
    const [showAddModal, setShowAddModal] = useState(false);
    const [newSnippet, setNewSnippet] = useState({
        title: '',
        content: '',
        tags: '',
        subject: '',
        classroom_id: '',
        material_type: 'file', // 'file', 'link', 'text'
        file: null,
        url: ''
    });
    const [classrooms, setClassrooms] = useState([]);
    const [saving, setSaving] = useState(false);

    const loadData = useCallback(async () => {
        try {
            setLoading(true);

            // Safety timeout to prevent infinite loading
            const safetyTimeout = setTimeout(() => {
                if (loading) {
                    console.warn('KnowledgeBase load taking too long, forcing loading to false');
                    setLoading(false);
                }
            }, 8000);
            const [data, classes] = await Promise.all([
                db.getKnowledgeBase(user?.role === 'member' ? user.classroom_id : null),
                db.getClassrooms()
            ]);
            setKnowledge(data);
            setClassrooms(classes);
            
            // Set default classroom if available
            if (classes.length > 0) {
                setNewSnippet(prev => ({ ...prev, classroom_id: classes[0].id }));
            }
        } catch (error) {
            console.error('Error loading knowledge base:', error);
        } finally {
            setLoading(false);
        }
    }, [user?.role, user?.classroom_id]);

    useEffect(() => {
        loadData();
    }, [loadData]);

    const handleAddSnippet = async (e) => {
        e.preventDefault();
        if (!newSnippet.title) return;
        if (newSnippet.material_type === 'text' && !newSnippet.content) return;
        if (newSnippet.material_type === 'link' && !newSnippet.url) return;
        if (newSnippet.material_type === 'file' && !newSnippet.file) return;

        setSaving(true);
        try {
            let file_url = newSnippet.url;
            if (newSnippet.material_type === 'file' && newSnippet.file) {
                file_url = await db.uploadStudyMaterial(newSnippet.file);
            }

            const tagsArray = newSnippet.tags.split(',').map(t => t.trim()).filter(t => t !== '');
            const material = await db.addKnowledgeSnippet({
                title: newSnippet.title,
                content: newSnippet.content || 'Attached Material',
                subject: newSnippet.subject,
                classroom_id: newSnippet.classroom_id,
                tags: tagsArray,
                material_type: newSnippet.material_type,
                file_url: file_url
            });

            // --- NOTIFY STUDENTS IN CLASSROOM (BATCH) ---
            try {
                const { data: profiles } = await supabase
                    .from('profiles')
                    .select('id, preferences')
                    .eq('classroom_id', newSnippet.classroom_id)
                    .eq('role', 'member');

                if (profiles && profiles.length > 0) {
                    const userIds = profiles.map(p => p.id).filter(Boolean);
                    const oneSignalIds = profiles.map(p => p.preferences?.onesignal_id).filter(Boolean);

                    if (userIds.length > 0 || oneSignalIds.length > 0) {
                        await fetch(`${window.location.origin}/api/push`, {
                            method: 'POST',
                            headers: { 'Content-Type': 'application/json' },
                            body: JSON.stringify({
                                user_ids: userIds,
                                onesignal_ids: oneSignalIds,
                                title: 'New Learning Resource! 📚',
                                body: `"${newSnippet.title}" has been shared in ${newSnippet.subject || 'your classroom'}.`,
                                data: {
                                    type: 'knowledge_snippet',
                                    id: material.id,
                                    classroom_id: newSnippet.classroom_id,
                                    url: '/knowledge-base'
                                }
                            })
                        });
                    }
                }
            } catch (notifyErr) {
                console.error('Failed to send notifications:', notifyErr);
            }

            setShowAddModal(false);
            setNewSnippet({ title: '', content: '', tags: '', subject: '', classroom_id: classrooms[0]?.id || '', material_type: 'file', file: null, url: '' });
            loadData();
        } catch (error) {
            console.error('Error adding snippet:', error);
            alert('Failed to add knowledge. Ensure the database table exists.');
        } finally {
            setSaving(false);
        }
    };

    const handleDeleteSnippet = async (id) => {
        if (!window.confirm('Are you sure you want to delete this knowledge snippet?')) return;
        
        try {
            await db.deleteKnowledgeSnippet(id);
            loadData();
        } catch (error) {
            console.error('Error deleting snippet:', error);
        }
    };

    const filteredKnowledge = knowledge.filter(k => 
        k.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
        k.content.toLowerCase().includes(searchQuery.toLowerCase()) ||
        k.tags?.some(t => t.toLowerCase().includes(searchQuery.toLowerCase()))
    );

    return (
        <div className="animate-fade-in">
            <div className="flex flex-mobile-col justify-between items-center mb-lg">
                <div>
                    <h2 style={{ margin: 0, display: 'flex', alignItems: 'center', gap: '12px' }}>
                        <BookOpen className="text-primary-400" />
                        Learning Resource Center
                    </h2>
                    <p style={{ color: 'var(--text-muted)', margin: 0 }}>
                        Share study resources, reference materials, and documents with your team members.
                    </p>
                </div>
                {user?.role === 'admin' && (
                    <Button variant="primary" icon={Plus} onClick={() => setShowAddModal(true)}>
                        Add Material
                    </Button>
                )}
            </div>

            <Card style={{ marginBottom: 'var(--space-lg)', padding: 'var(--space-md)' }}>
                <div className="flex items-center gap-md">
                    <Search className="text-muted" size={20} />
                    <Input 
                        placeholder="Search knowledge by title, content or tags..."
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
