// Save AI History
export const saveHistory = async (tool, content, title = '', model = null) => {
    try {
        const { data: { user } } = await supabase.auth.getUser();
        if (!user) return null;

        const { data, error } = await supabase
            .from('ai_history')
            .insert({
                user_id: user.id,
                tool,
                content,
                title: title || `New ${tool} session`,
                model_used: model
            })
            .select()
            .single();

        if (error) throw error;
        return data;
    } catch (error) {
        console.error('Failed to save AI history:', error);
        return null;
    }
};

// Get AI History for a specific tool
export const getHistory = async (tool) => {
    try {
        const { data: { user } } = await supabase.auth.getUser();
        if (!user) return [];

        const { data, error } = await supabase
            .from('ai_history')
            .select('*')
            .eq('user_id', user.id)
            .eq('tool', tool)
            .order('created_at', { ascending: false });

        if (error) throw error;
        return data;
    } catch (error) {
        console.error('Failed to fetch AI history:', error);
        return [];
    }
};

// Delete specific history item
export const deleteHistoryItem = async (id) => {
    try {
        const { error } = await supabase
            .from('ai_history')
            .delete()
            .eq('id', id);

        if (error) throw error;
        return true;
    } catch (error) {
        console.error('Failed to delete history item:', error);
        return false;
    }
};

// Update specific history item
export const updateHistory = async (id, content) => {
    try {
        const { error } = await supabase
            .from('ai_history')
            .update({ content })
            .eq('id', id);

        if (error) throw error;
        return true;
    } catch (error) {
        console.error('Failed to update history item:', error);
        return false;
    }
};

